window.DOSIK=window.DOSIK||{};DOSIK["sm_tax"]={"1":[{"t":"table","title":"납세의무와 제척기간","head":["항목","내용"],"rows":[["납세의무자","연대납세의무자, 제2차 납세의무자, 보증인이 들어가고 원천징수의무자는 빠진다"],["소득세·법인세·부가가치세 성립","과세기간이 끝나는 때"],["원천징수하는 소득세·법인세 성립","소득금액을 지급하는 때"],["종합부동산세 성립","과세기준일"],["상속세 성립","상속이 개시되는 때"],["신고로 확정","소득세·법인세·부가가치세·교통·에너지·환경세 등은 신고로 확정된다"],["정부가 결정하는 때 확정","상속세·증여세는 신고와 관계없이 정부가 결정하는 때 확정된다"],["성립과 동시에 확정","인지세, 원천징수하는 소득세·법인세, 납세조합 징수 소득세, 중간예납 법인세(정부가 조사·결정하는 경우 제외)"],["일반 부과제척기간","일반 5년, 무신고 7년, 부정행위 10년(역외거래 부정행위 15년)"],["상속세·증여세 제척기간","10년, 부정행위·무신고·거짓신고는 15년이다"],["부정 포탈 재산가액이 50억원을 넘으면","제3자 명의 재산 취득 등으로 부정 포탈한 재산가액이 50억원을 넘으면 상속·증여가 있음을 안 날부터 1년 이내에 부과할 수 있다"],["제척기간이 지나도 경정","경정청구가 있으면 경정청구일부터 2개월, 불복 결정·판결이 확정되면 확정된 날부터 1년 안에 경정할 수 있다"],["명의대여","판결로 확정되면 1년 이내에 실제 사업자에게 처분할 수 있다"]]},{"t":"table","title":"소멸시효·수정신고·연대납세의무","head":["항목","내용"],"rows":[["국세징수권과 국세환급금 청구권","행사할 수 있는 때부터 5년이다"],["신고 확정 세목의 기산","법정 신고납부기한의 다음 날, 기한이 연장되면 연장된 기한의 다음 날부터 행사할 수 있다"],["중단 사유","납부고지·독촉·교부청구·압류는 중단 사유이나 압류금지재산을 압류해 즉시 해제한 경우는 중단되지 않는다"],["시효 정지","분납·징수유예·사해행위 취소소송 진행·6개월 이상 국외 체류 기간에는 시효가 정지된다"],["수정신고","당초 신고한 세액을 증액하여 확정하는 효력이 있다"],["경정청구","과다신고한 자(기한후신고자 포함)는 법정신고기한이 지난 후 5년 이내에 경정을 청구하고, 결정·경정으로 증가한 세액은 처분을 안 날부터 3개월 이내(5년 한도)에 청구한다"],["후발적 사유","계약 해제 같은 후발적 사유는 안 날부터 3개월 이내이며, 상속세·증여세도 경정청구 대상이다"],["분할법인이 존속하면","분할신설법인 등은 분할등기일 이전에 성립한 국세에 연대납세의무를 진다"],["분할법인이 소멸하면","승계재산 가액을 한도로 연대한다"],["해산법인","국세를 내지 않고 잔여재산을 분배하면 청산인과 분배받은 자는 제2차 납세의무를 진다"],["사업양수인","양도일 이전에 확정된 그 사업의 국세에 대해 양수재산 가액 한도로 제2차 납세의무를 진다"]]},{"t":"table","title":"서류 송달과 가산세","head":["항목","내용"],"rows":[["납부고지서","등기우편이 원칙이지만 중간예납세액 등 고지금액 100만원 미만은 일반우편으로 보낼 수 있다(2026.2. 시행령 개정 전 50만원)"],["수취인 부재를 이유로 한 공시송달","2회 이상 방문하고 처음과 마지막 방문 사이가 3일 이상이어야 한다"],["구속·유치된 사람","교정시설의 장 등에게 송달한다"],["연대납세의무자","고지·독촉 서류를 각각 송달한다"],["무신고가산세","20%, 부정행위 무신고는 40%(역외거래 60%)"],["과소신고가산세","10%, 부정 과소신고는 40%이다"],["납부지연가산세","미납세액에 1일 10만분의 22를 곱하고 지정납부기한까지 내지 않으면 3%를 더한다"],["감면","법정신고기한 후 1개월 이내 수정신고는 과소신고가산세의 90%, 1개월 이내 기한후신고는 무신고가산세의 50%를 감면하고, 정당한 사유가 있으면 부과하지 않는다"]]},{"t":"table","title":"불복과 세무조사","head":["항목","내용"],"rows":[["이의신청·심사청구·심판청구","처분을 안 날부터 90일 이내에 하고, 처분으로 권리나 이익을 침해당하지 않은 자의 청구는 각하한다"],["조세심판관합동회의","구성원 3분의 2 이상 출석, 출석 과반수 찬성으로 의결한다"],["같은 세목·과세기간 재조사","금품 제공, 부분조사 후 나머지 조사 등 법정 사유가 있어야 한다"],["탈세 제보 확인 부분조사","2회를 넘길 수 없다"]]}],"2":[{"t":"table","title":"징수 순위와 납부고지","head":["항목","내용"],"rows":[["징수 순위","체납액은 강제징수비, 가산세를 제외한 국세, 가산세의 순으로 징수한다"],["납부고지서의 납부기한","고지하는 날부터 30일 이내로 정한다"],["독촉장","독촉하는 날부터 20일 이내의 범위에서 기한을 정해 발급한다"],["결정·경정을 납부고지서로 통지","그 고지는 부과처분과 징수처분의 성질을 함께 가진다"],["제2차 납세의무자, 보증인, 물적납세의무자","징수할 때도 납부고지서를 발급한다"],["지정납부기한이 지난 후의 납부지연가산세","징수할 때는 납부고지서를 발급하지 않을 수 있다"],["납부기한 전 징수","강제징수·경매 개시, 법인 해산, 국세 포탈 행위, 납세관리인 없이 국내 주소·거소를 두지 않게 된 경우 등에는 납부기한 전이라도 이미 납세의무가 확정된 국세를 징수할 수 있다"],["납부기한 전 징수의 대상","원천징수한 국세도 대상이고, 성립만 하고 확정되지 않은 세액은 대상이 아니다"],["단축된 기한까지 내지 않으면","독촉 없이 압류한다"]]},{"t":"table","title":"기한 연장과 납세담보","head":["항목","내용"],"rows":[["연장 사유","재난·도난, 질병, 사업의 중대한 위기, 장부 작성을 대행하는 세무사의 장부 도난 등"],["신청","기한 만료일 10일 전까지 신청했는데 10일 이내에 통지가 없으면 승인한 것으로 본다"],["담보 요구","재난·도난 손실이 아니면 담보를 요구할 수 있다"],["유예 취소","재산 상황 변동으로 유예를 취소했으면 다시 유예할 수 있다"],["유예기간","소멸시효가 진행되지 않고 교부청구는 할 수 있다"],["납세담보 제공액","담보할 국세의 120% 이상을 제공하고, 금전·납세보증보험증권·은행 납세보증서는 110% 이상이다"],["유가증권","양도성 예금증서도 담보로 쓰는 유가증권이다"],["납세보증보험증권","보험기간이 담보가 필요한 기간에 30일을 더한 기간 이상이어야 한다"],["금전을 담보로 낸 자","그 금전으로 국세를 납부할 수 있다"]]},{"t":"table","title":"압류","head":["항목","내용"],"rows":[["채권 압류","제3채무자에게 통지하고 그 통지서가 제3채무자에게 송달된 때 효력이 생기며 체납자에게는 압류 후 통지한다"],["동산·유가증권","세무공무원이 점유한 때 효력이 생긴다"],["예탁유가증권","예탁결제원에 송달된 때 효력이 생긴다"],["부동산 압류","소유권 이전 전에 법정기일이 도래한 국세에도 미치고, 이미 거두어들인 천연과실에는 미치지 않고 급료 등 계속적 채권은 압류 후 발생분에도 미친다"],["채권 압류의 범위","체납액을 한도로 압류하나 우선 질권 등으로 징수가 불확실하면 전액을 압류할 수 있다"],["제3자 재산이나 압류금지재산","압류했으면 즉시 해제한다"],["가압류·가처분 재산","강제징수하고 법인이 합병으로 소멸해도 강제징수를 계속한다"],["선행압류가 해제되면","참가압류는 등기재산의 경우 참가압류 등기가 완료된 때로 소급해 효력이 생긴다"]]},{"t":"table","title":"공매와 행정제재","head":["항목","내용"],"rows":[["공매보증금","공매예정가격의 10% 이상이다"],["매수신청","경쟁입찰은 문서로, 경매는 구두 등으로 한다"],["체납자와 세무공무원","제3자 명의나 계산으로도 압류재산을 매수할 수 없다"],["매각으로 소멸","질권·저당권·가등기담보권은 매각으로 소멸한다"],["불복이나 행정소송 진행 중","결정·판결 확정 전에 공매할 수 없으나 부패·감량되기 쉬운 재산은 예외이다"],["명단 공개와 수입물품 강제징수의 세관장 위탁","체납 발생일부터 1년이 지난 국세가 2억원 이상일 때 할 수 있고, 불복이 계속 중이면 공개하지 않는다"],["감치","3회 이상 체납, 각 1년 경과, 합계 2억원 이상 등을 갖추면 법원이 30일 범위에서 결정한다"],["출국금지","5천만원 이상 체납자 중 요건을 갖춘 자에 대해 요청해야 한다"],["사업정지","허가사업 관련 세금을 3회 이상·500만원 이상 체납하면 요구할 수 있다"],["열람","보증금 1천만원 초과 임차인은 임대인 동의 없이 미납국세를 열람할 수 있다"]]}],"3":[{"t":"table","title":"과세소득과 비영리법인","head":["항목","내용"],"rows":[["영리내국법인","각 사업연도 소득, 청산소득, 토지등 양도소득, 미환류소득에 과세된다"],["비영리내국법인","청산소득 납세의무가 없다"],["비영리외국법인","국내원천소득 중 수익사업 소득에만 과세된다"],["수익사업 소득에 들어가는 것","주식·출자지분 양도 수입과 유형·무형자산 처분 수입"],["수익사업 소득에서 빠지는 것","처분일 현재 3년 이상 계속 고유목적사업에 직접 쓴 자산의 처분 수입"],["구분경리","수익사업을 하면 자산·부채·손익을 다른 회계로 구분경리해야 한다"],["수익사업을 하지 않는 비영리내국법인","토지 등 양도소득을 양도소득세 방식으로 내고 과세표준 신고를 생략할 수 있다"],["수익사업을 하는 비영리법인","토지 양도소득도 과세표준 신고를 한다"],["고유목적사업준비금","한도 안에서 손금에 넣고, 손금산입한 사업연도 종료일 이후 5년이 되는 날까지 쓰지 않으면 익금에 산입한다"]]},{"t":"table","title":"사업연도와 소득처분","head":["항목","내용"],"rows":[["사업연도","1년을 넘지 못하고, 변경하려면 직전 사업연도 종료일부터 3개월 이내에 신고한다"],["변경 사업연도","종전 개시일부터 변경 후 개시일 전날까지가 1개월 미만이면 변경된 사업연도에 포함한다"],["분할로 해산","개시일부터 분할등기일까지가 1사업연도이다"],["귀속이 불분명한 사외유출","대표자 상여로 처분하고, 그 소득세를 법인이 대납해 손비로 처리한 금액은 기타사외유출이다"],["추계 과세표준과 당기순이익의 차액","대표자 상여(천재지변 장부 멸실은 기타사외유출)이며 기부금 한도초과액도 기타사외유출이다"],["사업연도 중 대표자가 바뀌고 귀속이 불분명","재직 일수로 나누어 각자에게 상여 처분한다"]]},{"t":"table","title":"익금과 익금불산입","head":["항목","내용"],"rows":[["익금","자본 납입 등을 빼고 순자산을 늘리는 거래의 수익이다"],["유가증권 저가매입","특수관계인인 개인에게서 시가보다 싸게 사면 차액이 익금이고, 국세 환급가산금은 익금이 아니다"],["자산수증이익·채무면제이익","이월결손금 보전에 충당한 금액만 익금불산입한다"],["출자전환 채무면제이익","회생계획인가 법인 등만 이후 결손금 보전에 쓰도록 이연할 수 있다"],["내국법인 배당","출자비율 50% 이상 100%, 20% 이상 50% 미만 80%, 20% 미만 30%를 익금불산입한다"],["외국자회사 배당","의결권 있는 주식 10%(해외자원개발 5%) 이상을 가진 외국자회사의 배당은 95%를 익금불산입하나 간접투자회사등은 제외한다"],["익금에 산입","특정외국법인 유보소득 간주배당과 혼성금융상품 배당"]]},{"t":"table","title":"의제배당과 결산조정","head":["항목","내용"],"rows":[["의제배당 무상주","이익잉여금, 자기주식처분이익, 소각일부터 2년 안의 자기주식소각이익, 재평가세 1% 토지분 재평가적립금을 자본전입해 받은 무상주는 의제배당이다"],["주식발행초과금","의제배당이 아니나, 출자전환 때 시가를 넘어 발행된 금액은 의제배당이다"],["자기주식에 배정할 무상주","다른 주주에게 주면 지분율이 늘어난 부분은 재원과 관계없이 의제배당이다"],["익금 항목","장부 계상과 관계없이 신고조정으로 산입한다"],["신고조정 대손","소멸시효가 완성되거나 회생계획인가·면책결정으로 회수불능이 확정된 채권은 그 사유가 생긴 사업연도에 손금산입해야 하고 뒤 사업연도에 계상해도 인정되지 않는다"],["감가상각비와 일시상각충당금","결산조정이 원칙이나 일부는 신고조정도 허용된다"]]}],"4":[{"t":"table","title":"손금","head":["항목","내용"],"rows":[["손비","법인의 사업과 관련해 발생하거나 지출된 비용으로서 일반적으로 인정되는 통상적인 것이거나 수익과 직접 관련된 것이다"],["공동사업 비용","출자비율에 따라 나누어 부담하는 것이 원칙이다"],["이익처분으로 지급하는 상여금","사전에 서면 약정한 성과배분상여금이라도 손금에 넣지 않는다"],["합명·합자회사 노무출자사원의 보수","이익처분 상여로 보아 손금불산입한다"],["퇴직급여 중간정산","정산시점부터 근무연수를 새로 기산하는 경우에만 현실적 퇴직으로 본다"],["손금에 넣지 않는 것","벌금·과료·과태료, 외국 법률에 따라 낸 벌금, 국민건강보험 연체금, 산재보험료 가산금"],["제재가 아니어서 손금","계약상 지체상금, 전기요금 연체가산금, 산재보험료 연체금, 국유지 사용료 연체료"],["회수불능 매출세액 미수금","대손세액공제를 받지 않은 것은 손금이고, 대손세액공제를 받은 부분은 손금이 아니다"],["간주임대료 부가가치세","임차인이 부담한 사실이 확인되는 전세금·임차보증금에 대한 부가가치세는 임차인의 손금이다"],["손비 인정","광업의 탐광 개발비, 우리사주조합에 출연한 자사주 장부가액, 이사회 결의로 사망 직원 유족에게 계속 주는 학자금"],["손금이 아닌 것","경상경비 외의 목적으로 내는 협회 특별회비와 할인율 변동에 따른 책임준비금 평가 증가액"]]},{"t":"table","title":"업무용승용차","head":["항목","내용"],"rows":[["업무용승용차 대상","개별소비세 과세 승용차가 대상이고, 운수업·자동차판매업 등에서 영업에 직접 쓰는 차와 연구개발용 차는 빠진다"],["업무사용금액 0원","법인 업무전용자동차보험에 가입하지 않았거나 법인 전용 번호판을 달지 않으면 업무사용금액은 0원이다"],["감가상각비","정액법·내용연수 5년으로 강제 상각한다"],["관련비용","운행기록상 업무사용비율을 곱한 금액만 손금이다"],["운행기록이 없으면","관련비용 1,500만원 이하는 전액 업무용으로 보고 초과하면 1,500만원/관련비용 비율을 쓴다"],["업무외 사용분","손금불산입하여 귀속자에 따라 상여 등으로 처분한다"]]},{"t":"table","title":"감가상각비 한도와 리스차량","head":["항목","내용"],"rows":[["감가상각비 한도","업무사용분 감가상각비(임차차량은 감가상각비 상당액)는 차량별 연 800만원을 넘는 금액을 손금불산입(보유 차량은 유보, 임차 차량은 기타사외유출)하고 이후 800만원에 미달하는 연도에 추인한다"],["처분손실","800만원을 넘는 금액은 다음 사업연도부터 800만원씩 나누어 손금에 넣는다"],["요건을 갖춘 법인","부동산임대업 주업 등 요건을 갖춘 법인은 800만원 대신 400만원, 1,500만원 대신 500만원이다"],["운용리스 차량","리스료에서 보험료·자동차세·수선유지비를 뺀 금액을 감가상각비 상당액으로 본다"],["리스차량 손금불산입","관련비용 전체에 업무외 비율을 곱한 금액을 먼저 손금불산입하고, 업무사용분 감가상각비 상당액 중 800만원 초과분을 다시 손금불산입하여 이월한다"]]}],"5":[{"t":"table","title":"손익의 귀속시기","head":["항목","내용"],"rows":[["자산 양도의 귀속시기","상품 등 외의 자산 양도는 대금청산일, 소유권이전등기일, 인도일, 사용수익일 중 빠른 날이 속하는 사업연도에 귀속한다"],["기준이 아닌 날","대금을 청산하기로 약정한 날은 기준이 아니다"],["유가증권 매매","증권시장에서 보통거래방식으로 한 유가증권 매매는 매매계약을 체결한 날이 귀속시기이다"],["건설·제조 등 용역","계약기간과 관계없이 작업진행률을 기준으로 각 사업연도의 익금과 손금에 넣는 것이 원칙이다"],["인도일이 속하는 사업연도","중소기업의 계약기간 1년 미만 건설, 기업회계기준에 따라 인도일 기준으로 계상한 경우, 작업진행률을 계산할 수 없는 경우는 인도일이 속하는 사업연도에 넣는다"],["진행률","누적 발생원가를 총공사예정원가로 나누어 구한다"],["임대료","임대료 지급기간이 1년을 넘거나 결산 때 경과기간분 임대료를 수익으로 계상하면 경과기간분을 그 사업연도의 익금으로 한다"],["이자·배당","투자회사 등이 경과기간분 이자·배당을 수익으로 계상하면 그 사업연도 익금이다"],["파생상품","목적물을 인도하지 않고 차액만 금전으로 정산하는 파생상품 손익은 대금결제일이 속하는 사업연도에 귀속한다"]]},{"t":"table","title":"취득가액","head":["항목","내용"],"rows":[["현물출자","피출자법인을 새로 설립하며 주식만 받으면 출자한 순자산의 시가가 주식 취득가액이다"],["적격합병·적격분할","받은 자산은 피합병법인·분할법인의 장부가액이 취득가액이다"],["온실가스 배출권","무상 할당받은 온실가스 배출권은 0원이다"],["동종자산 교환","동종자산과 교환한 유형자산도 취득 당시의 시가가 취득가액이다"],["국공채","유형자산을 취득하며 함께 산 국공채의 매입가액과 현재가치의 차액을 기업회계기준에 따라 유형자산 취득가액으로 계상하면 그 금액은 취득가액에 포함한다"]]},{"t":"table","title":"재고자산 평가방법","head":["항목","내용"],"rows":[["재고자산 구분","제품·상품, 반제품·재공품, 원재료, 저장품으로 구분하고 종류별·영업장별로 다른 방법을 쓸 수 있다"],["신설법인","설립일이 속하는 사업연도 신고기한까지 평가방법을 신고한다"],["변경","변경 방법을 적용할 사업연도 종료일 이전 3개월이 되는 날까지 신고한다"],["가상자산","총평균법으로 평가한다(2026.2. 시행령 개정 전 선입선출법)"],["기한 안에 신고하지 않으면","선입선출법(매매용 부동산은 개별법)으로 평가한다"],["임의 변경","신고한 방법 외의 방법으로 평가하거나 변경신고 없이 바꾸면 선입선출법 평가액과 당초 신고방법 평가액 중 큰 금액으로 평가한다"],["기한이 지나 변경신고","신고일이 속하는 사업연도까지는 종전 기준을 적용하고 그다음 사업연도부터 신고한 방법을 쓴다"]]},{"t":"table","title":"유보의 추인과 평가손실","head":["항목","내용"],"rows":[["유보의 추인","전기 유보로 세무상 취득가액이 장부가액보다 큰 자산을 처분하면 처분 비율만큼 유보를 손금산입(△유보)으로 추인한다"],["소멸시효가 완성된 매출채권","신고조정으로 손금산입하고, 지분법이익은 익금불산입한다"],["재고자산 평가손실","파손·부패 등으로 정상가격에 팔 수 없으면 처분가능한 시가로 감액할 수 있다"],["유형자산 평가손실","천재지변·화재·수용·폐광으로 파손·멸실된 경우에 시가로 감액한다"],["주식 평가손실","발행법인이 부도·파산 등 법정 사유에 해당할 때 감액할 수 있고 발행법인별 평가액이 1천원 이하이면 1천원으로 한다"]]}],"6":[{"t":"table","title":"감가상각","head":["항목","내용"],"rows":[["감가상각 시부인","회사가 계상한 감가상각비(즉시상각의제액 포함)가 상각범위액을 넘으면 상각부인액으로 손금불산입(유보)하고, 이후 시인부족액이 생기는 해에 그 범위에서 손금으로 추인한다"],["정률법 상각범위액","세무상 미상각잔액(장부가액+전기 상각부인누계액+즉시상각의제액)에 상각률을 곱해 구한다"],["상각방법을 신고하지 않으면","건축물은 정액법, 기계장치 등은 정률법을 적용한다"],["법인세를 감면받는 법인","상각범위액만큼 반드시 손금에 넣어야 해서(의무상각), 덜 계상해도 상각범위액을 손금산입한 것으로 보고 미상각잔액을 줄인다"],["즉시상각의제","자산의 가치를 늘리는 자본적 지출을 수선비 등 비용으로 처리하면 감가상각비로 계상한 것으로 보아 시부인한다"],["재해로 훼손된 자산의 복구비","비용 처리한 경우에도 감가상각비에 합산하고 상각 기초가액에도 더한다"],["소액수선비 특례","개별자산별 수선비가 600만원 미만이거나 직전 사업연도 말 재무상태표상 자산가액(취득가액-감가상각누계액)의 5% 미만이면 비용 처리한 금액을 그대로 손금으로 인정한다"],["주기적 수선","3년 미만의 기간마다 하는 주기적 수선도 같다"],["즉시 손금 처리 자산","거래단위별 취득가액 100만원 이하 자산은 사업에 쓴 날이 속하는 사업연도에 비용 처리하면 손금이다"],["휴대전화·개인용 컴퓨터","금액과 관계없이 비용 처리할 수 있다"],["임차 사업장 원상회복","시설물을 철거하면 장부가액에서 1천원을 뺀 금액을 폐기일이 속하는 사업연도의 손금에 넣을 수 있다"]]},{"t":"table","title":"대손충당금·퇴직급여충당금","head":["항목","내용"],"rows":[["대손충당금 한도","사업연도 말 설정대상 채권 장부가액에 1%와 대손실적률 중 큰 비율을 곱한 금액이다"],["대손실적률","당기 세법상 대손금을 직전 사업연도 말 채권가액으로 나눈 비율이다"],["설정대상 채권에서 빼는 것","업무무관 대여금과 특수관계인 업무무관 가지급금 등"],["퇴직급여충당금","총급여액의 5%와 추계액 기준 누적한도(2016년 이후 0%에 퇴직금전환금 가산) 중 작은 금액까지 손금이다"],["확정급여형 퇴직연금 부담금","추계액에서 세법상 퇴직급여충당금 잔액을 뺀 금액과 운용자산 잔액 중 적은 금액에서 이미 손금산입한 누적액을 뺀 범위에서 신고조정으로 손금산입한다"]]},{"t":"table","title":"일시상각·압축기장충당금","head":["항목","내용"],"rows":[["국고보조금·공사부담금·보험차익","익금이지만 같은 사업연도(또는 기한) 안에 사업용자산 취득에 쓰면 해당 금액을 손금에 넣어 과세를 이연한다"],["감가상각자산","일시상각충당금으로 계상한다"],["그 밖의 자산","압축기장충당금으로 계상한다"],["세무조정계산서에 계상","신고 때 손금산입하면 손비로 계상한 것으로 본다"],["미사용 국고보조금","손금에 넣은 국고보조금을 기한 안에 사업용자산 취득·개량에 쓰지 않거나 쓰기 전에 폐업·해산하면 쓰지 않은 금액을 그 사유가 생긴 사업연도의 익금에 산입한다"],["합병·분할로 승계","합병법인 등이 손금산입한 것으로 본다"]]}],"7":[{"t":"table","title":"부당행위계산","head":["항목","내용"],"rows":[["부당행위계산 요건","특수관계인과의 거래로 조세 부담을 부당하게 줄이면 시가로 다시 계산한다"],["적용 기준","고가매입·저가양도·금전 대여 등은 시가와 거래가액의 차액이 3억원 이상이거나 시가의 5% 이상일 때만 적용한다"],["부인으로 익금산입한 금액","귀속자에 따라 상여·배당·기타소득 등으로 처분하고 증여세를 과세하는 것이 아니다"],["고가매입","특수관계인에게서 자산을 시가보다 비싸게 사면 시가 초과액을 대가 지급 사업연도별로 손금불산입(상여 등)하고 같은 금액을 손금산입(△유보)해 취득가액을 시가로 낮춘다"],["금전 대여의 시가","가중평균차입이자율이 원칙이고, 이를 계산할 때 특수관계인에게서 빌린 차입금은 뺀다"],["당좌대출이자율","연 4.6%이다"]]},{"t":"table","title":"기부금","head":["항목","내용"],"rows":[["기부금 범위","특수관계인 외의 자에게 정당한 사유 없이 자산을 정상가액보다 낮게 양도해 실질적으로 증여한 금액도 기부금이다"],["현금주의","어음으로 지급하면 어음이 결제된 날에 지출한 것으로 본다"],["미지급으로 계상한 기부금","지급한 사업연도의 기부금이다"],["가지급금으로 이연계상한 기부금","지출한 사업연도의 기부금이다"],["특례기부금 한도","국가·지자체, 국방헌금, 이재민 구호금품, 사립학교·국립대학병원 시설비 등은 기준소득금액에서 이월결손금을 뺀 금액의 50%가 한도이다"],["일반기부금 한도","그 금액에서 특례기부금 손금산입액을 다시 뺀 금액의 10%(사회적기업 30%)가 한도이다"],["한도초과액","기타사외유출로 처분하고 10년간 이월해 당기 지출분보다 먼저 공제한다"]]},{"t":"table","title":"기업업무추진비","head":["항목","내용"],"rows":[["기업업무추진비 증빙","한 차례 접대에 3만원(경조금 20만원)을 넘게 쓰면서 신용카드·현금영수증·세금계산서 등 적격증빙을 받지 않은 금액은 한도 계산 전에 전액 손금불산입하고 기타사외유출로 처분한다"],["증빙 자체가 없거나 귀속이 불분명","대표자 상여이다"],["다른 가맹점 명의 매출전표","실제 공급자가 아닌 다른 가맹점 명의 매출전표는 신용카드 사용으로 보지 않는다"],["기본한도","1,200만원(중소기업 3,600만원)에 사업연도 월수/12를 곱하고 수입금액 한도를 더한다"],["수입금액 한도","수입금액 100억원 이하 0.3%, 100억원 초과 500억원 이하 0.2%, 500억원 초과 0.03%를 적용한다"],["특수관계인 수입금액","일반 수입금액 다음 구간부터 적용한 금액의 10%만 인정한다"],["한도초과액","기타사외유출이다"],["기업업무추진비에 포함","거래처 1인당 연 5만원을 넘는 광고선전물품, 정당한 사유 없이 포기한 거래처 채권, 법인인 직원 조직(조합·단체)에 낸 복리시설비"],["업무와 무관한 지출","대표이사 개인 경조사 비용처럼 업무와 무관한 지출은 기업업무추진비가 아니라 상여 등으로 손금불산입한다"]]},{"t":"table","title":"지급이자","head":["항목","내용"],"rows":[["지급이자 손금불산입 순서","채권자 불분명 사채이자, 지급받는 자가 불분명한 채권·증권 이자, 건설자금이자, 업무무관자산·가지급금 관련 이자의 순서로 적용한다"],["채권자 불분명 사채이자","원천징수세액을 기타사외유출, 나머지를 대표자 상여로 처분한다"],["채권자 불분명 사채가 아닌 경우","주민등록상 거주가 확인된 채권자가 변제받은 뒤 소재불명이 되면 채권자 불분명 사채로 보지 않는다"],["특정차입금 이자","사업용 유형·무형자산 건설에 쓴 특정차입금 이자는 준공된 날까지 자본적 지출로 원본에 더한다(유보)"],["연체이자를 원본에 가산","그 금액은 자본적 지출, 그에 대한 이자는 손금이다"],["업무무관자산·가지급금 이자","지급이자에 업무무관자산 등 적수/차입금 적수를 곱해 기타사외유출로 처분한다"],["가지급금에서 빼는 것","퇴직금전환금, 미지급소득세 대납액, 직원 학자금·우리사주 취득자금 대여 등"]]}],"8":[{"t":"table","title":"과세표준과 세율","head":["항목","내용"],"rows":[["과세표준","각 사업연도 소득에서 이월결손금, 비과세소득, 소득공제를 차례로 뺀 금액이다"],["이월결손금","개시일 전 15년 이내에 발생해 신고·결정된 것만 공제하고, 중소기업·회생계획 이행 기업 외에는 소득의 80%가 한도이다"],["공제받지 못한 비과세소득·소득공제","이월되지 않는다"],["법인세율(2026년)","2025.12.23 개정 세율은 2억원 이하 10%, 2억원 초과 200억원 이하 20%, 200억원 초과 3천억원 이하 22%, 3천억원 초과 25%이다"],["소규모 법인","부동산임대업 주업 등 성실신고확인 대상 소규모 법인은 200억원 이하도 20%이다"],["사업연도가 1년 미만","과세표준을 12개월로 환산해 세율을 적용한 뒤 월수/12를 곱한다(2023년 기출은 9·19·21·24% 시절 세율로 계산)"],["결손금 소급공제","중소기업만 직전 사업연도 법인세를 환급받을 수 있고, 결손금 사업연도와 직전 사업연도를 모두 기한 안에 신고해야 한다"],["환급액","직전 산출세액에서 결손금을 뺀 과세표준에 직전 세율을 적용한 세액을 뺀 금액이며 직전 사업연도 법인세액(산출세액-공제·감면세액)이 한도이다"],["일부 소급공제","결손금 일부만 소급공제 신청할 수도 있다"]]},{"t":"table","title":"세액공제와 최저한세","head":["항목","내용"],"rows":[["외국납부세액공제 한도","산출세액×국외원천소득/과세표준이다"],["외국자회사 배당","자회사 법인세 중 배당분(간접외국납부세액)을 더해 공제하고 국외원천소득에도 가산한다"],["한도를 넘은 금액","다음 사업연도 개시일부터 10년 이내에 이월공제한다"],["재해손실세액공제","사업용 자산의 20% 이상을 재해로 잃으면 법인세액에 자산상실비율을 곱한 금액을 공제하되 상실 자산가액이 한도이다"],["상실비율 계산","변상책임이 없는 타인 소유 자산은 상실비율 계산에서 빼고, 보험금을 받아도 상실비율은 줄지 않는다"],["최저한세","감면 후 세액이 감면 전 과세표준에 최저한세율을 곱한 금액보다 적으면 그 차액만큼 감면을 배제한다"],["최저한세율","중소기업 7%, 일반기업 100억원 이하 10%, 100억원 초과 1천억원 이하 12%, 1천억원 초과 17%이다"],["최저한세 계산에 넣지 않는 것","토지등 양도소득에 대한 법인세와 가산세"]]},{"t":"table","title":"신고·중간예납·가산세","head":["항목","내용"],"rows":[["신고기한","사업연도 종료일이 속하는 달의 말일부터 3개월 이내에 신고하고, 성실신고확인서를 내면 4개월, 외부감사 미종결로 신청하면 1개월 연장된다"],["납부","산출세액에서 감면·공제세액, 중간예납·수시부과·원천징수세액을 빼고 납부하며 수시부과를 받아도 신고의무는 남는다"],["분납","납부세액이 1천만원을 넘으면 2천만원 이하는 1천만원 초과분, 2천만원 초과는 50% 이하를 1개월(중소기업 2개월) 안에 분납한다"],["중간예납 직전 산출세액 기준","직전 사업연도 산출세액(가산세 포함, 토지등 양도소득 법인세 등 제외)에서 감면·원천징수·수시부과세액을 뺀 금액에 6/직전 월수를 곱한다"],["중간예납 실적 기준","중간예납기간 6개월 소득을 연으로 환산해 계산한다"],["선택","원칙은 둘 중 선택이지만 현행법상 공시대상기업집단 소속 법인은 실적 기준으로만 계산한다"],["법인으로 전환","성실신고확인 대상 개인사업자가 법인으로 전환하면 전환 후 3년간 성실신고확인서를 낸다"],["주식등변동상황명세서 미제출","액면금액의 1%"],["사실과 다른 발급","기부금영수증 사실과 다른 발급과 신용카드 매출전표 사실과 다른 발급은 그 금액의 5%"],["현금영수증가맹점 미가입","수입금액 1%에 미가입 기간 비율을 곱한다"],["결정과 경정","무신고 법인에 대한 결정은 신고기한부터 1년 이내에 끝내야 하고, 경정은 장부·증명서류에 의한 실지조사가 원칙이다"]]}],"9":[{"t":"table","title":"합병·분할의 과세","head":["항목","내용"],"rows":[["비적격합병 피합병법인","자산을 합병법인에 양도한 것으로 보아 양도가액에서 순자산 장부가액을 뺀 양도손익을 최종 사업연도 익금·손금에 넣는다"],["비적격합병 합병법인","자산을 합병등기일 현재 시가로 양수한 것으로 보고, 지급한 양도가액과 순자산 시가의 차액은 합병매수차익·합병매수차손으로 처리한다"],["비적격분할","분할등기일 현재 시가로 양수한 것으로 본다"],["적격합병 요건","합병등기일 현재 1년 이상 사업을 계속한 내국법인 간 합병이어야 하고, 합병대가 중 합병법인 주식이 80% 이상이어야 한다"],["승계사업·근로자","합병법인은 그 사업연도 종료일까지 승계사업을 계속하고, 합병등기일 1개월 전 근로자의 80% 이상을 승계해 사업연도 말까지 유지해야 한다"],["근로자 비율에서 빼는 자","임원, 일용근로자, 정년퇴직 예정자, 계약기간 1년 미만인 자"],["적격합병의 효과","피합병법인의 양도손익은 없는 것으로 하고, 합병법인은 자산을 장부가액으로 양수한 것으로 보아 시가로 계상하되 시가와 장부가액의 차액은 자산조정계정으로 둔다"],["자산조정계정","감가상각·처분 때 익금·손금으로 정리된다"]]},{"t":"table","title":"적격합병의 결손금과 사후관리","head":["항목","내용"],"rows":[["승계한 피합병법인 결손금","승계사업에서 생긴 소득금액의 80%(중소기업 등 100%) 범위에서만 공제한다"],["합병법인 자신의 결손금","합병법인 본래 사업 소득에서만 공제한다"],["승계 결손금","채무면제이익으로 보전하는 데 쓸 수 없다"],["승계한 기부금한도초과액","승계사업 소득으로 계산한 기부금 한도 안에서 손금에 넣는다"],["사후관리 기간","합병등기일이 속하는 사업연도의 다음 사업연도 개시일부터 2년(근로자 수 요건은 3년) 안이다"],["사후관리 사유","승계사업을 폐지하거나 주주가 받은 주식을 처분하는 등의 사유가 생기면 그 사업연도에 자산조정계정 잔액과 공제한 승계결손금 등을 익금에 산입한다"],["감면·세액공제","승계받아 공제한 감면·세액공제액도 법인세에 더해 납부하고 그 사업연도부터 감면을 적용하지 않는다"]]},{"t":"table","title":"연결납세와 청산소득","head":["항목","내용"],"rows":[["연결지배","내국법인이 다른 내국법인 주식의 90% 이상을 보유하면 연결지배이고 연결모법인 관할 지방국세청장의 승인을 받아 연결납세방식을 적용할 수 있다"],["연결법인의 사업연도","연결사업연도와 일치해야 하고 1년을 넘지 못하며 납세지는 연결모법인의 납세지이다"],["포기","최초 적용 연결사업연도와 그다음 4년 동안은 포기할 수 없다"],["승인 취소","연결지배하지 않는 법인에 적용하면 승인이 취소된다"],["청산소득","잔여재산가액에서 해산등기일 현재 자본금과 잉여금 합계(자기자본)를 뺀 금액이다"],["이월결손금","잉여금 범위에서 자기자본에서 빼고, 청산기간 중 환급받은 법인세는 자기자본에 더한다"],["청산소득 법인세를 과세하지 않는 경우","특별법 폐지로 상법상 회사로 조직변경하면 과세하지 않으며 비영리내국법인은 청산소득 납세의무가 없다"],["확정신고","잔여재산가액확정일이 속하는 달의 말일부터 3개월 이내에 한다"],["확정일","해산등기일 현재 잔여재산을 그대로 분배하면 분배를 완료한 날이 확정일이다"],["중간신고","해산등기일부터 1년이 되는 날까지 잔여재산가액이 확정되지 않으면 하되 국유재산법상 청산절차를 밟는 법인은 하지 않는다"]]},{"t":"table","title":"교환 양도차익과 토지등 양도소득","head":["항목","내용"],"rows":[["교환 양도차익","2년 이상 사업에 쓴 자산을 특수관계 없는 다른 내국법인이 2년 이상 쓴 같은 종류 사업용자산과 교환(3 이상 법인 간 교환 포함)하고 교환일이 속하는 사업연도 종료일까지 사업에 쓰면 양도차익 상당액을 손금에 넣을 수 있다"],["토지등 양도소득","주택·별장과 조합원입주권·분양권 양도는 20%, 비사업용 토지는 10%(미등기 40%)를 각 사업연도 법인세에 추가한다"],["추가 과세에서 빠지는 것","파산선고에 따른 처분, 직접 경작 농지의 교환·분합, 환지처분"]]}],"10":[{"t":"table","title":"거주자·납세지·위법소득","head":["항목","내용"],"rows":[["거주자","국내에 주소를 두거나 183일 이상 거소를 둔 개인이 거주자이고, 주소는 생계를 같이하는 가족과 국내 자산 등 생활관계의 객관적 사실로 판정한다"],["거주자가 되는 날","국내에 주소를 두면 그날, 거소를 둔 기간이 183일이 되면 그날 거주자가 되며 2과세기간에 걸쳐 183일 이상이어도 된다"],["비거주자가 되는 날","국외 이전을 위해 출국하면 출국하는 날의 다음 날 비거주자가 된다"],["해외현지법인 파견 직원","내국법인이 100% 출자한 해외현지법인 파견 직원은 거주자로 본다"],["납세지","거주자의 소득세 납세지는 소득 종류와 관계없이 주소지이고 주소지가 없으면 거소지이다"],["납세조합이 징수하는 사업소득","납세조합 소재지가 납세지이다"],["납세지 변경","변경된 날부터 15일 이내에 변경 후 관할 세무서장에게 신고한다"],["위법소득","횡령한 처분대금, 무효인 매매로 받아 보유하는 대금처럼 위법소득도 과세하고, 나중에 형법상 몰수·추징되면 후발적 경정청구를 할 수 있다"],["부당행위계산 부인","출자공동사업자의 배당소득, 사업소득, 기타소득, 양도소득에만 적용하고 이자·근로·연금·퇴직소득에는 없다"],["직계존비속에게 주택 무상 대여","직계존비속에게 주택을 무상으로 빌려주고 실제 거주하면 부인 대상이 아니다"]]},{"t":"table","title":"이자소득","head":["항목","내용"],"rows":[["이자소득","비영업대금이익, 직장공제회 초과반환금, 채권 보유기간 이자상당액, 환매조건부채권 매매차익, 물가연동국채 원금 증가분, 소비대차로 바뀐 외상매출금 지연이자는 이자소득이다"],["이자소득이 아닌 것","통합발행 국채의 매각가액과 액면가액 차액, 판결에 따른 손해배상금의 법정이자는 이자소득이 아니다"],["저축성보험 차익","이자소득이나 10년 이상 유지하고 납입보험료 1억원 이하 등 요건을 갖추면 과세하지 않는다"],["직장공제회 초과반환금","종합소득에 합산하지 않는 분리과세 이자소득이고, 납입금 초과이익은 연분연승 방식으로 세액을 계산한다"],["분할 수령 때 생기는 반환금 추가이익","과세하며 세액은 추가이익에 납입금 초과이익 산출세액/납입금 초과이익 비율을 곱해 구한다"]]},{"t":"table","title":"배당소득","head":["항목","내용"],"rows":[["배당소득","법인으로 보는 단체의 분배금, 외국법인 배당, 주식 대차에서 받는 배당 상당액, 출자공동사업자의 손익분배액, 파생결합사채 이익, 요건을 갖춘 조각투자상품 이익은 배당소득이다"],["국외 집합투자기구 이익","결산·분배 요건이 없어도 배당소득이다"],["자본준비금 감액배당","상장법인 대주주의 자본준비금 감액배당은 주식 장부가액까지만 배당소득에서 뺀다"],["이익잉여금 자본전입 무상주","액면가액으로 평가한다"],["상법상 주식배당","발행금액으로 평가한다"],["주식 외 재산","취득 당시 시가로 평가한다"],["합병대가를 모두 주식으로 받은 적격합병","피합병법인 주식의 취득가액으로 평가한다"],["소액주주로서 취득가액이 불분명","상장 여부와 관계없이 액면가액을 취득가액으로 본다"]]},{"t":"table","title":"금융소득 종합과세","head":["항목","내용"],"rows":[["종합과세","이자·배당소득 합계가 2천만원을 넘으면 전액 종합과세하고, 2천만원 이하이면 14%(비영업대금이익·출자공동사업자 배당 25%) 원천징수로 끝난다"],["2천만원 채우는 순서","이자, Gross-up 대상이 아닌 배당, Gross-up 대상 배당 순으로 채운다"],["배당세액공제","기준금액을 넘는 Gross-up 대상 배당에 현행 11%를 더하고 같은 금액을 배당세액공제하되 종합과세 세액과 분리과세 가정 세액의 차액이 한도이다"],["Gross-up 대상","법인세가 과세된 내국법인 배당과 의제배당"],["Gross-up 대상이 아닌 것","외국법인 배당, 출자공동사업자 배당, 자기주식소각이익 2년 내 자본전입, 집합투자기구 이익"],["수입시기","잉여금처분 배당의 수입시기는 잉여금처분 결의일이고, 인정배당은 결산확정일이다"]]}],"11":[{"t":"table","title":"사업소득금액과 결손금","head":["항목","내용"],"rows":[["사업소득금액","총수입금액에서 필요경비를 뺀 금액이다"],["필요경비가 아닌 것","소득세와 대표자 본인의 급여"],["필요경비","실제 근무하는 배우자·가족의 급여는 필요경비이다"],["사업과 무관한 이자수익","예금이자처럼 사업과 무관한 이자수익은 이자소득으로 따로 구분하며 사업소득에 넣지 않는다"],["상품 판매 수입시기","인도한 날"],["금융보험업의 이자·할인료","실제로 받은 날이 수입시기이다"],["총수입금액에 넣는 보험차익","확정급여형 퇴직연금 보험차익과 사업용 자산 손실로 받은 보험차익은 사업소득 총수입금액에 넣는다"],["장부에 의한 사업소득 결손금","그 과세기간의 근로·연금·기타·이자·배당소득금액에서 순서대로 공제한다"],["부동산임대업 결손금","다른 소득에서 빼지 않고 이후 부동산임대업 소득에서만 공제하나, 주거용 건물 임대업 결손금은 다른 소득에서도 공제한다"],["이월결손금","발생 후 15년 이내에 공제하고, 추계신고·추계결정 때는 공제하지 않는다(천재지변 등으로 장부가 없어진 경우는 공제)"],["제척기간이 지난 뒤","그 이전 과세기간 이월결손금이 확인되어도 공제하지 않는다"]]},{"t":"table","title":"결손금 소급공제와 초과인출금","head":["항목","내용"],"rows":[["결손금 소급공제","중소기업을 경영하는 거주자만 사업소득 결손금으로 직전 과세기간 소득세를 환급받을 수 있고 비거주자는 대상이 아니다"],["소급공제할 수 없는 결손금","부동산임대업에서 생긴 결손금은 소급공제할 수 없으며, 과세표준확정신고기한까지 신청한다"],["초과인출금 지급이자","부채(충당금 제외)가 사업용 자산을 넘는 초과인출금에 대한 지급이자는 필요경비에 넣지 않는다"],["불산입액 계산","채권자 불분명 사채이자를 먼저 빼고 남은 차입금 중 이자율이 높은 것부터 초과인출금 적수에 맞추어 불산입액을 계산한다"]]},{"t":"table","title":"주택임대소득","head":["항목","내용"],"rows":[["간주임대료","3주택 이상을 소유하고 보증금 합계가 3억원을 넘으면 3억원 초과분의 60%에 정기예금이자율을 곱한 금액을 간주임대료로 총수입금액에 넣는다"],["소형주택","전용 40㎡ 이하이고 기준시가 2억원 이하인 소형주택은 2026년까지 주택 수에서 뺀다"],["추계로 결정","보증금에서 금융수익을 빼지 않는다"],["분리과세 주택임대소득","주택임대 총수입금액이 2천만원 이하이면 14% 분리과세를 선택할 수 있다"],["필요경비율","50%(등록임대주택 60%)이다"],["추가 공제","분리과세 주택임대소득 외 종합소득금액이 2천만원 이하이면 200만원(등록임대주택 400만원)을 추가로 뺀다"]]}],"12":[{"t":"table","title":"근로소득","head":["항목","내용"],"rows":[["근로소득이 아닌 것","독립된 지위에서 제공한 근로의 대가는 근로소득이 아니다"],["주택구입자금 무상 대여","중소기업이 아닌 회사 종업원이 주택구입자금을 무상으로 빌려 얻은 이익은 근로소득이다"],["사택 이익","임원이 아닌 종업원이 받는 사택 이익은 비과세이다"],["인정상여의 귀속시기","결산확정일이 아니라 근로를 제공한 날이다"],["근로소득공제","연 2천만원이 한도이다"],["비과세 근로소득","식사를 제공받지 않는 근로자의 식사대 월 20만원, 6세 이하 자녀 보육수당 자녀 1명당 월 20만원, 자가운전보조금 월 20만원 이내는 비과세이다"],["상금·보상금","직무발명보상금은 연 700만원, 공무원의 공무 관련 상금은 연 240만원까지 비과세이다"],["식사를 현물로 받으면서 따로 받는 식사대","과세한다"],["생산직 연장근로수당","월정액급여 260만원 이하이고 직전 총급여 3,700만원 이하인 생산직 근로자의 연장·야간·휴일근로수당은 연 240만원까지 비과세한다"],["월정액급여 계산에서 빼는 것","자가운전보조금, 사택제공이익, 광산 입갱·발파수당 같은 실비변상성 급여"],["월정액급여 계산에서 빼지 않는 것","식사대와 보육수당"]]},{"t":"table","title":"공적연금과 연금계좌","head":["항목","내용"],"rows":[["공적연금","2002.1.1. 이후 납입분에 해당하는 부분만 과세하고, 수입시기는 연금을 지급받기로 한 날이다"],["과세분 구분","국민연금은 환산소득 누계액 비율로, 공무원연금 등 그 밖의 공적연금은 기여금 납입월수 비율로 과세분을 나눈다"],["연금소득공제","900만원이 한도이고 분리과세연금소득에는 적용하지 않는다"],["연금계좌 과세","세액공제받은 납입액과 운용수익은 연금수령하면 연금소득, 연금외수령하면 기타소득(15% 원천징수)이다"],["인출 순서","과세제외금액, 이연퇴직소득, 세액공제받은 납입액과 운용수익 순으로 본다"],["연금수령한도","평가액÷(11-연금수령연차)×120%이고, 한도를 넘는 인출은 연금외수령이다"],["연금소득 원천징수","세액공제분 연금수령액은 70세 미만 5%, 70세 이상 80세 미만 4%, 80세 이상 3%로 원천징수하고, 사망 때까지 받는 종신계약 연금은 3%이다"],["이연퇴직소득 연금수령","실제 수령연차 10년 이하는 연금외수령 세율의 70%, 10년 초과 20년 이하는 60%, 20년 초과는 50%를 적용한다"],["분리과세","그 밖의 사적연금이 연 1,500만원 이하이면 분리과세를 선택할 수 있다"]]},{"t":"table","title":"기타소득","head":["항목","내용"],"rows":[["기타소득 범위","퇴직금 지급 지체로 받는 지연손해금, 퇴직 후 행사한 주식매수선택권 이익, 상속받은 저작권 양도대가, 계약 위약 배상금과 그 법정이자, 몰수되지 않은 뇌물은 기타소득이다"],["다른 소득과 겹치면","다른 소득으로 구분하고, 서화를 반복적으로 판매하면 사업소득이다"],["과세대상이 아닌 것","교통재해 보험금은 과세대상이 아니고 서화·골동품을 박물관·미술관에 양도한 소득은 비과세이다"],["필요경비 의제 80%","주택입주 지체상금은 받은 금액의 80%"],["필요경비 의제 60%","강연료·산업재산권 대여·공익사업 관련 지상권 대여 등은 60%를 필요경비로 하되 실제 경비가 더 크면 실제 경비를 쓴다"],["서화·골동품","양도대가 1억원 이하분 90%, 초과분 80%(10년 이상 보유하면 90%)이며 이 역시 실제 경비가 크면 그 금액을 쓴다"],["원천징수세율","기타소득 원천징수세율은 20%이고 연금외수령분과 소기업·소상공인 공제부금 해지일시금은 15%이다"],["분리과세","기타소득금액이 연 300만원 이하이면 분리과세를 선택할 수 있다"]]}],"13":[{"t":"table","title":"결손금·공동사업·상속","head":["항목","내용"],"rows":[["결손금 통산 순서","해당 과세기간에 생긴 결손금을 먼저 공제하고 남은 소득에서 이월결손금을 뺀다"],["사업소득 결손금","근로·연금·기타·이자·배당소득금액 순으로 공제하고, 일반 사업 결손금은 같은 해 부동산임대업 소득에서도 공제한다"],["부동산임대업 결손금","주거용 건물 임대업 결손금은 다른 소득과 통산하지만 그 밖의 부동산임대업 결손금은 이월만 되고 소급공제도 안 된다"],["공동사업","공동사업장을 1거주자로 보아 소득금액을 계산한 뒤 손익분배비율로 나눈다"],["특수관계인과의 공동사업","지분을 거짓으로 정하면 주된 공동사업자에게 합산하며, 이때 특수관계인은 손익분배비율에 해당하는 자기 소득금액을 한도로 연대납세의무를 진다"],["합산 대상","사업소득뿐이고 공동사업장의 이자·배당소득은 합산하지 않는다"],["상속과 소득세","피상속인의 소득에 대한 소득세와 상속인 자신의 소득에 대한 소득세는 구분해서 계산한다"],["연금계좌 승계","연금계좌 가입자가 사망하고 배우자가 연금외수령 없이 계좌를 승계하면 그 계좌의 소득은 상속인의 소득으로 본다"]]},{"t":"table","title":"소득공제","head":["항목","내용"],"rows":[["기본공제","본인·배우자·부양가족 1명당 연 150만원이고 배우자·부양가족은 소득금액 100만원 이하(근로소득만 있으면 총급여 500만원 이하)여야 한다"],["연령 요건","직계존속 60세 이상, 직계비속 20세 이하, 형제자매 20세 이하 또는 60세 이상이 요건이고 장애인은 나이 제한이 없다"],["대상 범위","기초생활수급자는 친족이 아니어도 생계를 같이하면 대상이고, 재혼한 직계존속의 법률상 배우자도 포함되나 사실혼 배우자는 빠진다"],["판정 시점","공제대상 여부는 과세기간 종료일 현재로 판정하고, 그 전에 사망한 사람은 사망일 전날로 판정한다"],["사망·이혼","과세기간 중 사망한 배우자는 공제하지만 이혼한 배우자는 공제하지 않는다"],["여러 거주자의 공제대상에 겹치면","신고서에 적은 대로 1인에게 공제하고 서로 적었거나 알 수 없으면 배우자 공제를 우선한다"],["추가공제","70세 이상 경로우대 100만원, 장애인 200만원, 종합소득금액 3천만원 이하 여성의 부녀자공제 50만원, 한부모 100만원을 더한다"],["소득공제 구분","근로소득공제와 연금소득공제는 소득금액 계산 단계의 공제라서 종합소득공제가 아니다"]]},{"t":"table","title":"세액공제","head":["항목","내용"],"rows":[["자녀세액공제","8세 이상 공제대상 자녀·손자녀가 1명이면 연 25만원, 2명이면 55만원, 3명 이상이면 55만원에 2명 초과 1명당 40만원을 더한다"],["출산·입양","그 해 출산·입양한 자녀가 첫째면 30만원, 둘째 50만원, 셋째 이상 70만원을 공제한다"],["보험료","보장성보험료는 12%(장애인전용 15%)로 각 100만원 한도이고 건강보험료는 소득공제 대상이다"],["교육비","15%이며 교복은 1인당 50만원 한도이고 배우자·자녀의 대학원비와 사설학원비는 공제하지 않는다"],["의료비","총급여 3%를 넘는 금액의 15%(일반 대상 700만원 한도, 본인·65세 이상·6세 이하·장애인은 한도 없음)이고 미숙아 20%, 난임시술 30%이며 안경은 1인당 50만원까지이다"]]},{"t":"table","title":"금융소득 비교과세","head":["항목","내용"],"rows":[["금융소득 비교과세","금융소득이 2천만원을 넘으면 2천만원은 14%, 나머지는 기본세율로 계산한 세액과 금융소득 전체를 원천징수세율로 계산하고 다른 소득에 기본세율을 적용한 세액 중 큰 금액을 산출세액으로 한다"],["계산에서 빼는 것","비실명 이자처럼 45% 분리과세되는 소득은 이 계산에서 뺀다"]]}],"14":[{"t":"table","title":"퇴직소득","head":["항목","내용"],"rows":[["퇴직소득 범위","종교관련종사자가 현실적 퇴직으로 받는 소득, 과학기술인공제회의 과학기술발전장려금, 국민연금 일시금 중 2002.1.1. 이후 납입분 기초 부분은 퇴직소득이다"],["퇴직연금제도 폐지","퇴직급여를 미리 받으면 받은 날 퇴직한 것으로 본다"],["외국납부세액","퇴직소득에서 공제하는 외국납부세액의 한도초과액은 이월공제하지 않는다"],["퇴직소득세 계산","퇴직소득에서 근속연수공제를 빼고 12/근속연수를 곱해 환산급여를 구한 뒤 환산급여공제를 빼고 기본세율을 적용해 근속연수/12를 곱한다"],["임원 퇴직소득 한도","2012~2019년 근무분은 직전 3년 연평균 급여×1/10×근속연수×3배, 2020년 이후 근무분은 직전 3년 연평균 급여×1/10×근속연수×2배를 한도로 하고 넘는 금액은 근로소득이다"]]},{"t":"table","title":"양도와 1세대1주택 비과세","head":["항목","내용"],"rows":[["양도","강제경매로 넘어가는 것도 양도이고 파산선고에 의한 처분만 비과세이다"],["양도가 아닌 것","환지처분으로 지목·지번이 바뀌는 것은 양도가 아니며, 지역권은 과세대상 자산이 아니다"],["국가사업 농지 교환","쌍방 토지가액 차액이 큰 쪽 가액의 4분의 1 이하인 국가사업 농지 교환은 비과세이다"],["1세대1주택 비과세","2년 이상 보유하고 취득 당시 조정대상지역 주택은 보유기간 중 2년 이상 거주해야 하며, 양도가액 12억원을 넘는 고가주택은 초과분을 과세한다"],["2년 미만 보유","1년 이상 거주한 주택은 세대전원이 취학·근무상 형편·질병 요양 등으로 다른 시·군으로 옮기면 2년 미만 보유여도 비과세하나 사업상 형편은 사유가 아니다"],["이혼","법률상 이혼했어도 생계를 같이하는 등 사실상 이혼으로 보기 어려운 사람은 1세대의 배우자에 포함한다"]]},{"t":"table","title":"1세대1주택 특례와 양도·취득가액","head":["항목","내용"],"rows":[["일시적 2주택","종전주택 취득 후 1년 이상 지나 신규주택을 사고 3년 이내(조정대상지역 안에서 갈아타면 2년)에 종전주택을 팔면 비과세한다"],["상속주택","상속주택과 상속 전부터 보유한 일반주택이 있으면 일반주택을 팔 때만 1주택으로 보고, 상속 후 산 일반주택에는 적용하지 않는다"],["합가","60세 이상 직계존속 동거봉양 합가는 10년 이내"],["겸용주택","겸용주택 전부를 주택으로 볼 때 고가주택 판단은 전체 실지거래가액으로 한다"],["양도가액","특수관계법인 외의 자에게 시가보다 비싸게 팔아 증여재산가액이 있으면 양도가액에서 증여재산가액을 뺀 금액이 양도가액이다"],["취득가액","특수관계법인에서 취득하며 상여로 처분된 금액은 취득가액에 더하고, 소유권 확보 소송비용은 다른 소득에서 필요경비로 처리한 부분을 빼고 취득가액에 넣는다"],["소급 감정","취득일부터 3년이 지나 소급 감정한 가액은 쓸 수 없다"],["환산취득가액·매매사례가액","쓰면 필요경비는 개산공제(토지·건물은 기준시가의 3%, 미등기 0.3%)만 인정한다"]]},{"t":"table","title":"양도소득 공제·세율·이월과세","head":["항목","내용"],"rows":[["장기보유특별공제","3년 이상 보유한 토지·건물은 6%부터 해마다 2%포인트씩 늘어 15년 이상 30%를 공제하고, 1세대1주택 고가주택은 보유 연 4%·거주 연 4%로 각 40%, 최대 80%이다"],["공제 제외","미등기자산과 국외자산에는 장기보유특별공제가 없다"],["기본공제","부동산 등과 주식 등 소득별로 연 250만원이며 미등기자산은 받지 못한다"],["토지·건물 세율","1년 미만 보유 토지·건물 50%, 1년 이상 2년 미만 40%이다"],["주택·조합원입주권·분양권","1년 미만 70%, 2년 미만 60%이다"],["그 밖의 세율","분양권은 2년 이상이어도 60%, 미등기자산은 70%, 비사업용 토지는 기본세율에 10%포인트를 더한다"],["대주주 주식","과세표준 3억원 이하 20%, 초과분 25%(중소기업 외 1년 미만 보유 30%)이다"],["이월과세","배우자·직계존비속에게 증여받은 자산을 10년 이내 양도하면 취득가액과 취득시기를 증여자 기준으로 하고 낸 증여세는 필요경비로 뺀다"],["그 밖의 특수관계인","증여한 자산을 수증자가 10년 이내 양도해 세부담이 줄면 증여자가 양도한 것으로 보아 연대납세의무를 지우고 증여세는 환급한다"],["예정신고","부동산·신탁수익권은 양도일이 속하는 달의 말일부터 2개월, 주식은 반기 말일부터 2개월, 부담부증여는 3개월 이내이고 국외전출자는 출국일이 속하는 달의 말일부터 3개월 이내에 신고한다"]]}],"15":[{"t":"table","title":"중간예납·확정신고·분납","head":["항목","내용"],"rows":[["중간예납","1월 1일부터 6월 30일까지를 중간예납기간으로 하여 직전 과세기간 세액으로 정한 중간예납기준액의 2분의 1을 고지하고 11월 30일까지 납부한다"],["중간예납 의무가 없는 경우","과세기간 개시일 현재 사업자가 아닌 자로서 그 해 신규로 사업을 시작한 거주자는 중간예납 의무가 없고 중간예납세액이 50만원 미만이면 징수하지 않는다"],["중간예납추계액","중간예납기준액의 30%에 미달하면 11월에 추계액을 신고·납부할 수 있다"],["확정신고","종합소득금액이 있으면 과세표준이 없거나 결손금이 있어도 확정신고를 해야 한다"],["확정신고 예외","분리과세 이자·배당·연금·기타소득만 있는 거주자와 공적연금소득만 있는 거주자는 신고하지 않을 수 있으나 분리과세 주택임대소득이 있으면 확정신고를 해야 한다"],["출국","확정신고를 해야 할 거주자가 출국하면 출국일 전날까지 그 과세기간의 과세표준을 신고한다"],["성실신고확인","성실신고확인대상사업자가 성실신고확인서를 내면 확정신고 기간은 다음 연도 5월 1일부터 6월 30일까지이다"],["세무사","세무사가 성실신고확인대상사업자이면 자기 사업소득금액에 대한 성실신고확인서를 본인이 작성·제출할 수 없다"],["분할납부","납부할 세액이 1천만원을 넘으면 납부기한이 지난 후 2개월 이내에 일부를 나누어 낼 수 있다"],["분납액","세액이 2천만원 이하면 1천만원을 넘는 금액, 2천만원을 넘으면 세액의 50% 이하를 분납한다"],["분납 적용","종합소득·퇴직소득·양도소득 모두에 적용되고 확정신고 세액뿐 아니라 중간예납세액과 예정신고세액도 대상이다"]]},{"t":"table","title":"원천징수세율과 지급시기","head":["항목","내용"],"rows":[["원천징수세율","일반 이자·배당은 14%, 비영업대금의 이익과 출자공동사업자의 배당은 25%, 원천징수대상 사업소득은 3%이다"],["그 밖의 세율","외국인 직업운동가가 프로스포츠구단과 계약해 받는 소득은 계약기간과 관계없이 20%, 일용근로자 근로소득은 6%, 봉사료는 5%이다"],["거주자의 양도소득","원천징수 대상이 아니다"],["지급시기 의제(근로·퇴직)","1~11월분 근로소득과 1~11월 퇴직자의 퇴직소득을 12월 31일까지 지급하지 않으면 12월 31일에, 12월분 근로소득을 다음 연도 2월 말일까지 지급하지 않으면 2월 말일에 지급한 것으로 본다"],["출자공동사업자의 배당소득","과세기간 종료 후 3개월이 되는 날까지 지급하지 않으면 그날 지급한 것으로 본다"],["무기명주식의 배당","실제 지급한 날 원천징수한다"],["소득처분 금액","법인세 결정·경정으로 처분된 상여·배당·기타소득은 소득금액변동통지서를 받은 날에 지급한 것으로 보고 원천징수한다"],["법인이 신고하면서 처분한 금액","신고일 또는 수정신고일에 지급한 것으로 본다"],["결정·경정으로 처분된 소득","원천징수세액은 반기별 납부를 할 수 없다"]]},{"t":"table","title":"원천징수 제외와 납부","head":["항목","내용"],"rows":[["원천징수하지 않는 경우","소득세가 면제되는 소득과 지급 전에 이미 종합소득에 합산되어 과세된 배당소득은 지급할 때 원천징수하지 않는다"],["퇴직소득","퇴직일 현재 연금계좌에 있는 퇴직소득은 연금외수령하기 전까지 원천징수하지 않는다"],["근무지 변경","같은 고용주가 근무지 변경으로 월급여를 나누어 지급하면 변경된 근무지에서 월급여액 전액을 원천징수한다"],["납부","원천징수세액은 징수일이 속하는 달의 다음 달 10일까지 낸다"],["반기납부","직전 연도 상시고용인원 20명 이하인 원천징수의무자(금융·보험업 제외)는 승인을 받아 반기 마지막 달의 다음 달 10일까지 낼 수 있다"],["연말정산","공적연금소득자가 사망하면 사망일이 속하는 달의 다음다음 달 말일까지 연말정산한다"],["지급명세서","일용근로소득 지급명세서는 지급일이 속하는 달의 다음 달 말일까지 낸다"],["합병신설법인","소멸법인이 내지 않은 원천징수 소득세의 납세의무를 진다"]]}],"16":[{"t":"table","title":"재화 공급의 특례","head":["항목","내용"],"rows":[["재화의 공급으로 보는 것","매입세액을 공제받은 재화를 면세사업에 직접 쓰거나 개인적으로 쓰는 것, 고객 추첨 경품 같은 사업상 증여, 폐업 때 남은 재화"],["내국신용장","내국신용장으로 영세율을 적용받아 산 재화를 면세사업에 직접 써도 공급이다"],["공급이 아닌 것","견본품 인도, 사후 무료서비스용 사용, 과세사업의 수선비 등 대체 사용, 자기적립마일리지로만 결제받은 증여"],["재화의 공급인 것","교환계약, 현물출자, 재화의 소비대차에 따른 차용·반환, 공동사업 건축물의 분할등기 이전"],["공급이 아닌 것(담보·상속)","질권·저당권·양도담보 목적의 제공, 상속세 물납, 출자지분의 양도·상속·증여와 현금 반환"],["출자지분을 현물로 반환","공급이다"],["위탁매매에서 위탁자를 알 수 없으면","수탁자가 공급하거나 공급받은 것으로 본다"]]},{"t":"table","title":"용역의 공급과 재화의 공급시기","head":["항목","내용"],"rows":[["용역의 공급","주요자재를 전혀 부담하지 않는 단순가공과 자재를 부담하는 건설업은 용역의 공급이다"],["재화의 공급","주요자재 일부를 부담해 새 재화를 만들어 인도하면 재화의 공급이다"],["특수관계인에게 사업용 부동산 임대","시가보다 싸게 임대하면 과세하나 대학이 산학협력단에 무상 임대하는 것은 공급이 아니다"],["과세대상이 아닌 것","대가 없는 위약금·체선료·협회비와 사업장 안 사용인 무상 음식"],["과세하는 것","반환하지 않는 골프장 입회금과 면세재화 운반용역"],["재화의 공급시기","기한부판매는 기한이 지나 판매가 확정되는 때, 무인판매기는 현금을 꺼내는 때, 위탁판매수출은 공급가액이 확정되는 때가 공급시기이다"],["계속 공급","완성도기준·중간지급조건부와 전력처럼 단위를 나눌 수 없는 재화의 계속 공급은 대가의 각 부분을 받기로 한 때이고 완성도기준·중간지급조건부에서 인도일 이후 받기로 한 부분은 인도일이다"],["보세구역에서 국내로 공급","수입에 해당하는 것은 수입신고 수리일이다"]]},{"t":"table","title":"용역의 공급시기와 사업장","head":["항목","내용"],"rows":[["부동산 임대용역","둘 이상의 과세기간에 걸쳐 제공하고 대가를 선불이나 후불로 받으면 예정신고기간 또는 과세기간의 종료일이 공급시기이다"],["상표권 사용대가","일시불 선불로 받고 여러 과세기간 계속 쓰게 하는 경우도 같다"],["장기할부조건부 용역","대가의 각 부분을 받기로 한 때이고 역무 완료일 이후 부분을 완료일로 당기는 규정은 없다"],["이동통신 전기통신사업","법인의 이동통신 전기통신사업은 본점소재지가 사업장이다"],["운수업","개인 명의 차량을 다른 개인이 운용하는 운수업은 등록된 개인이 업무를 총괄하는 장소가 사업장이다"],["무인자동판매기 사업","업무를 총괄하는 장소만 사업장이고 다른 장소를 추가로 등록할 수 없으며 사업장도 등록도 없으면 결정·경정 당시 주소나 거소를 사업장으로 한다"],["납세의무","농민이 농지 개량에서 나온 토사석을 일시적으로 파는 것은 납세의무가 없으나 사업자가 아닌 자의 재화 수입은 납세의무가 있다"]]},{"t":"table","title":"영세율과 면세","head":["항목","내용"],"rows":[["수출 영세율","중계무역·외국인도수출과 보세구역 물품의 외국 반출은 국내 사업장에서 계약과 대가 수령이 이루어진 경우에만 영세율이다"],["수산물","대한민국 선박이 공해에서 잡은 수산물의 외국 반출은 영세율이다"],["영세율이 아닌 것","금지금을 내국신용장·구매확인서로 공급하는 것은 영세율이 아니고, 국내에서 국내사업장 없는 비거주자에게 재화를 직접 공급하고 원화로 받는 것도 영세율이 아니다"],["국외 제공 용역","대가를 원화로 받는지와 관계없이 영세율이고 국외 건설공사 재도급도 같다"],["비거주자에게 제공하는 용역","국내사업장 없는 비거주자에게 상품중개·교육지원 용역을 제공하고 외국환은행에서 원화로 받으면 영세율이나 건물 임대는 제외된다"],["영세율 용역","상업서류 송달용역과 외국항행사업자가 자기 승객 전용 호텔에 투숙시키는 것은 영세율이다"],["상호주의","비거주자·외국법인 사업자는 그 나라가 우리 거주자에게 같은 면세를 할 때만 영세율을 받으며 간이과세자도 영세율을 적용받는다"],["면세","미술창작품, 금융회사의 금고대행용역, 차도선형여객선 운송, 국산 비식용 원생산물(관상용 새 등)은 면세하나 외국산 비식용 수산물 수입은 과세한다"],["과세","항공기 여객운송, 도서 인쇄·제본 용역, 피부과 부설 피부관리실 용역, 음악산업법상 전자출판물, 집합투자업자가 자금을 어업권 등 실물에 운용하는 용역은 과세한다"],["면세포기","영세율 대상인 면세재화는 면세를 포기할 수 있으나 신고한 날부터 3년간 면제받지 못하고 그 수출용 농산물에는 의제매입세액공제를 하지 않는다"]]}],"17":[{"t":"table","title":"공급가액","head":["항목","내용"],"rows":[["공급가액의 원칙","금전으로 받으면 그 대가, 금전 외의 대가를 받으면 자기가 공급한 재화·용역의 시가가 공급가액이다"],["교환","받은 재화가 아니라 내가 준 재화의 시가로 하고 사업상 증여·폐업 잔존재화도 시가로 한다"],["부가가치세 포함 여부가 불분명","받은 금액에 110분의 100을 곱한다"],["공급가액에 넣지 않는 것","매출에누리·매출할인, 환입된 재화, 도달 전 파손·멸실된 재화, 연체이자, 공급과 직접 관련 없는 국고보조금"],["공급가액에 포함","공급과 직접 관련된 국고보조금·공공보조금"],["과세표준에서 빼지 않는 것","공급받는 자에게 주는 판매장려금과 대손금"],["특수관계인에게 사업용 부동산 임대용역","무상이나 부당하게 낮은 대가로 공급하면 시가를 공급가액으로 한다"],["위탁가공무역 수출","완성된 제품의 인도가액이 과세표준이다"],["기부채납","근거 법률에 따라 기부채납된 가액(포함된 부가가치세 제외)이 과세표준이다"],["자기적립마일리지","결제받은 금액은 공급가액에서 뺀다"]]},{"t":"table","title":"외화·할부·선발급","head":["항목","내용"],"rows":[["공급시기가 되기 전에 환가","환가한 금액을 공급가액으로 한다"],["공급시기 이후 외화로 받거나 외화로 보유","공급시기의 기준환율로 환산한다"],["수출","공급시기는 선적일이므로 선적 전 환가한 선수금은 환가액, 선적 후 받은 잔금은 선적일 기준환율로 계산한다"],["장기할부판매","2회 이상 나누어 받고 인도일 다음 날부터 최종 할부금 지급기일까지 1년 이상이어야 하며 받기로 한 부분만 그 과세기간 과세표준에 넣는다"],["기간이 1년 미만","인도일에 전액을 과세한다"],["중간지급조건부","계약금 외에 2회 이상 나누어 받고 계약금 약정일부터 인도일까지 6개월 이상이어야 한다"],["완성도기준지급조건부","받기로 한 각 부분이 과세표준이다"],["세금계산서 선발급","공급시기 전에 대가를 받지 않았더라도 거래상대방 요청 등으로 세금계산서를 먼저 발급하면 발급한 금액을 그때의 공급가액으로 한다"],["7일이 넘어 대가를 받고 법정 요건도 갖추지 못하면","발급일부터 7일이 넘어 대가를 받고 법정 요건도 갖추지 못하면 발급일이 공급시기가 되지 않는다"],["계약금만 받고 세금계산서를 발급하지 않았으면","중간지급조건부가 아닌 거래에서는 인도 전에는 공급시기가 오지 않는다"]]},{"t":"table","title":"간주임대료와 일괄 공급","head":["항목","내용"],"rows":[["간주임대료","임대보증금·전세금을 받으면 보증금에 정기예금이자율과 과세대상기간 일수/365(윤년 366)를 곱한 간주임대료를 과세표준에 더한다"],["월세","받기로 한 날을 기준으로 하고 둘 이상의 과세기간에 걸친 선불·후불 임대료는 월수에 따라 안분한다"],["관리비","관리비 중 청소비 같은 용역 대가는 과세표준에 포함한다"],["상가와 주택이 함께 있는 건물","임대료와 간주임대료 합계를 건물은 기준시가 비율로, 부수토지는 면적 비율로 나누어 상가분만 과세한다"],["주택과 그 부수토지 임대","면세이다"],["토지와 건물 일괄 공급","건물의 실지거래가액이 공급가액이고 가액 구분이 불분명하거나 안분계산액과 30% 이상 차이 나면 안분한다"],["안분","감정평가가액, 기준시가, 장부가액 순으로 하며 기준시가가 없는 기계장치가 섞이면 먼저 장부가액 비율로 나누고 건물·토지는 기준시가 비율로 다시 나눈다"]]}],"18":[{"t":"table","title":"매입세액 공제","head":["항목","내용"],"rows":[["공제 시기","공급시기 이후 받은 세금계산서도 그 과세기간 확정신고기한까지 받으면 공제하고 확정신고기한 다음 날부터 1년 이내에 받아 수정신고서나 경정청구서와 함께 내도 공제한다"],["종이 세금계산서","전자세금계산서 의무발급자에게서 종이 세금계산서를 받았어도 확정신고기한까지 받고 거래사실이 확인되면 공제한다"],["등록 전 매입세액","과세기간이 끝난 후 20일 이내에 등록을 신청하면 그 과세기간 기산일까지 역산한 기간분을 공제한다"],["필요적 기재사항이 빠진 세금계산서","작성 연월일 같은 필요적 기재사항이 빠진 세금계산서는 공제하지 않으나 공급자 주소·품목·단가·수량이 빠진 것은 공제한다"],["불공제","업무무관 자산, 기업업무추진비 관련(거래처 증정품), 면세사업 투자, 토지 관련(건축물이 있는 토지를 사서 철거한 건물의 취득·철거비 포함) 매입세액은 불공제이다"],["승용자동차","개별소비세 과세 승용자동차의 구입·유지 매입세액은 제조업자가 업무에 써도 불공제이고 운수업 등에 직접 영업으로 쓰는 것만 공제한다"],["공제하는 것","종업원 선물·작업복과 국가에 무상 공급한 재화의 매입세액은 공제한다"]]},{"t":"table","title":"공통매입세액과 의제매입세액","head":["항목","내용"],"rows":[["공통매입세액","실지귀속을 구분할 수 없는 공통매입세액은 공급가액 비율로 안분하고 예정신고 때 안분한 것은 확정신고 때 6개월 전체 비율로 정산한다"],["재계산","감가상각자산은 면세비율이 취득 때나 직전 재계산 때보다 5%포인트 이상 증감하면 매입세액×(1−체감률×경과된 과세기간 수)×증감비율로 재계산하고 체감률은 건물·구축물 5%, 그 밖의 자산 25%이다"],["면세사업에만 쓰던 감가상각자산","과세사업에 함께 쓰면 같은 체감 계산에 과세비율을 곱해 공제하고 원재료는 대상이 아니다"],["의제매입세액","면세농산물등을 원재료로 과세 재화·용역을 공급하면 매입가액에 공제율을 곱해 매입한 때 공제하므로 재고분도 포함하고 운반비는 빼며 수입분은 관세의 과세가격으로 한다"],["음식점업","법인 6/106, 개인 8/108(과세표준 2억원 이하는 2026.12.31.까지 9/109)이고 과세유흥장소는 2/102이다"],["제조업","개인·중소기업 4/104(과자점·떡방앗간 등 개인은 6/106), 그 밖은 2/102이다"],["적용하지 않는 경우","면세를 포기하고 영세율을 적용받는 공급과 간이과세자에는 적용하지 않는다"]]},{"t":"table","title":"세금계산서","head":["항목","내용"],"rows":[["재화 환입","환입된 날을 작성일로 적고 비고란에 처음 작성일을 덧붙여 붉은색 글씨나 음의 표시로 발급한다"],["간이과세자에서 일반과세자로 바뀐 뒤 환입","전환 전 공급분이 환입되면 처음 세금계산서 작성일을 작성일로 적는다"],["이중 발급","착오로 이중 발급하면 처음 내용대로 음의 표시를 해 발급한다"],["내국신용장","과세기간 종료 후 25일 이내 사후 개설되어도 발급한다"],["세율 오류 정정","세무조사 통지 후 경정을 미리 알고 하는 세율 오류 정정은 할 수 없다"],["영수증 발급","직전 연도 공급대가 4천800만원 미만 간이과세자와 수의사 진료용역·도로운영용역 공급자는 영수증을 발급한다"],["감가상각자산 공급","자동차운전학원·수의사도 감가상각자산을 공급하며 사업자가 요구하면 세금계산서를 발급한다"],["간주임대료","누가 부담하든 세금계산서를 주고받을 수 없다"],["종합여행업자","외국인 관광객에게 알선용역을 제공하고 원화로 받으면 발급의무가 없다"],["위탁매입","공급자가 위탁자를 공급받는 자로 하고 수탁자 등록번호를 덧붙여 적는다"],["전자세금계산서 발급 대상","법인과 직전 연도 사업장별 공급가액 8천만원 이상인 개인사업자는 다음 해 제2기(7월 1일)부터 전자세금계산서를 발급하고 세무서장은 1개월 전까지 통지한다"],["전송","발급명세는 발급일 다음 날까지 국세청장에게 전송하고 의무가 없는 사업자도 전자발급·전송할 수 있다"],["가산세","의무자가 종이로 발급하면 공급가액의 1%, 확정신고기한까지 늦게 전송하면 0.3% 가산세이다"],["매입자발행세금계산서","공급시기가 속하는 과세기간 종료일부터 1년 이내에 신청인 관할 세무서장에게 거래사실 확인을 신청한다"]]},{"t":"table","title":"신고·납부와 간이과세","head":["항목","내용"],"rows":[["예정고지","개인사업자는 예정고지세액을 내고 50만원 미만이면 징수하지 않으며 제1기분 고지서는 4월 1일부터 10일까지 발부한다"],["예정신고","공급가액이 직전 과세기간의 3분의 1에 미달하거나 조기환급을 받으려면 예정신고할 수 있다"],["확정신고","예정신고분을 제외하고 한다"],["수입 재화","부가가치세는 세관장에게 관세와 함께 신고·납부하고 납부유예도 세관장이 한다"],["대리납부","국외사업자에게 용역을 받은 자는 사업자가 아니어도 매입세액공제가 안 되는 부분을 대리납부한다"],["사업자 단위 과세","바꾸려면 과세기간 개시 20일 전까지 본점·주사무소 관할 세무서장에게 신청한다"],["간이과세자","직전 연도 공급대가 1억4백만원 미만인 개인사업자만 간이과세자이고 부동산임대업·과세유흥장소는 4천800만원 미만이 기준이며 일반과세 사업장을 가진 사람이 새로 연 사업장도 일반과세이다"],["일반과세로 전환","기준금액 이상이 된 해의 다음 해 7월 1일부터 일반과세로 바뀌고 결정·경정으로 기준을 넘으면 그 과세기간까지는 간이과세자로 본다"],["납부세액","공급대가×업종별 부가가치율×10%이고 매입세금계산서 공급대가의 0.5%와 신용카드 발행금액의 1.3%(연 1천만원 한도, 2026년까지)를 빼며 의제매입·대손세액 공제는 없다"]]}],"19":[{"t":"table","title":"상속세 과세대상과 과세가액","head":["항목","내용"],"rows":[["상속세 과세대상","피상속인이 거주자이면 국내외 모든 상속재산, 비거주자이면 국내에 있는 상속재산에 상속세를 매긴다"],["납부의무","상속인과 수유자는 상속재산 중 각자 받았거나 받을 재산의 비율에 따라 상속세를 내고 각자 받았거나 받을 재산을 한도로 연대납부의무를 진다"],["상속재산으로 보는 것","피상속인이 보험료를 낸 생명보험금, 신탁재산, 피상속인에게 지급될 퇴직금"],["추정상속재산","상속개시 전 1년 이내에 재산 종류별로 2억원 이상, 2년 이내 5억원 이상을 처분하거나 인출했는데 용도가 객관적으로 명백하지 않으면 상속받은 것으로 추정해 과세가액에 넣는다"],["채무","같은 기간·금액 기준으로 진 채무의 용도가 불분명해도 같고 국가·금융회사 등이 아닌 자에 대한 채무로서 상속인이 변제할 의무가 없다고 보이는 것도 과세가액에 넣는다"],["과세가액","상속재산가액에서 공과금, 장례비용, 채무를 빼고 상속개시 전 10년 이내 상속인에게 한 증여재산과 5년 이내 상속인 아닌 자에게 한 증여재산을 더한다"],["장례비용","500만원 미만이면 500만원, 1천만원을 넘으면 1천만원이고 봉안시설·자연장지 비용은 500만원까지 따로 더한다"]]},{"t":"table","title":"상속공제","head":["항목","내용"],"rows":[["기초공제","2억원이고 자녀(태아 포함)는 1명당 5천만원, 65세 이상 연로자는 1명당 5천만원을 공제한다"],["일괄공제","기초공제와 그 밖의 인적공제 합계 대신 5억원을 일괄공제로 받을 수 있고 신고를 하지 않으면 5억원을 공제한다"],["일괄공제를 받을 수 없는 경우","배우자가 단독으로 상속받으면 일괄공제를 받을 수 없다"],["배우자 상속공제","배우자가 실제 상속받은 금액을 법정상속분 등으로 계산한 한도와 30억원 중 작은 금액까지 공제한다"],["5억원 공제","배우자가 상속받은 금액이 없거나 5억원 미만이면 5억원을 공제한다"],["분할","상속세 신고기한 다음 날부터 9개월이 되는 날까지 배우자 상속재산을 분할(등기 등 포함)해야 적용한다"],["금융재산 공제","순금융재산이 2천만원 이하면 전액, 넘으면 20%와 2천만원 중 큰 금액을 2억원 한도로 공제하고 최대주주 보유 주식과 신고하지 않은 타인 명의 금융재산은 빠진다"],["동거주택 공제","피상속인과 직계비속 상속인이 10년 이상 한 주택에서 동거하고 1세대1주택이었으면 주택가액(담보채무 차감)의 100%를 6억원 한도로 공제한다"],["상속공제 한도","과세가액에서 상속인 아닌 자에게 유증한 재산, 상속 포기로 다음 순위가 받은 재산, 가산한 사전증여재산을 뺀 금액을 한도로 한다"]]},{"t":"table","title":"세율·신고와 증여재산공제","head":["항목","내용"],"rows":[["세율","과세표준 1억원 이하 10%, 5억원 이하 20%, 10억원 이하 30%, 30억원 이하 40%, 초과분 50%로 상속세와 증여세가 같다"],["할증","자녀가 아닌 직계비속이 상속·증여받으면 산출세액의 30%(미성년자이고 20억원 초과분이면 40%)를 더하나 중간 세대가 먼저 사망한 대습상속이면 할증하지 않는다"],["신고","상속세는 상속개시일이 속하는 달의 말일부터 6개월, 증여세는 증여받은 날이 속하는 달의 말일부터 3개월 이내에 신고하고 신고하면 산출세액의 3%를 공제한다"],["증여재산공제","10년 동안 배우자에게서 6억원, 직계존속에게서 5천만원(미성년자 2천만원), 직계비속에게서 5천만원, 4촌 이내 혈족·3촌 이내 인척에게서 1천만원을 공제한다"],["혼인·출산","직계존속에게서 혼인일 전후 2년 이내나 자녀 출생일부터 2년 이내에 받으면 합쳐서 1억원을 따로 공제한다"],["증여 반환","금전 외 증여재산을 신고기한까지 돌려주면 처음부터 증여가 없던 것으로 보고 신고기한 후 3개월 이내에 돌려주면 당초 증여는 과세하고 반환분만 과세하지 않는다"]]},{"t":"table","title":"증여 예시·평가·연부연납","head":["항목","내용"],"rows":[["특수관계인 간 저가양수·고가양도","차액이 시가의 30%와 3억원 중 적은 금액 이상이면 차액에서 그 금액을 뺀 것을 증여재산으로 한다"],["특수관계가 없으면","정당한 사유 없이 차액이 시가의 30% 이상일 때 차액에서 3억원을 뺀다"],["평가","재산은 시가로 평가하며 매매·감정·수용·경매가 있는 평가기간은 상속은 상속개시일 전후 6개월, 증여는 증여일 전 6개월부터 후 3개월까지이다"],["연부연납","납부세액이 2천만원을 넘으면 담보를 제공하고 연부연납할 수 있고 기간은 일반 상속재산 10년, 일반 증여재산 5년이다"]]}],"20":[{"t":"table","title":"조세포탈과 세금계산서 범죄","head":["항목","내용"],"rows":[["조세포탈죄 형량","사기나 그 밖의 부정한 행위로 조세를 포탈하거나 환급·공제를 받으면 2년 이하 징역 또는 포탈세액등의 2배 이하 벌금이다"],["가중","포탈세액등이 3억원 이상이면서 신고·납부할 세액의 30% 이상이거나 5억원 이상이면 3년 이하 징역 또는 3배 이하 벌금이고 징역과 벌금을 병과할 수 있으며 상습범은 형의 2분의 1을 가중한다"],["감경","법정신고기한 후 2년 이내 수정신고나 6개월 이내 기한 후 신고를 하면 형을 감경할 수 있다"],["부정한 행위","이중장부, 거짓 증빙 작성·수취, 장부 파기, 재산 은닉, 고의적 장부 미작성처럼 부과·징수를 불가능하게 하거나 현저히 곤란하게 하는 적극적 행위이고 착오로 장부를 안 쓰거나 단순히 신고하지 않은 것은 해당하지 않는다"],["기수시기","신고납부 세목은 신고·납부기한이 지난 때이고 부과 세목은 정부 결정 후 납부기한이 지난 때이나 포탈 목적으로 신고하지 않아 결정할 수 없으면 신고기한이 지난 때이다"],["고발과 공소시효","국세청장·지방국세청장·세무서장의 고발이 없으면 공소를 제기할 수 없고 공소시효는 7년이며 조세범 처벌법의 조세는 관세를 제외한 국세이다"],["1년 이하 징역","세금계산서 미발급·거짓 기재 발급, 통정한 미수취·거짓 수취, 매출처별 합계표 거짓 제출은 1년 이하 징역 또는 공급가액×세율의 2배 이하 벌금이다"],["3년 이하 징역","재화·용역의 공급 없이 세금계산서·계산서를 발급하거나 받은 행위와 합계표 거짓 제출은 3년 이하 징역 또는 3배 이하 벌금으로 징역과 벌금을 병과할 수 있다"],["알선·중개","알선·중개자도 같은 형이며 세무사·공인회계사·변호사가 알선하면 2분의 1을 가중한다"],["그 밖의 판단","실제 공급받은 자가 아닌 다른 사람에게 발급하면 미발급죄가 되고 거래 없는 발급죄는 세금계산서마다 1죄이며 합계표를 내지 않은 것은 가산세 대상일 뿐 범죄가 아니다"]]},{"t":"table","title":"그 밖의 범칙행위","head":["행위","처벌"],"rows":[["체납처분 면탈 목적의 재산 은닉·거짓 계약","3년 이하 징역 또는 3천만원 이하 벌금"],["포탈 증거인멸 목적으로 법정신고기한이 지난 날부터 5년 이내에 장부를 소각·파기","2년 이하 징역 또는 2천만원 이하 벌금"],["세무대리인의 거짓 신고와 타인 명의 사업자등록 이용","2년 이하 징역 또는 2천만원 이하"],["신고하지 않게 선동·교사하거나 명의를 빌려주면","1년 이하 징역 또는 1천만원 이하 벌금"],["원천징수의무자가 징수하지 않으면","1천만원 이하 벌금"],["징수하고 납부하지 않으면","2년 이하 징역 또는 2천만원 이하 벌금"],["면세유 부정유통","3년 이하 징역 또는 5배 이하"],["가짜석유 포탈","5년 이하 징역 또는 5배 이하 벌금"]]},{"t":"table","title":"정상가격과 상호합의","head":["항목","내용"],"rows":[["정상가격","거주자와 국외특수관계인의 국제거래 가격이 정상가격보다 낮거나 높으면 정상가격을 기준으로 결정·경정하고 같은 방법으로 여러 과세연도의 정상가격을 산출해 일부 연도를 경정하면 나머지 연도도 그 가격으로 경정한다"],["산출방법","비교가능 제3자 가격방법(특수관계 없는 독립 사업자 간 가격), 재판매가격방법(재판매가에서 통상이윤을 뺀 가격), 원가가산방법, 거래순이익률방법, 이익분할방법 가운데 가장 합리적인 방법을 고르며 순서는 없고 무형자산 거래는 비교가능 제3자 가격방법과 이익분할방법을 우선한다"],["국제거래에서 자산을 시가보다 비싸거나 싸게 매매","부당행위계산 부인이 아니라 정상가격 과세조정을 적용한다"],["대응조정","체약상대국이 국외특수관계인과의 거래가격을 조정하고 상호합의절차가 종결되면 거주자는 수정신고나 경정청구를 할 수 있고 과세당국은 그 합의에 따라 조정할 수 있다"],["상호합의절차","개시 신청은 국세청장에게 하고 체약상대국에 개시를 요청한 경우 개시일은 상대국 권한 있는 당국에게서 수락 통보를 받은 날이며 개시일부터 종료일까지는 불복청구기간·결정기간에 넣지 않는다"],["사전승인","정상가격 산출방법 사전승인은 적용하려는 최초 과세연도 개시일의 전날까지 국세청장에게 신청하고 일방적 사전승인을 받아 과실이 없다고 판정되면 과소신고가산세를 부과하지 않는다"]]},{"t":"table","title":"과다차입·유보소득·해외자료","head":["항목","내용"],"rows":[["과다차입 손금불산입","국외지배주주에게서 빌린 금액이 그 출자금액의 2배(금융업 6배)를 넘으면 초과분의 이자는 손금불산입하여 배당으로 처분하고 국외지배주주의 지급보증으로 제3자에게 빌린 부분은 기타사외유출로 처분한다"],["이자율이 다르면","높은 이자율의 차입금부터 초과분에 넣고 건설자금이자는 대상에서 빼며 이 규정은 법인세법의 지급이자 손금불산입보다 먼저 적용한다"],["과다이자 손금불산입","국외특수관계인에게 지급한 순이자비용이 조정소득금액(감가상각비와 순이자비용을 빼기 전 소득)의 30%를 넘으면 초과액을 손금불산입하여 기타사외유출로 처분한다"],["특정외국법인","실제부담세액이 실제발생소득에 법인세 최고세율의 70%를 곱한 금액 이하인 지역의 외국법인으로서 내국인과 특수관계가 있으면 특정외국법인이고 사업연도 말 현재 발행주식의 10% 이상을 직접·간접 보유한 내국인이 대상이다"],["배당간주","배당 가능 유보소득에 보유비율을 곱한 금액을 사업연도 종료일 다음 날부터 60일이 되는 날이 속하는 내국인의 과세연도의 익금 또는 배당소득에 넣고 나중에 실제 배당하면 이월익금으로 본다"],["선박·항공기·장비 임대","주된 사업이면 현지에 고정시설을 두고 스스로 사업을 관리해도 배당간주를 적용하고 유보소득은 법인마다 따로 계산하며 임의적립금 처분액은 유보소득에서 빼지 않는다"],["국외재산 증여","거주자(국내에 본점을 둔 비영리법인 포함)가 비거주자에게 국외재산을 증여하면 증여자가 증여세를 내고 수증자가 특수관계인이 아니며 외국에서 증여세가 부과(면제 포함)되면 납부의무를 면제한다"],["해외금융계좌","매월 말일 중 어느 하루라도 해외금융계좌 잔액 합계가 5억원을 넘는 거주자·내국법인은 다음 해 6월 1일부터 30일까지 신고하고 명의자와 실질적 소유자가 다르면 둘 다 보유한 것으로 보며 국가·지방자치단체·공공기관은 면제된다"],["해외직접투자","해외직접투자를 한 거주자·내국법인은 과세기간(사업연도) 종료일이 속하는 달의 말일부터 6개월 이내에 해외직접투자명세등을 내고 주식 양도나 청산으로 투자가 끝난 해에도 제출한다"]]}]};
