(window.TNQ=window.TNQ||[]).push({"terms":{"연대납세의무자":{"d":"같은 국세에 대해 각자가 전액을 납부할 의무를 지는 납세의무자.","r":["제2차 납세의무자"]},"제2차 납세의무자":{"d":"주된 납세자가 체납해 징수가 부족할 때 보충적으로 납세의무를 지는 사람.","r":["연대납세의무자"]},"경정청구":{"d":"신고한 세액이 과다한 납세자가 세액을 바로잡아 달라고 청구하는 것.","r":["수정신고"]},"수정신고":{"d":"이미 신고한 과세표준과 세액이 적을 때 늘려서 다시 신고하는 것.","r":["경정청구"]},"가산세":{"d":"세법상 의무를 이행하지 않은 납세자에게 본세에 더해 부과하는 금전 제재.","r":[]},"참가압류":{"d":"이미 압류된 재산에 다시 압류를 하는 대신 교부청구의 효력을 갖게 하는 압류.","r":[]},"공매":{"d":"압류한 재산을 경쟁입찰이나 경매로 팔아 체납세금에 충당하는 절차.","r":[]},"구분경리":{"d":"비영리법인이 수익사업과 고유목적사업의 자산과 손익을 따로 나누어 기록하는 것.","r":[]},"기타사외유출":{"d":"사외유출된 소득의 귀속자가 법인세 과세로 끝나 추가 소득세 부담이 없는 소득처분.","r":[]},"의제배당":{"d":"실제 배당은 아니지만 자본전입이나 합병 등으로 받은 이익을 배당으로 보는 것.","r":[]},"결산조정":{"d":"장부에 비용으로 계상해야만 손금으로 인정되는 세무조정 방식.","r":["신고조정"]},"신고조정":{"d":"장부에 반영하지 않아도 신고서에서 조정해 손금이나 익금으로 인정하는 세무조정 방식.","r":["결산조정"]},"작업진행률":{"d":"공사 등의 누적 발생원가를 총공사예정원가로 나눈 비율로 수익과 비용을 배분하는 기준.","r":[]},"상각범위액":{"d":"세법이 인정하는 한 사업연도의 감가상각비 한도 금액.","r":["즉시상각의제"]},"즉시상각의제":{"d":"자본적 지출을 비용으로 처리했을 때 감가상각비로 계상한 것으로 보는 규정.","r":["상각범위액"]},"부당행위계산":{"d":"특수관계인과 거래하며 조세 부담을 부당하게 줄인 경우 시가로 다시 계산하는 규정.","r":[]},"기업업무추진비":{"d":"업무와 관련해 거래처 등에 지출하는 접대와 선물 같은 비용으로 손금 한도가 있다.","r":[]},"기부금":{"d":"사업과 직접 관련 없이 무상으로 지출하는 금전이나 자산의 가치.","r":[]},"이월결손금":{"d":"과거 사업연도에 발생한 결손금 중 소득에서 공제하지 못하고 넘어온 금액.","r":[]},"최저한세":{"d":"각종 감면을 받아도 최소한 내야 하도록 정한 세액의 하한.","r":[]},"중간예납":{"d":"사업연도 중간에 미리 세금의 일부를 납부하는 제도.","r":[]},"자산조정계정":{"d":"적격합병에서 자산을 시가로 계상하며 생긴 시가와 장부가액의 차액을 두는 계정.","r":[]},"연결납세방식":{"d":"모회사와 완전지배 자회사를 하나의 과세 단위로 묶어 법인세를 계산하는 방식.","r":[]},"청산소득":{"d":"해산한 법인의 잔여재산가액에서 자기자본을 뺀 금액으로 법인세 과세 대상이다.","r":[]},"비거주자":{"d":"거주자가 아닌 개인으로 국내원천소득에 대해서만 소득세 납세의무를 진다.","r":[]},"위법소득":{"d":"횡령이나 불법으로 얻은 소득으로 소득세 과세 대상에 포함된다.","r":[]},"비영업대금이익":{"d":"금전 대여를 사업으로 하지 않는 사람이 빌려주고 받는 이자 성격의 이익.","r":[]},"출자공동사업자":{"d":"공동사업에 출자하되 경영에 참여하지 않거나 손익분배만 받는 구성원.","r":[]},"종합과세":{"d":"여러 종류의 소득을 합산해 누진세율로 과세하는 방식.","r":["분리과세"]},"분리과세":{"d":"다른 소득과 합산하지 않고 원천징수 등으로 납세의무를 끝내는 과세 방식.","r":["종합과세"]},"간주임대료":{"d":"임대보증금에 정기예금이자율을 곱해 임대료처럼 보아 과세하는 금액.","r":[]},"연금계좌":{"d":"연금저축과 퇴직연금 계좌처럼 세제 혜택을 주는 연금 목적 계좌.","r":[]},"이연퇴직소득":{"d":"퇴직소득을 연금계좌에 넣어 퇴직소득세 징수를 미룬 금액.","r":["연금계좌"]},"환산급여":{"d":"퇴직소득세를 계산할 때 퇴직소득을 근속연수로 나누고 12를 곱해 연 단위로 바꾼 금액.","r":[]},"조정대상지역":{"d":"주택 가격 급등 우려로 지정되어 양도소득세 등에서 규제가 강화되는 지역.","r":[]},"장기보유특별공제":{"d":"토지와 건물을 오래 보유한 경우 양도차익에서 일정 비율을 빼 주는 공제.","r":[]},"원천징수":{"d":"소득을 지급하는 자가 세금을 미리 떼어 국가에 대신 납부하는 제도.","r":[]},"영세율":{"d":"수출 등에 0%의 세율을 적용해 부가가치세 부담을 완전히 없애는 제도.","r":["면세"]},"면세":{"d":"일정한 재화와 용역에 부가가치세를 부과하지 않는 제도로 매입세액은 공제되지 않는다.","r":["영세율"]},"공급시기":{"d":"부가가치세에서 재화와 용역이 공급된 것으로 보는 시점.","r":[]},"의제매입세액":{"d":"면세 농산물 등을 원재료로 쓸 때 매입세액을 낸 것으로 보고 공제하는 세액.","r":[]},"세금계산서":{"d":"공급자가 공급가액과 세액을 적어 공급받는 자에게 발급하는 거래 증빙.","r":[]},"간이과세자":{"d":"직전 연도 공급대가가 일정 금액 미만인 개인사업자에게 세부담을 덜어 주는 과세 유형.","r":[]},"일괄공제":{"d":"기초공제와 인적공제를 합친 금액 대신 5억원을 한꺼번에 공제받는 방식.","r":[]},"연부연납":{"d":"상속세나 증여세를 여러 해에 걸쳐 나누어 내도록 허용하는 제도.","r":[]},"정상가격":{"d":"특수관계 없는 독립된 사업자 사이의 거래라면 형성되었을 가격.","r":[]},"상호합의절차":{"d":"국제적 이중과세를 해소하려고 체약상대국 과세당국끼리 협의하는 절차.","r":["정상가격"]},"특정외국법인":{"d":"세부담이 낮은 지역에 있는 내국인과 특수관계인 외국법인으로 유보소득 배당간주 대상.","r":[]}},"notes":{"1,200만원(중소기업 3,600만원)에 사업연도 월수/12를 곱하고 수입금액 한도를 더한다":"기업업무추진비의 기본한도는 1,200만원에 사업연도 월수를 12로 나눈 비율을 곱하고 수입금액 한도를 더하며 중소기업은 3,600만원입니다.","10%, 부정 과소신고는 40%이다":"과소신고가산세율은 10%이고 부정행위로 과소신고하면 40%로 높아집니다.","10년, 부정행위·무신고·거짓신고는 15년이다":"상속세와 증여세의 제척기간은 10년이지만 부정행위와 무신고와 거짓신고는 15년으로 깁니다.","10년 동안 배우자에게서 6억원, 직계존속에게서 5천만원(미성년자 2천만원), 직계비속에게서 5천만원, 4촌 이내 혈족·3촌 이내 인척에게서 1천만원을 공제한다":"증여재산공제는 10년 동안 배우자에게서 6억원 직계존속에게서 5천만원 미성년자는 2천만원 직계비속에게서 5천만원 친족에게서 1천만원입니다.","15%이며 교복은 1인당 50만원 한도이고 배우자·자녀의 대학원비와 사설학원비는 공제하지 않는다":"교육비 세액공제는 공제율이 15%이고 교복은 1인당 50만원이 한도이며 배우자와 자녀의 대학원비와 사설학원비는 제외됩니다.","1~11월분 근로소득과 1~11월 퇴직자의 퇴직소득을 12월 31일까지 지급하지 않으면 12월 31일에, 12월분 근로소득을 다음 연도 2월 말일까지 지급하지 않으면 2월 말일에 지급한 것으로 본다":"근로소득과 퇴직소득은 해를 넘겨 지급하지 않더라도 12월 31일이나 다음 해 2월 말일에 지급한 것으로 간주해 원천징수합니다.","1년 미만 70%, 2년 미만 60%이다":"주택과 조합원입주권과 분양권은 1년 미만 보유하면 70% 2년 미만 보유하면 60%의 세율이 적용됩니다.","1년 미만 보유 토지·건물 50%, 1년 이상 2년 미만 40%이다":"토지와 건물은 1년 미만 보유하면 50% 1년 이상 2년 미만 보유하면 40%의 양도소득세율이 적용됩니다.","1년을 넘지 못하고, 변경하려면 직전 사업연도 종료일부터 3개월 이내에 신고한다":"사업연도는 1년을 넘을 수 없고 변경하려면 직전 사업연도 종료일부터 3개월 안에 신고해야 합니다.","1년 이상 거주한 주택은 세대전원이 취학·근무상 형편·질병 요양 등으로 다른 시·군으로 옮기면 2년 미만 보유여도 비과세하나 사업상 형편은 사유가 아니다":"1년 이상 거주한 주택은 취학이나 근무나 질병 요양으로 세대가 다른 시군으로 옮기면 보유기간이 짧아도 비과세하나 사업상 사유는 제외됩니다.","1년 이하 징역 또는 1천만원 이하 벌금":"신고하지 않게 선동하거나 교사하거나 명의를 빌려주면 1년 이하 징역 또는 1천만원 이하 벌금에 처합니다.","1월 1일부터 6월 30일까지를 중간예납기간으로 하여 직전 과세기간 세액으로 정한 중간예납기준액의 2분의 1을 고지하고 11월 30일까지 납부한다":"소득세 중간예납은 1월 1일부터 6월 30일까지를 기간으로 하여 직전 세액으로 정한 중간예납기준액의 2분의 1을 11월 30일까지 냅니다.","20%, 부정행위 무신고는 40%(역외거래 60%)":"무신고가산세율은 20%이고 부정행위로 무신고하면 40%이며 역외거래의 부정행위면 60%입니다.","2002.1.1. 이후 납입분에 해당하는 부분만 과세하고, 수입시기는 연금을 지급받기로 한 날이다":"공적연금은 2002.1.1. 이후 낸 보험료에 해당하는 부분만 과세하며 연금을 받기로 정해진 날이 수입시기입니다.","2012~2019년 근무분은 직전 3년 연평균 급여×1/10×근속연수×3배, 2020년 이후 근무분은 직전 3년 연평균 급여×1/10×근속연수×2배를 한도로 하고 넘는 금액은 근로소득이다":"임원 퇴직소득은 근무 기간별로 직전 3년 연평균 급여의 10분의 1에 근속연수와 3배 또는 2배를 곱한 금액이 한도이고 초과분은 근로소득입니다.","2025.12.23 개정 세율은 2억원 이하 10%, 2억원 초과 200억원 이하 20%, 200억원 초과 3천억원 이하 22%, 3천억원 초과 25%이다":"최근 개정된 법인세율은 과세표준 구간이 올라갈수록 10%에서 25%까지 네 단계로 커집니다.","2년 이상 보유하고 취득 당시 조정대상지역 주택은 보유기간 중 2년 이상 거주해야 하며, 양도가액 12억원을 넘는 고가주택은 초과분을 과세한다":"주택 비과세는 보유 2년 이상이 기본이고 조정대상지역 취득이면 거주 2년 이상도 필요하며 12억원 초과 고가주택은 초과분을 과세합니다.","2년 이상 사업에 쓴 자산을 특수관계 없는 다른 내국법인이 2년 이상 쓴 같은 종류 사업용자산과 교환(3 이상 법인 간 교환 포함)하고 교환일이 속하는 사업연도 종료일까지 사업에 쓰면 양도차익 상당액을 손금에 넣을 수 있다":"사업에 오래 쓴 자산을 특수관계 없는 법인의 같은 종류 자산과 바꾸고 계속 사업에 쓰면 교환차익을 당장 과세하지 않고 손금에 넣습니다.","2년 이하 징역 또는 2천만원 이하":"세무대리인의 거짓 신고와 타인 명의 사업자등록 이용은 2년 이하 징역 또는 2천만원 이하 벌금에 처합니다.","2년 이하 징역 또는 2천만원 이하 벌금":"남의 명의로 사업자등록을 하면 2년 이하 징역 또는 2천만원 이하 벌금에 처합니다.","2억원이고 자녀(태아 포함)는 1명당 5천만원, 65세 이상 연로자는 1명당 5천만원을 공제한다":"상속공제 중 기초공제는 2억원이고 자녀와 65세 이상 연로자는 1명당 5천만원씩 인적공제가 따로 붙습니다.","2회 이상 나누어 받고 인도일 다음 날부터 최종 할부금 지급기일까지 1년 이상이어야 하며 받기로 한 부분만 그 과세기간 과세표준에 넣는다":"장기할부판매는 두 번 이상 나누어 받고 인도 후 최종 지급까지 1년 이상 걸려야 하며 받기로 한 몫만 그 과세기간에 넣습니다.","2회 이상 방문하고 처음과 마지막 방문 사이가 3일 이상이어야 한다":"수취인이 없다는 이유로 공시송달을 하려면 2회 이상 방문하고 첫 방문과 마지막 방문 사이가 3일 이상이어야 합니다.","3년 미만의 기간마다 하는 주기적 수선도 같다":"3년 미만의 기간마다 하는 주기적 수선도 소액수선비 특례와 같이 비용 처리한 금액을 그대로 손금으로 봅니다.","3년 이상 보유한 토지·건물은 6%부터 해마다 2%포인트씩 늘어 15년 이상 30%를 공제하고, 1세대1주택 고가주택은 보유 연 4%·거주 연 4%로 각 40%, 최대 80%이다":"장기보유특별공제는 오래 가질수록 공제율이 높아지며 1세대1주택 고가주택은 보유와 거주 기간을 각각 따져 최대 80%까지 줍니다.","3년 이하 징역 또는 3천만원 이하 벌금":"체납처분을 피하려고 재산을 숨기는 행위는 3년 이하 징역 또는 3천만원 이하 벌금입니다.","3년 이하 징역 또는 5배 이하":"면세유를 부정하게 유통하면 3년 이하 징역 또는 부정 이득의 5배 이하 벌금을 받습니다.","3주택 이상을 소유하고 보증금 합계가 3억원을 넘으면 3억원 초과분의 60%에 정기예금이자율을 곱한 금액을 간주임대료로 총수입금액에 넣는다":"주택 수와 보증금 합계가 일정 기준을 넘는 임대인은 초과 보증금의 일정 비율에 정기예금이자율을 곱한 간주임대료를 수입에 넣습니다.","3회 이상 체납, 각 1년 경과, 합계 2억원 이상 등을 갖추면 법원이 30일 범위에서 결정한다":"3회 이상 체납하고 각각 1년이 지나며 합계 2억원 이상이면 법원이 30일 범위에서 감치를 결정할 수 있습니다.","50%(등록임대주택 60%)이다":"분리과세 주택임대소득의 필요경비율은 50%이고 등록임대주택이면 60%를 적용합니다.","500만원 미만이면 500만원, 1천만원을 넘으면 1천만원이고 봉안시설·자연장지 비용은 500만원까지 따로 더한다":"장례비용은 500만원을 최소로 하고 1천만원을 상한으로 정하며 봉안시설과 자연장지 비용은 500만원까지 따로 공제합니다.","5년 이하 징역 또는 5배 이하 벌금":"가짜석유로 조세를 포탈하면 5년 이하 징역 또는 5배 이하 벌금에 처합니다.","5천만원 이상 체납자 중 요건을 갖춘 자에 대해 요청해야 한다":"5천만원 이상 체납한 사람 중 요건에 해당하는 사람에 대해서는 출국금지를 요청해야 합니다.","60세 이상 직계존속 동거봉양 합가는 10년 이내":"60세 이상 직계존속을 모시려고 합가하면 합가한 날부터 10년 안에 먼저 판 주택은 비과세 특례를 받는다는 내용입니다.","70세 이상 경로우대 100만원, 장애인 200만원, 종합소득금액 3천만원 이하 여성의 부녀자공제 50만원, 한부모 100만원을 더한다":"추가공제는 70세 이상 경로우대 100만원과 장애인 200만원과 부녀자공제 50만원과 한부모 100만원이 있습니다.","800만원을 넘는 금액은 다음 사업연도부터 800만원씩 나누어 손금에 넣는다":"업무용승용차 처분손실 중 800만원을 넘는 금액은 다음 사업연도부터 800만원씩 나눠 손금에 넣습니다.","8세 이상 공제대상 자녀·손자녀가 1명이면 연 25만원, 2명이면 55만원, 3명 이상이면 55만원에 2명 초과 1명당 40만원을 더한다":"자녀세액공제는 자녀 수가 늘어날수록 공제액이 커지는 구조이며 2명을 넘는 자녀는 1명마다 40만원이 더해집니다.","900만원이 한도이고 분리과세연금소득에는 적용하지 않는다":"연금소득공제는 한도가 900만원이고 분리과세되는 연금소득에는 적용하지 않습니다.","가중평균차입이자율이 원칙이고, 이를 계산할 때 특수관계인에게서 빌린 차입금은 뺀다":"금전 대여의 시가는 가중평균차입이자율이 원칙이며 그 이자율을 계산할 때 특수관계인에게서 빌린 차입금은 뺍니다.","각 사업연도 소득, 청산소득, 토지등 양도소득, 미환류소득에 과세된다":"영리 내국법인에는 사업연도 소득과 청산소득과 토지 양도소득과 미환류소득이 법인세 과세 대상입니다.","각 사업연도 소득에서 이월결손금, 비과세소득, 소득공제를 차례로 뺀 금액이다":"법인세 과세표준은 각 사업연도 소득에서 이월결손금과 비과세소득과 소득공제를 순서대로 뺀 금액입니다.","감가상각자산은 면세비율이 취득 때나 직전 재계산 때보다 5%포인트 이상 증감하면 매입세액×(1−체감률×경과된 과세기간 수)×증감비율로 재계산하고 체감률은 건물·구축물 5%, 그 밖의 자산 25%이다":"감가상각자산의 면세비율이 크게 바뀌면 체감률과 경과 과세기간을 반영한 계산식으로 재계산하며 체감률은 건물 5% 그 밖의 자산 25%입니다.","감가상각·처분 때 익금·손금으로 정리된다":"자산조정계정은 해당 자산을 감가상각하거나 처분할 때 익금이나 손금으로 풀려 없어집니다.","감면 후 세액이 감면 전 과세표준에 최저한세율을 곱한 금액보다 적으면 그 차액만큼 감면을 배제한다":"감면을 적용한 뒤 세액이 최저한세율로 계산한 금액에 못 미치면 모자라는 만큼은 감면을 인정하지 않습니다.","감정평가가액, 기준시가, 장부가액 순으로 하며 기준시가가 없는 기계장치가 섞이면 먼저 장부가액 비율로 나누고 건물·토지는 기준시가 비율로 다시 나눈다":"일괄 공급 대가를 나눌 때는 감정평가가액과 기준시가와 장부가액 순으로 쓰고 기계장치가 섞이면 장부가액 비율을 먼저 씁니다.","강연료·산업재산권 대여·공익사업 관련 지상권 대여 등은 60%를 필요경비로 하되 실제 경비가 더 크면 실제 경비를 쓴다":"강연료와 산업재산권 대여 등은 받은 금액의 60%를 필요경비로 보며 실제 경비가 더 크면 실제 경비를 씁니다.","강제경매로 넘어가는 것도 양도이고 파산선고에 의한 처분만 비과세이다":"강제경매로 소유권이 넘어가는 것도 양도에 해당하고 파산선고에 따른 처분만 양도소득세가 비과세입니다.","강제징수·경매 개시, 법인 해산, 국세 포탈 행위, 납세관리인 없이 국내 주소·거소를 두지 않게 된 경우 등에는 납부기한 전이라도 이미 납세의무가 확정된 국세를 징수할 수 있다":"강제징수나 법인 해산이나 포탈 행위처럼 징수가 위험해지는 사유가 있으면 납부기한 전에도 확정된 국세를 징수할 수 있습니다.","강제징수하고 법인이 합병으로 소멸해도 강제징수를 계속한다":"가압류나 가처분이 된 재산도 강제징수할 수 있고 법인이 합병으로 소멸해도 이미 시작한 강제징수는 계속됩니다.","같은 고용주가 근무지 변경으로 월급여를 나누어 지급하면 변경된 근무지에서 월급여액 전액을 원천징수한다":"같은 고용주가 근무지 변경으로 월급여를 나눠 주면 바뀐 근무지에서 월급여액 전체를 기준으로 원천징수합니다.","같은 기간·금액 기준으로 진 채무의 용도가 불분명해도 같고 국가·금융회사 등이 아닌 자에 대한 채무로서 상속인이 변제할 의무가 없다고 보이는 것도 과세가액에 넣는다":"같은 기간과 금액 기준으로 진 채무의 용도가 불분명해도 같고 상속인이 갚을 의무가 없다고 보이는 채무도 과세가액에 넣습니다.","개별소비세 과세 승용자동차의 구입·유지 매입세액은 제조업자가 업무에 써도 불공제이고 운수업 등에 직접 영업으로 쓰는 것만 공제한다":"개별소비세가 붙는 승용자동차의 구입과 유지 매입세액은 업무용이어도 공제하지 않고 영업에 직접 쓰는 업종만 공제합니다.","개별소비세 과세 승용차가 대상이고, 운수업·자동차판매업 등에서 영업에 직접 쓰는 차와 연구개발용 차는 빠진다":"업무용승용차는 개별소비세가 과세되는 승용차이며 운수업이나 판매업의 영업용 차와 연구개발용 차는 제외됩니다.","개별자산별 수선비가 600만원 미만이거나 직전 사업연도 말 재무상태표상 자산가액(취득가액-감가상각누계액)의 5% 미만이면 비용 처리한 금액을 그대로 손금으로 인정한다":"자산별 수선비가 600만원 미만이거나 직전 말 자산가액의 5% 미만이면 비용 처리한 금액을 그대로 손금으로 인정합니다.","개시 신청은 국세청장에게 하고 체약상대국에 개시를 요청한 경우 개시일은 상대국 권한 있는 당국에게서 수락 통보를 받은 날이며 개시일부터 종료일까지는 불복청구기간·결정기간에 넣지 않는다":"상호합의절차는 국세청장에게 신청하고 상대국의 수락 통보를 받은 날이 개시일이며 개시일부터 종료일까지는 불복청구기간과 결정기간에 넣지 않습니다.","개시일부터 분할등기일까지가 1사업연도이다":"분할로 해산하는 법인은 사업연도 개시일부터 분할등기일까지를 하나의 사업연도로 봅니다.","개시일 전 15년 이내에 발생해 신고·결정된 것만 공제하고, 중소기업·회생계획 이행 기업 외에는 소득의 80%가 한도이다":"이월결손금은 개시일 전 15년 이내에 생겨 신고나 결정된 것만 공제하고 중소기업 등이 아니면 소득의 80%까지만 공제합니다.","개인 명의 차량을 다른 개인이 운용하는 운수업은 등록된 개인이 업무를 총괄하는 장소가 사업장이다":"운수업은 개인 명의의 차량을 다른 개인이 운용해도 등록된 개인이 사업을 총괄하는 곳을 사업장으로 정합니다.","개인사업자는 예정고지세액을 내고 50만원 미만이면 징수하지 않으며 제1기분 고지서는 4월 1일부터 10일까지 발부한다":"개인사업자는 예정고지세액이 50만원 미만이면 걷지 않고 제1기분은 4월 1일부터 10일 사이에 고지서를 보냅니다.","개인·중소기업 4/104(과자점·떡방앗간 등 개인은 6/106), 그 밖은 2/102이다":"제조업의 의제매입세액 공제율은 개인과 중소기업이 4/104이고 과자점이나 떡방앗간 등 개인은 6/106이며 그 밖은 2/102입니다.","거래단위별 취득가액 100만원 이하 자산은 사업에 쓴 날이 속하는 사업연도에 비용 처리하면 손금이다":"거래 한 건의 취득가액이 작은 자산은 사업에 쓴 사업연도에 곧바로 비용으로 처리하면 손금으로 인정합니다.","거래처 1인당 연 5만원을 넘는 광고선전물품, 정당한 사유 없이 포기한 거래처 채권, 법인인 직원 조직(조합·단체)에 낸 복리시설비":"거래처 1인당 연 5만원을 넘는 광고선전물품과 정당한 사유 없이 포기한 거래처 채권과 직원 단체에 낸 복리시설비는 기업업무추진비에 포함합니다.","거주자(국내에 본점을 둔 비영리법인 포함)가 비거주자에게 국외재산을 증여하면 증여자가 증여세를 내고 수증자가 특수관계인이 아니며 외국에서 증여세가 부과(면제 포함)되면 납부의무를 면제한다":"거주자가 비거주자에게 국외재산을 증여하면 증여자가 증여세를 내되 수증자가 특수관계인이 아니고 외국에서 증여세가 부과되면 납부의무를 면제합니다.","거주자와 국외특수관계인의 국제거래 가격이 정상가격보다 낮거나 높으면 정상가격을 기준으로 결정·경정하고 같은 방법으로 여러 과세연도의 정상가격을 산출해 일부 연도를 경정하면 나머지 연도도 그 가격으로 경정한다":"국제거래 가격이 정상가격과 다르면 정상가격으로 결정하며 여러 과세연도를 같은 방법으로 산출해 일부를 경정하면 나머지도 같은 가격으로 경정합니다.","거주자의 소득세 납세지는 소득 종류와 관계없이 주소지이고 주소지가 없으면 거소지이다":"거주자의 소득세 납세지는 소득이 어떤 종류이든 주소지이고 주소지가 없을 때만 거소지를 납세지로 삼습니다.","건물의 실지거래가액이 공급가액이고 가액 구분이 불분명하거나 안분계산액과 30% 이상 차이 나면 안분한다":"토지와 건물을 한꺼번에 팔 때 건물의 실지거래가액이 공급가액이지만 구분이 불분명하거나 안분액과 크게 어긋나면 안분합니다.","건축물은 정액법, 기계장치 등은 정률법을 적용한다":"상각방법을 신고하지 않으면 건축물은 정액법을 쓰고 기계장치 같은 자산은 정률법을 적용합니다.","견본품 인도, 사후 무료서비스용 사용, 과세사업의 수선비 등 대체 사용, 자기적립마일리지로만 결제받은 증여":"견본품 인도와 사후 무료서비스용 사용과 과세사업의 수선비 대체 사용은 재화의 공급으로 보지 않습니다.","결산·분배 요건이 없어도 배당소득이다":"국외 집합투자기구에서 생긴 이익은 결산과 분배 요건을 갖추지 않았더라도 배당소득으로 봅니다.","결산조정이 원칙이나 일부는 신고조정도 허용된다":"감가상각비와 일시상각충당금은 장부에 반영하는 결산조정이 원칙이고 일부만 신고조정을 허용합니다.","결산확정일이 아니라 근로를 제공한 날이다":"인정상여의 귀속시기는 결산을 확정한 날이 아니라 근로를 실제로 제공한 날입니다.","결손금 일부만 소급공제 신청할 수도 있다":"결손금 전부가 아니라 일부 금액만 골라서 소급공제를 신청하는 것도 허용됩니다.","결정·판결 확정 전에 공매할 수 없으나 부패·감량되기 쉬운 재산은 예외이다":"불복이나 행정소송이 진행 중이면 결정이나 판결이 확정되기 전에 공매하지 못하나 상하기 쉬운 재산은 예외입니다.","결제받은 금액은 공급가액에서 뺀다":"자기적립마일리지로 결제받은 금액은 실제 받은 대가가 아니므로 공급가액에서 뺍니다.","겸용주택 전부를 주택으로 볼 때 고가주택 판단은 전체 실지거래가액으로 한다":"겸용주택 전부를 주택으로 보는 경우 고가주택 여부는 전체 실지거래가액을 기준으로 판단합니다.","경상경비 외의 목적으로 내는 협회 특별회비와 할인율 변동에 따른 책임준비금 평가 증가액":"일상 경비가 아닌 목적의 협회 특별회비와 할인율 변동에 따른 책임준비금 평가 증가액은 손금이 아닙니다.","경쟁입찰은 문서로, 경매는 구두 등으로 한다":"공매의 매수 신청은 경쟁입찰이면 서면으로 하고 경매이면 말로 하는 등 방식이 다릅니다.","경정청구가 있으면 경정청구일부터 2개월, 불복 결정·판결이 확정되면 확정된 날부터 1년 안에 경정할 수 있다":"제척기간이 지나도 경정청구가 있으면 청구일부터 2개월, 불복 결정이 확정되면 그날부터 1년까지 경정할 수 있습니다.","계약금 외에 2회 이상 나누어 받고 계약금 약정일부터 인도일까지 6개월 이상이어야 한다":"중간지급조건부는 계약금 외에 두 번 이상 나누어 받고 계약금 약정일에서 인도일까지 6개월 이상 걸리는 거래입니다.","계약기간과 관계없이 작업진행률을 기준으로 각 사업연도의 익금과 손금에 넣는 것이 원칙이다":"건설과 제조 같은 용역은 계약기간과 상관없이 작업진행률에 따라 각 사업연도의 익금과 손금에 넣는 것이 원칙입니다.","계약상 지체상금, 전기요금 연체가산금, 산재보험료 연체금, 국유지 사용료 연체료":"계약상 지체상금이나 전기요금 연체가산금 같은 지출은 법적 제재가 아니라 손금으로 인정됩니다.","계약 해제 같은 후발적 사유는 안 날부터 3개월 이내이며, 상속세·증여세도 경정청구 대상이다":"계약 해제처럼 나중에 생긴 사유로 세액이 달라지면 안 날부터 3개월 안에 경정을 청구하며 상속세와 증여세도 대상입니다.","고가매입·저가양도·금전 대여 등은 시가와 거래가액의 차액이 3억원 이상이거나 시가의 5% 이상일 때만 적용한다":"시가와 거래가액의 차이가 3억원 이상이거나 시가의 5% 이상일 때만 고가매입과 저가양도와 금전 대여를 부당행위로 봅니다.","고지·독촉 서류를 각각 송달한다":"연대납세의무자 각자가 별도 납세의무자이므로 고지서와 독촉 서류를 각각에게 따로 송달합니다.","고지하는 날부터 30일 이내로 정한다":"납부고지서의 납부기한은 고지하는 날부터 30일 이내의 날로 정합니다.","공급가액이 직전 과세기간의 3분의 1에 미달하거나 조기환급을 받으려면 예정신고할 수 있다":"공급가액이 직전 과세기간의 3분의 1에 못 미치거나 조기환급을 받으려는 개인사업자는 예정신고를 선택할 수 있습니다.","공급과 직접 관련된 국고보조금·공공보조금":"공급과 직접 관련된 국고보조금과 공공보조금은 대가의 성격이 있어 공급가액에 넣습니다.","공급대가×업종별 부가가치율×10%이고 매입세금계산서 공급대가의 0.5%와 신용카드 발행금액의 1.3%(연 1천만원 한도, 2026년까지)를 빼며 의제매입·대손세액 공제는 없다":"간이과세자의 납부세액은 공급대가에 부가가치율과 10%를 곱한 뒤 매입세금계산서와 카드 발행분 일부를 빼고 의제매입과 대손세액 공제는 없습니다.","공급받는 자에게 주는 판매장려금과 대손금":"공급받는 자에게 주는 판매장려금과 대손금은 과세표준에서 빼지 않고 그대로 포함합니다.","공급시기가 속하는 과세기간 종료일부터 1년 이내에 신청인 관할 세무서장에게 거래사실 확인을 신청한다":"매입자발행세금계산서는 공급시기가 속한 과세기간 종료일부터 1년 안에 관할 세무서장에게 거래사실 확인을 신청해야 합니다.","공급시기는 선적일이므로 선적 전 환가한 선수금은 환가액, 선적 후 받은 잔금은 선적일 기준환율로 계산한다":"수출은 선적일이 공급시기이므로 선적 이전에 환가한 선수금과 이후에 받은 잔금의 환산 기준이 서로 다릅니다.","공급시기의 기준환율로 환산한다":"공급시기 이후에 외화로 받거나 외화로 보유한 경우에는 공급시기의 기준환율로 원화로 환산합니다.","공급시기 이후 받은 세금계산서도 그 과세기간 확정신고기한까지 받으면 공제하고 확정신고기한 다음 날부터 1년 이내에 받아 수정신고서나 경정청구서와 함께 내도 공제한다":"공급시기 이후 받은 세금계산서도 확정신고기한까지 받으면 공제하고 그 뒤 1년 안이면 수정신고나 경정청구와 함께 내 공제받습니다.","공급시기 전에 대가를 받지 않았더라도 거래상대방 요청 등으로 세금계산서를 먼저 발급하면 발급한 금액을 그때의 공급가액으로 한다":"대가를 받기 전이라도 상대방의 요청 등으로 세금계산서를 먼저 발급하면 발급한 금액이 그 시점의 공급가액이 됩니다.","공급자가 위탁자를 공급받는 자로 하고 수탁자 등록번호를 덧붙여 적는다":"위탁매입에서는 공급자가 위탁자를 공급받는 자로 적고 수탁자의 등록번호를 덧붙여 적어 발급합니다.","공동사업장을 1거주자로 보아 소득금액을 계산한 뒤 손익분배비율로 나눈다":"공동사업은 공동사업장을 한 사람의 거주자로 보고 소득금액을 계산한 뒤 각 구성원의 손익분배비율로 나눕니다.","공매예정가격의 10% 이상이다":"공매에 참여하려면 공매예정가격의 10% 이상을 공매보증금으로 내야 합니다.","공적연금소득자가 사망하면 사망일이 속하는 달의 다음다음 달 말일까지 연말정산한다":"공적연금소득자가 사망한 경우에는 사망일이 속하는 달의 다다음 달 말일까지 연말정산을 끝내야 합니다.","공제대상 여부는 과세기간 종료일 현재로 판정하고, 그 전에 사망한 사람은 사망일 전날로 판정한다":"공제대상 판단은 과세기간 종료일 현재 상황을 기준으로 하며 그전에 사망했다면 사망일 전날 상황을 봅니다.","과다신고한 자(기한후신고자 포함)는 법정신고기한이 지난 후 5년 이내에 경정을 청구하고, 결정·경정으로 증가한 세액은 처분을 안 날부터 3개월 이내(5년 한도)에 청구한다":"세금을 많이 신고했다면 법정신고기한이 지난 뒤 5년 안에 경정을 청구하고 처분으로 늘어난 세액은 안 날부터 3개월 안에 청구합니다.","과세가액에서 상속인 아닌 자에게 유증한 재산, 상속 포기로 다음 순위가 받은 재산, 가산한 사전증여재산을 뺀 금액을 한도로 한다":"상속공제의 총한도는 과세가액에서 상속인 아닌 자의 유증과 상속 포기로 다음 순위가 받은 재산과 사전증여재산을 뺀 금액입니다.","과세기간 개시일 현재 사업자가 아닌 자로서 그 해 신규로 사업을 시작한 거주자는 중간예납 의무가 없고 중간예납세액이 50만원 미만이면 징수하지 않는다":"그 해 새로 사업을 시작한 거주자는 중간예납 의무가 없고 중간예납세액이 50만원 미만이면 징수하지 않습니다.","과세기간이 끝난 후 20일 이내에 등록을 신청하면 그 과세기간 기산일까지 역산한 기간분을 공제한다":"사업자등록 전 매입세액은 과세기간이 끝난 후 20일 안에 등록을 신청하면 그 과세기간 기산일까지 거슬러 올라간 기간분을 공제합니다.","과세기간 종료 후 25일 이내 사후 개설되어도 발급한다":"내국신용장이 과세기간 종료 후 25일 이내에 사후 개설되더라도 영세율 세금계산서를 발급합니다.","과세기간 종료 후 3개월이 되는 날까지 지급하지 않으면 그날 지급한 것으로 본다":"출자공동사업자의 배당소득은 과세기간이 끝난 후 3개월이 되는 날까지 지급하지 않으면 그날 지급한 것으로 봅니다.","과세기간 중 사망한 배우자는 공제하지만 이혼한 배우자는 공제하지 않는다":"과세기간 중에 사망한 배우자는 공제대상이지만 이혼한 배우자는 공제대상이 아닙니다.","과세사업에 함께 쓰면 같은 체감 계산에 과세비율을 곱해 공제하고 원재료는 대상이 아니다":"면세사업에만 쓰던 감가상각자산을 과세사업에도 함께 쓰면 같은 체감 계산에 과세비율을 곱해 공제하며 원재료는 대상이 아닙니다.","과세제외금액, 이연퇴직소득, 세액공제받은 납입액과 운용수익 순으로 본다":"연금계좌에서 돈을 뺄 때는 과세제외금액과 이연퇴직소득과 세액공제받은 납입액과 운용수익 순으로 인출한 것으로 봅니다.","과세표준 1억원 이하 10%, 5억원 이하 20%, 10억원 이하 30%, 30억원 이하 40%, 초과분 50%로 상속세와 증여세가 같다":"상속세와 증여세의 세율은 같아서 과세표준 1억원 이하 10% 5억원 이하 20% 10억원 이하 30% 30억원 이하 40% 초과분 50%입니다.","과세표준 3억원 이하 20%, 초과분 25%(중소기업 외 1년 미만 보유 30%)이다":"대주주 주식의 양도소득세율은 과세표준 3억원 이하 20%이고 초과분은 25%이며 중소기업 외 1년 미만 보유는 30%입니다.","과세표준을 12개월로 환산해 세율을 적용한 뒤 월수/12를 곱한다(2023년 기출은 9·19·21·24% 시절 세율로 계산)":"사업연도가 짧을 때는 과세표준을 연 단위로 바꿔 세율을 적용한 뒤 월수 비율만큼 다시 줄여서 세액을 구합니다.","과세하며 세액은 추가이익에 납입금 초과이익 산출세액/납입금 초과이익 비율을 곱해 구한다":"분할로 받는 반환금 추가이익은 과세하며 세액은 추가이익에 납입금 초과이익 산출세액을 납입금 초과이익으로 나눈 비율을 곱해 구합니다.","관련비용 1,500만원 이하는 전액 업무용으로 보고 초과하면 1,500만원/관련비용 비율을 쓴다":"운행기록이 없으면 관련비용이 1,500만원 이하일 때 전액 업무용으로 보고 초과하면 1,500만원을 관련비용으로 나눈 비율을 씁니다.","관련비용 전체에 업무외 비율을 곱한 금액을 먼저 손금불산입하고, 업무사용분 감가상각비 상당액 중 800만원 초과분을 다시 손금불산입하여 이월한다":"리스차량은 관련비용에 업무외 비율을 곱한 금액을 먼저 빼고 업무사용분 감가상각비 상당액 중 800만원 초과분을 다시 빼서 이월합니다.","관리비 중 청소비 같은 용역 대가는 과세표준에 포함한다":"관리비 중에서 청소비처럼 용역의 대가에 해당하는 금액은 임대료와 함께 과세표준에 포함합니다.","광업의 탐광 개발비, 우리사주조합에 출연한 자사주 장부가액, 이사회 결의로 사망 직원 유족에게 계속 주는 학자금":"광업의 탐광 개발비와 우리사주조합에 낸 자사주 장부가액과 사망 직원 유족에게 주는 학자금은 손비로 인정됩니다.","교정시설의 장 등에게 송달한다":"구속되거나 유치된 사람에게는 본인이 아니라 교정시설의 장 등에게 서류를 송달합니다.","교통재해 보험금은 과세대상이 아니고 서화·골동품을 박물관·미술관에 양도한 소득은 비과세이다":"사고로 받는 교통재해 보험금은 과세 대상이 아니고 미술품을 박물관에 넘긴 소득은 세금을 매기지 않습니다.","교환계약, 현물출자, 재화의 소비대차에 따른 차용·반환, 공동사업 건축물의 분할등기 이전":"교환계약과 현물출자와 재화의 소비대차와 공동사업 건축물의 분할등기 이전은 재화의 공급에 해당합니다.","구성원 3분의 2 이상 출석, 출석 과반수 찬성으로 의결한다":"조세심판관합동회의는 구성원 3분의 2 이상이 출석해야 열리고 출석한 사람의 과반수 찬성으로 결정합니다.","국가·지자체, 국방헌금, 이재민 구호금품, 사립학교·국립대학병원 시설비 등은 기준소득금액에서 이월결손금을 뺀 금액의 50%가 한도이다":"국가와 지자체 기부와 국방헌금과 이재민 구호금품 같은 특례기부금은 기준소득금액에서 이월결손금을 뺀 금액의 50%가 한도입니다.","국내사업장 없는 비거주자에게 상품중개·교육지원 용역을 제공하고 외국환은행에서 원화로 받으면 영세율이나 건물 임대는 제외된다":"국내사업장이 없는 비거주자에게 상품중개나 교육지원을 제공하고 원화로 받으면 영세율이지만 건물 임대는 해당하지 않습니다.","국내에 주소를 두거나 183일 이상 거소를 둔 개인이 거주자이고, 주소는 생계를 같이하는 가족과 국내 자산 등 생활관계의 객관적 사실로 판정한다":"거주자는 국내에 주소를 두거나 오래 거소를 둔 개인이며 주소는 가족과 자산 같은 생활관계의 객관적 사실로 따집니다.","국내에 주소를 두면 그날, 거소를 둔 기간이 183일이 되면 그날 거주자가 되며 2과세기간에 걸쳐 183일 이상이어도 된다":"국내에 주소를 두는 날 거주자가 되고 거소 기간이 183일이 되는 날 거주자가 되며 2과세기간에 걸쳐 183일이 넘어도 됩니다.","국내원천소득 중 수익사업 소득에만 과세된다":"비영리 외국법인은 국내에서 생긴 소득 중 수익사업에서 나온 소득에 대해서만 과세됩니다.","국민연금은 환산소득 누계액 비율로, 공무원연금 등 그 밖의 공적연금은 기여금 납입월수 비율로 과세분을 나눈다":"국민연금과 다른 공적연금은 과세 대상 부분을 나누는 기준이 달라 국민연금은 환산소득 누계액이고 나머지는 납입월수입니다.","국세를 내지 않고 잔여재산을 분배하면 청산인과 분배받은 자는 제2차 납세의무를 진다":"해산한 법인이 국세를 내지 않고 잔여재산을 나누면 청산인과 분배받은 사람이 제2차 납세의무를 집니다.","국세청장·지방국세청장·세무서장의 고발이 없으면 공소를 제기할 수 없고 공소시효는 7년이며 조세범 처벌법의 조세는 관세를 제외한 국세이다":"조세포탈은 국세청장과 세무서장 등의 고발이 있어야 공소를 제기할 수 있고 공소시효는 7년이며 대상 조세는 관세를 뺀 국세입니다.","국외사업자에게 용역을 받은 자는 사업자가 아니어도 매입세액공제가 안 되는 부분을 대리납부한다":"국외사업자에게서 용역을 받은 사람은 사업자가 아니더라도 매입세액공제가 안 되는 부분의 부가가치세를 대리납부합니다.","국외 이전을 위해 출국하면 출국하는 날의 다음 날 비거주자가 된다":"국외로 이전하려고 출국하는 개인은 출국하는 날의 다음 날부터 비거주자가 됩니다.","국외지배주주에게서 빌린 금액이 그 출자금액의 2배(금융업 6배)를 넘으면 초과분의 이자는 손금불산입하여 배당으로 처분하고 국외지배주주의 지급보증으로 제3자에게 빌린 부분은 기타사외유출로 처분한다":"국외지배주주에게 빌린 돈이 출자금의 2배를 넘으면 초과분 이자를 배당으로 처분하고 금융업은 6배이며 지급보증 차입분은 기타사외유출입니다.","국외특수관계인에게 지급한 순이자비용이 조정소득금액(감가상각비와 순이자비용을 빼기 전 소득)의 30%를 넘으면 초과액을 손금불산입하여 기타사외유출로 처분한다":"국외특수관계인에게 준 순이자비용이 조정소득금액의 30%를 넘으면 그 초과액을 손금에 넣지 않고 기타사외유출로 처분합니다.","귀속자에 따라 상여·배당·기타소득 등으로 처분하고 증여세를 과세하는 것이 아니다":"부당행위계산으로 익금에 넣은 금액은 귀속자에 따라 상여나 배당이나 기타소득으로 처분하며 증여세를 부과하는 것은 아닙니다.","그 고지는 부과처분과 징수처분의 성질을 함께 가진다":"결정이나 경정을 납부고지서로 통지하면 그 고지는 세액을 정하는 부과처분과 거두는 징수처분의 성질을 함께 가집니다.","그 과세기간의 근로·연금·기타·이자·배당소득금액에서 순서대로 공제한다":"장부로 계산한 사업소득의 결손금은 그 과세기간의 근로와 연금과 기타와 이자와 배당소득금액에서 순서대로 공제합니다.","그 금액에서 특례기부금 손금산입액을 다시 뺀 금액의 10%(사회적기업 30%)가 한도이다":"일반기부금은 기준소득금액에서 이월결손금과 특례기부금 손금산입액을 뺀 금액의 10%가 한도이며 사회적기업은 30%입니다.","그 금액은 자본적 지출, 그에 대한 이자는 손금이다":"연체이자를 원본에 가산했다면 그 가산한 금액은 자본적 지출이고 그 금액에 대해 붙는 이자는 손금입니다.","그 금전으로 국세를 납부할 수 있다":"금전을 담보로 낸 사람은 그 금전으로 국세를 직접 납부할 수 있어 담보가 납부로 바뀝니다.","그 밖의 사적연금이 연 1,500만원 이하이면 분리과세를 선택할 수 있다":"연 1,500만원 이하의 사적연금은 다른 소득과 합치지 않고 따로 세금을 끝내는 방법을 고를 수 있습니다.","그 이전 과세기간 이월결손금이 확인되어도 공제하지 않는다":"제척기간이 지난 뒤에는 그 이전 과세기간의 이월결손금이 확인되더라도 공제하지 않습니다.","그 해 출산·입양한 자녀가 첫째면 30만원, 둘째 50만원, 셋째 이상 70만원을 공제한다":"그 해 출산하거나 입양한 자녀가 첫째이면 30만원 둘째이면 50만원 셋째 이상이면 70만원을 세액에서 공제합니다.","근거 법률에 따라 기부채납된 가액(포함된 부가가치세 제외)이 과세표준이다":"기부채납의 과세표준은 근거 법률에 따라 기부채납된 가액이며 거기에 포함된 부가가치세는 제외합니다.","근로소득공제와 연금소득공제는 소득금액 계산 단계의 공제라서 종합소득공제가 아니다":"근로소득공제와 연금소득공제는 소득금액을 구하는 과정의 공제여서 종합소득공제에 속하지 않습니다.","근로·연금·기타·이자·배당소득금액 순으로 공제하고, 일반 사업 결손금은 같은 해 부동산임대업 소득에서도 공제한다":"사업소득 결손금은 근로와 연금과 기타와 이자와 배당소득금액 순으로 공제하며 일반 사업 결손금은 같은 해 부동산임대업 소득에서도 공제합니다.","금액과 관계없이 비용 처리할 수 있다":"휴대전화와 개인용 컴퓨터는 금액이 크더라도 취득한 사업연도에 곧바로 비용으로 처리할 수 있습니다.","금융소득이 2천만원을 넘으면 2천만원은 14%, 나머지는 기본세율로 계산한 세액과 금융소득 전체를 원천징수세율로 계산하고 다른 소득에 기본세율을 적용한 세액 중 큰 금액을 산출세액으로 한다":"금융소득이 2천만원을 넘으면 두 방식으로 계산한 세액 중 큰 금액을 산출세액으로 삼는 비교과세를 합니다.","금전 외 증여재산을 신고기한까지 돌려주면 처음부터 증여가 없던 것으로 보고 신고기한 후 3개월 이내에 돌려주면 당초 증여는 과세하고 반환분만 과세하지 않는다":"금전이 아닌 증여재산은 신고기한까지 돌려주면 증여가 없던 것으로 보고 기한 후 3개월 안에 돌려주면 반환분만 과세에서 제외합니다.","금전으로 받으면 그 대가, 금전 외의 대가를 받으면 자기가 공급한 재화·용역의 시가가 공급가액이다":"공급가액은 금전으로 받으면 그 금액이고 금전 외의 대가를 받으면 자기가 공급한 재화나 용역의 시가입니다.","금지금을 내국신용장·구매확인서로 공급하는 것은 영세율이 아니고, 국내에서 국내사업장 없는 비거주자에게 재화를 직접 공급하고 원화로 받는 것도 영세율이 아니다":"금지금을 내국신용장이나 구매확인서로 공급하는 것과 비거주자에게 국내에서 직접 공급해 원화로 받는 것은 영세율이 아닙니다.","금품 제공, 부분조사 후 나머지 조사 등 법정 사유가 있어야 한다":"같은 세목과 과세기간을 다시 조사하는 재조사는 금품 제공이나 부분조사 후 나머지 조사 같은 법정 사유가 있을 때만 가능합니다.","기부금영수증 사실과 다른 발급과 신용카드 매출전표 사실과 다른 발급은 그 금액의 5%":"기부금영수증이나 신용카드 매출전표를 사실과 다르게 발급하면 그 금액의 5%를 가산세로 냅니다.","기준금액을 넘는 Gross-up 대상 배당에 현행 11%를 더하고 같은 금액을 배당세액공제하되 종합과세 세액과 분리과세 가정 세액의 차액이 한도이다":"기준금액을 넘는 Gross-up 대상 배당에 11%를 더해 소득에 넣고 같은 금액을 배당세액공제하되 두 세액의 차액이 한도입니다.","기준금액 이상이 된 해의 다음 해 7월 1일부터 일반과세로 바뀌고 결정·경정으로 기준을 넘으면 그 과세기간까지는 간이과세자로 본다":"간이과세자가 기준금액을 넘으면 다음 해 7월 1일부터 일반과세로 바뀌고 결정으로 넘은 경우는 그 과세기간까지 간이과세자입니다.","기초공제와 그 밖의 인적공제 합계 대신 5억원을 일괄공제로 받을 수 있고 신고를 하지 않으면 5억원을 공제한다":"기초공제와 인적공제를 합치는 방법 대신 5억원을 정액으로 공제하는 일괄공제를 받을 수 있고 신고가 없어도 5억원을 공제합니다.","기초생활수급자는 친족이 아니어도 생계를 같이하면 대상이고, 재혼한 직계존속의 법률상 배우자도 포함되나 사실혼 배우자는 빠진다":"기초생활수급자는 친족이 아니어도 생계를 같이하면 부양가족이 되고 법률상 배우자는 포함하나 사실혼 배우자는 대상이 아닙니다.","기타사외유출로 처분하고 10년간 이월해 당기 지출분보다 먼저 공제한다":"한도를 넘은 기부금은 기타사외유출로 처분하고 10년간 이월하되 이월분을 당기 지출분보다 먼저 공제합니다.","기타소득금액이 연 300만원 이하이면 분리과세를 선택할 수 있다":"기타소득금액이 연 300만원 이하라면 합산 대신 분리과세를 고를 수 있어 신고 부담이 줄어듭니다.","기타소득 원천징수세율은 20%이고 연금외수령분과 소기업·소상공인 공제부금 해지일시금은 15%이다":"기타소득의 일반 원천징수세율은 20%이고 연금 외 수령분 등 일부는 15%의 낮은 세율을 적용합니다.","기한 만료일 10일 전까지 신청했는데 10일 이내에 통지가 없으면 승인한 것으로 본다":"연장 신청을 제때 했는데 과세관청이 기한 안에 아무 통지를 하지 않으면 신청이 받아들여진 것으로 의제합니다.","기한부판매는 기한이 지나 판매가 확정되는 때, 무인판매기는 현금을 꺼내는 때, 위탁판매수출은 공급가액이 확정되는 때가 공급시기이다":"기한부판매와 무인판매기와 위탁판매수출은 각각 판매가 확정되는 때와 현금을 꺼내는 때와 공급가액이 확정되는 때가 공급시기입니다.","납부고지·독촉·교부청구·압류는 중단 사유이나 압류금지재산을 압류해 즉시 해제한 경우는 중단되지 않는다":"납부고지와 독촉과 교부청구와 압류가 시효를 중단시키지만 압류금지재산을 압류했다가 곧 해제하면 중단되지 않습니다.","납부세액이 1천만원을 넘으면 2천만원 이하는 1천만원 초과분, 2천만원 초과는 50% 이하를 1개월(중소기업 2개월) 안에 분납한다":"납부세액이 크면 일부를 분납할 수 있는데 구간에 따라 분납 금액이 다르고 분납 기간은 중소기업이 더 깁니다.","납부세액이 2천만원을 넘으면 담보를 제공하고 연부연납할 수 있고 기간은 일반 상속재산 10년, 일반 증여재산 5년이다":"납부세액이 2천만원을 넘으면 담보를 내고 연부연납할 수 있으며 상속재산은 10년 증여재산은 5년까지 나눠 낼 수 있습니다.","납부할 세액이 1천만원을 넘으면 납부기한이 지난 후 2개월 이내에 일부를 나누어 낼 수 있다":"세액이 1천만원을 넘으면 납부기한이 지난 뒤 두 달 안에 일부를 뒤로 미뤄 나누어 낼 수 있다는 규정입니다.","납세조합 소재지가 납세지이다":"납세조합이 징수하는 사업소득의 납세지는 거주자의 주소지가 아니라 납세조합 소재지입니다.","내국법인이 100% 출자한 해외현지법인 파견 직원은 거주자로 본다":"내국법인이 전액 출자한 해외현지법인에 파견된 직원은 해외에 있어도 거주자로 취급합니다.","내국법인이 다른 내국법인 주식의 90% 이상을 보유하면 연결지배이고 연결모법인 관할 지방국세청장의 승인을 받아 연결납세방식을 적용할 수 있다":"내국법인이 다른 내국법인 주식의 90% 이상을 가지면 연결지배이며 관할 지방국세청장의 승인으로 연결납세방식을 쓸 수 있습니다.","내국신용장으로 영세율을 적용받아 산 재화를 면세사업에 직접 써도 공급이다":"내국신용장으로 영세율을 적용받고 산 재화를 면세사업에 직접 쓰면 그 재화를 공급한 것으로 봅니다.","농민이 농지 개량에서 나온 토사석을 일시적으로 파는 것은 납세의무가 없으나 사업자가 아닌 자의 재화 수입은 납세의무가 있다":"농민이 농지 개량 중 나온 토사석을 일시적으로 판매하는 행위는 납세의무가 없지만 비사업자의 재화 수입은 납세의무가 있습니다.","높은 이자율의 차입금부터 초과분에 넣고 건설자금이자는 대상에서 빼며 이 규정은 법인세법의 지급이자 손금불산입보다 먼저 적용한다":"과다차입 규정에서 이자율이 높은 차입금이 초과분에 먼저 들어가고 건설자금이자는 빠지며 법인세법 지급이자 규정보다 앞서 적용됩니다.","누가 부담하든 세금계산서를 주고받을 수 없다":"간주임대료에 대한 부가가치세는 임대인과 임차인 중 누가 부담하든 세금계산서를 주고받지 않습니다.","누적 발생원가를 총공사예정원가로 나누어 구한다":"작업진행률은 지금까지 쌓인 누적 발생원가를 총공사예정원가로 나눈 비율로 구합니다.","다른 소득에서 빼지 않고 이후 부동산임대업 소득에서만 공제하나, 주거용 건물 임대업 결손금은 다른 소득에서도 공제한다":"부동산임대업 결손금은 다른 소득에서 빼지 못하고 이후 임대업 소득에서만 공제하며 주거용 건물 임대업 결손금은 다른 소득에서도 공제합니다.","다른 소득으로 구분하고, 서화를 반복적으로 판매하면 사업소득이다":"다른 소득 유형과 겹치면 그쪽 소득으로 구분하고 서화를 반복해서 판매하면 기타소득이 아니라 사업소득입니다.","다른 주주에게 주면 지분율이 늘어난 부분은 재원과 관계없이 의제배당이다":"자기주식에 배정할 무상주를 다른 주주에게 주면 지분율이 늘어난 부분은 재원과 관계없이 의제배당입니다.","다음 사업연도 개시일부터 10년 이내에 이월공제한다":"외국납부세액이 공제한도를 넘으면 다음 사업연도 개시일부터 10년 이내에 이월해서 공제합니다.","담보할 국세의 120% 이상을 제공하고, 금전·납세보증보험증권·은행 납세보증서는 110% 이상이다":"납세담보는 담보할 국세의 120% 이상이어야 하나 금전과 납세보증보험증권과 은행 납세보증서는 110% 이상이면 됩니다.","당기 세법상 대손금을 직전 사업연도 말 채권가액으로 나눈 비율이다":"대손실적률은 당기에 세법상 인정된 대손금을 직전 사업연도 말 채권가액으로 나눈 비율입니다.","당초 신고한 세액을 증액하여 확정하는 효력이 있다":"수정신고는 이미 신고한 세액이 너무 적었을 때 더 늘려서 확정하는 효력을 가집니다.","대가를 원화로 받는지와 관계없이 영세율이고 국외 건설공사 재도급도 같다":"국외에서 제공하는 용역은 대가를 원화로 받는지와 관계없이 영세율이며 국외 건설공사의 재도급도 같습니다.","대가 없는 위약금·체선료·협회비와 사업장 안 사용인 무상 음식":"대가 없이 받는 위약금과 체선료와 협회비와 사업장 안에서 사용인에게 무상으로 주는 음식은 과세대상이 아닙니다.","대가의 각 부분을 받기로 한 때이고 역무 완료일 이후 부분을 완료일로 당기는 규정은 없다":"장기할부조건부 용역의 공급시기는 대가의 각 부분을 받기로 한 때이고 역무 완료일 이후 부분을 완료일로 당기는 규정은 없습니다.","대금을 청산하기로 약정한 날은 기준이 아니다":"자산 양도의 귀속시기를 정할 때 대금을 청산하기로 약정만 한 날은 기준일이 되지 못합니다.","대손세액공제를 받지 않은 것은 손금이고, 대손세액공제를 받은 부분은 손금이 아니다":"회수할 수 없는 매출세액 미수금은 대손세액공제를 받지 않았다면 손금이고 공제를 받은 부분은 손금이 아닙니다.","대표이사 개인 경조사 비용처럼 업무와 무관한 지출은 기업업무추진비가 아니라 상여 등으로 손금불산입한다":"대표이사 개인의 경조사 비용 같은 업무와 무관한 지출은 기업업무추진비가 아니라 상여 등으로 처분하고 손금에 넣지 않습니다.","대표자 상여(천재지변 장부 멸실은 기타사외유출)이며 기부금 한도초과액도 기타사외유출이다":"추계 과세표준과 당기순이익의 차액은 대표자 상여로 처분하고 천재지변 멸실은 기타사외유출이며 기부금 한도초과액도 같습니다.","대표자 상여로 처분하고, 그 소득세를 법인이 대납해 손비로 처리한 금액은 기타사외유출이다":"귀속이 불분명한 사외유출은 대표자 상여로 처분하고 그 소득세를 법인이 대신 내 손비로 처리한 금액은 기타사외유출입니다.","대한민국 선박이 공해에서 잡은 수산물의 외국 반출은 영세율이다":"대한민국 선박이 공해에서 잡은 수산물을 외국으로 반출하는 것은 영세율을 적용합니다.","독립된 지위에서 제공한 근로의 대가는 근로소득이 아니다":"고용 관계 없이 독립된 지위에서 일하고 받은 대가는 근로소득이 아니라 사업소득 등으로 봅니다.","독촉하는 날부터 20일 이내의 범위에서 기한을 정해 발급한다":"독촉장은 납부기한을 정해 발급하며 그 기한은 독촉하는 날로부터 한정된 범위 안에서 정합니다.","동종자산과 교환한 유형자산도 취득 당시의 시가가 취득가액이다":"같은 종류의 자산과 교환해 받은 유형자산도 취득한 당시의 시가가 취득가액이 됩니다.","둘 이상의 과세기간에 걸쳐 제공하고 대가를 선불이나 후불로 받으면 예정신고기간 또는 과세기간의 종료일이 공급시기이다":"여러 과세기간에 걸쳐 용역을 제공하고 대가를 미리나 나중에 받으면 예정신고기간이나 과세기간 종료일을 공급시기로 삼습니다.","등기우편이 원칙이지만 중간예납세액 등 고지금액 100만원 미만은 일반우편으로 보낼 수 있다(2026.2. 시행령 개정 전 50만원)":"납부고지서는 등기우편이 원칙이나 중간예납세액처럼 고지금액이 100만원 미만이면 일반우편으로 보낼 수 있습니다.","리스료에서 보험료·자동차세·수선유지비를 뺀 금액을 감가상각비 상당액으로 본다":"운용리스 차량은 리스료에서 보험료와 자동차세와 수선유지비를 뺀 금액을 감가상각비에 해당하는 금액으로 봅니다.","매월 말일 중 어느 하루라도 해외금융계좌 잔액 합계가 5억원을 넘는 거주자·내국법인은 다음 해 6월 1일부터 30일까지 신고하고 명의자와 실질적 소유자가 다르면 둘 다 보유한 것으로 보며 국가·지방자치단체·공공기관은 면제된다":"해외금융계좌 잔액이 월말 하루라도 5억원을 넘으면 다음 해 6월 1일부터 30일까지 신고하고 국가와 공공기관은 면제됩니다.","매입세액을 공제받은 재화를 면세사업에 직접 쓰거나 개인적으로 쓰는 것, 고객 추첨 경품 같은 사업상 증여, 폐업 때 남은 재화":"매입세액을 공제받은 재화를 면세사업이나 개인적 용도에 쓰는 것과 사업상 증여와 폐업 때 남은 재화는 재화의 공급으로 봅니다.","매출에누리·매출할인, 환입된 재화, 도달 전 파손·멸실된 재화, 연체이자, 공급과 직접 관련 없는 국고보조금":"매출에누리와 매출할인과 환입된 재화와 도달 전 파손된 재화와 연체이자와 공급과 무관한 국고보조금은 공급가액에 넣지 않습니다.","면세농산물등을 원재료로 과세 재화·용역을 공급하면 매입가액에 공제율을 곱해 매입한 때 공제하므로 재고분도 포함하고 운반비는 빼며 수입분은 관세의 과세가격으로 한다":"면세농산물을 원재료로 쓰면 매입가액에 공제율을 곱해 매입한 때 공제하며 재고분도 포함하고 운반비는 빼고 수입분은 과세가격을 씁니다.","면세를 포기하고 영세율을 적용받는 공급과 간이과세자에는 적용하지 않는다":"면세를 포기하고 영세율을 적용받는 공급과 간이과세자의 공급에는 의제매입세액공제를 적용하지 않습니다.","목적물을 인도하지 않고 차액만 금전으로 정산하는 파생상품 손익은 대금결제일이 속하는 사업연도에 귀속한다":"기초자산을 주고받지 않고 차액만 현금으로 정산하는 파생상품 손익은 대금결제일이 속하는 사업연도에 귀속합니다.","무상이나 부당하게 낮은 대가로 공급하면 시가를 공급가액으로 한다":"특수관계인에게 사업용 부동산 임대용역을 무상이나 부당하게 낮은 대가로 공급하면 시가를 공급가액으로 합니다.","무상 할당받은 온실가스 배출권은 0원이다":"무상으로 할당받은 온실가스 배출권은 대가를 낸 것이 없으므로 취득가액이 0원입니다.","무신고 법인에 대한 결정은 신고기한부터 1년 이내에 끝내야 하고, 경정은 장부·증명서류에 의한 실지조사가 원칙이다":"신고하지 않은 법인의 결정은 신고기한부터 1년 안에 끝내야 하고 경정은 장부와 증명서류를 바탕으로 한 실지조사가 원칙입니다.","미납세액에 1일 10만분의 22를 곱하고 지정납부기한까지 내지 않으면 3%를 더한다":"납부지연가산세는 미납세액에 하루 10만분의 22를 곱하고 지정납부기한까지 안 내면 3%가 더해집니다.","미등기자산과 국외자산에는 장기보유특별공제가 없다":"미등기 자산과 국외 자산은 오래 보유했더라도 장기보유특별공제를 받을 수 없습니다.","미술창작품, 금융회사의 금고대행용역, 차도선형여객선 운송, 국산 비식용 원생산물(관상용 새 등)은 면세하나 외국산 비식용 수산물 수입은 과세한다":"미술창작품과 금고대행용역과 차도선형여객선 운송과 국산 비식용 원생산물은 면세이지만 외국산 비식용 수산물 수입은 과세합니다.","바꾸려면 과세기간 개시 20일 전까지 본점·주사무소 관할 세무서장에게 신청한다":"사업자 단위 과세로 바꾸려면 과세기간 개시 20일 전까지 본점이나 주사무소 관할 세무서장에게 신청해야 합니다.","반환하지 않는 골프장 입회금과 면세재화 운반용역":"돌려주지 않는 골프장 입회금과 면세재화를 운반하는 용역은 부가가치세 과세대상입니다.","받기로 한 각 부분이 과세표준이다":"완성도기준지급조건부는 대가를 받기로 한 각 부분이 그 시점의 과세표준이 됩니다.","받기로 한 날을 기준으로 하고 둘 이상의 과세기간에 걸친 선불·후불 임대료는 월수에 따라 안분한다":"월세는 받기로 한 날을 기준으로 하고 둘 이상의 과세기간에 걸쳐 선불이나 후불로 받은 임대료는 월수에 따라 나눕니다.","받은 금액에 110분의 100을 곱한다":"부가가치세가 포함되었는지 불분명하면 받은 금액에 110분의 100을 곱한 금액을 공급가액으로 봅니다.","받은 자산은 피합병법인·분할법인의 장부가액이 취득가액이다":"적격합병이나 적격분할로 받은 자산은 피합병법인이나 분할법인이 장부에 올린 가액이 그대로 취득가액입니다.","받은 재화가 아니라 내가 준 재화의 시가로 하고 사업상 증여·폐업 잔존재화도 시가로 한다":"교환할 때 공급가액은 받은 재화가 아니라 내가 준 재화의 시가이며 사업상 증여와 폐업 잔존재화도 시가로 정합니다.","발급명세는 발급일 다음 날까지 국세청장에게 전송하고 의무가 없는 사업자도 전자발급·전송할 수 있다":"전자세금계산서는 발급한 다음 날까지 국세청장에게 전송하며 의무가 없는 사업자도 자발적으로 전자 발급하고 전송할 수 있습니다.","발급일부터 7일이 넘어 대가를 받고 법정 요건도 갖추지 못하면 발급일이 공급시기가 되지 않는다":"세금계산서를 먼저 발급하고 7일이 넘어 대가를 받았는데 법정 요건도 갖추지 못했다면 발급일을 공급시기로 보지 않습니다.","발생 후 15년 이내에 공제하고, 추계신고·추계결정 때는 공제하지 않는다(천재지변 등으로 장부가 없어진 경우는 공제)":"이월결손금은 발생 후 15년 안에 공제하고 추계로 신고하거나 결정할 때는 공제하지 않으며 천재지변으로 장부가 없어진 경우만 예외입니다.","발행법인이 부도·파산 등 법정 사유에 해당할 때 감액할 수 있고 발행법인별 평가액이 1천원 이하이면 1천원으로 한다":"주식 평가손실은 발행법인이 부도나 파산 같은 법정 사유일 때만 인정되고 법인별로 천원은 남기고 감액합니다.","배당 가능 유보소득에 보유비율을 곱한 금액을 사업연도 종료일 다음 날부터 60일이 되는 날이 속하는 내국인의 과세연도의 익금 또는 배당소득에 넣고 나중에 실제 배당하면 이월익금으로 본다":"특정외국법인의 유보소득 중 보유비율 몫을 배당받은 것으로 보아 60일이 되는 날이 속한 연도에 과세하고 나중에 배당하면 이월익금입니다.","배우자가 단독으로 상속받으면 일괄공제를 받을 수 없다":"배우자가 단독으로 상속받는 경우에는 일괄공제를 적용할 수 없습니다.","배우자가 상속받은 금액이 없거나 5억원 미만이면 5억원을 공제한다":"배우자가 상속받은 재산이 없거나 5억원보다 적더라도 최소 5억원은 배우자 상속공제로 공제해 줍니다.","배우자가 실제 상속받은 금액을 법정상속분 등으로 계산한 한도와 30억원 중 작은 금액까지 공제한다":"배우자 상속공제는 실제 상속받은 금액과 법정상속분 등으로 계산한 한도 중 작은 금액이되 30억원을 넘지 않습니다.","배우자·직계존비속에게 증여받은 자산을 10년 이내 양도하면 취득가액과 취득시기를 증여자 기준으로 하고 낸 증여세는 필요경비로 뺀다":"가까운 가족에게 증여받은 자산을 10년 안에 팔면 증여자의 취득가액과 취득시기를 적용하고 증여세는 필요경비로 인정합니다.","벌금·과료·과태료, 외국 법률에 따라 낸 벌금, 국민건강보험 연체금, 산재보험료 가산금":"벌금과 과료와 과태료와 국민건강보험 연체금 같은 제재성 지출은 손금에 넣지 않습니다.","법률상 이혼했어도 생계를 같이하는 등 사실상 이혼으로 보기 어려운 사람은 1세대의 배우자에 포함한다":"법적으로 이혼했더라도 실제로 생계를 같이하는 등 사실상 이혼이 아니라면 그 사람도 1세대의 배우자에 포함됩니다.","법인 6/106, 개인 8/108(과세표준 2억원 이하는 2026.12.31.까지 9/109)이고 과세유흥장소는 2/102이다":"의제매입세액 공제율은 업종과 사업자 유형에 따라 다르며 음식점은 법인 6/106 개인 8/108이고 과세유흥장소는 2/102입니다.","법인과 직전 연도 사업장별 공급가액 8천만원 이상인 개인사업자는 다음 해 제2기(7월 1일)부터 전자세금계산서를 발급하고 세무서장은 1개월 전까지 통지한다":"공급가액이 8천만원 이상인 개인사업자와 법인은 정해진 때부터 전자세금계산서를 의무로 발급하고 세무서장이 1개월 전에 알립니다.","법인세가 과세된 내국법인 배당과 의제배당":"Gross-up 대상은 법인 단계에서 이미 법인세가 과세된 내국법인의 배당과 의제배당입니다.","법인세 결정·경정으로 처분된 상여·배당·기타소득은 소득금액변동통지서를 받은 날에 지급한 것으로 보고 원천징수한다":"법인세 결정이나 경정으로 상여와 배당과 기타소득으로 처분된 금액은 소득금액변동통지서를 받은 날에 지급한 것으로 보고 원천징수합니다.","법인 업무전용자동차보험에 가입하지 않았거나 법인 전용 번호판을 달지 않으면 업무사용금액은 0원이다":"전용 보험이나 전용 번호판이 없으면 업무용으로 쓴 사실을 인정하지 않아 업무사용금액을 영으로 계산합니다.","법인으로 보는 단체의 분배금, 외국법인 배당, 주식 대차에서 받는 배당 상당액, 출자공동사업자의 손익분배액, 파생결합사채 이익, 요건을 갖춘 조각투자상품 이익은 배당소득이다":"법인으로 보는 단체의 분배금과 외국법인 배당과 출자공동사업자의 손익분배액과 파생결합사채 이익 등은 배당소득입니다.","법인의 사업과 관련해 발생하거나 지출된 비용으로서 일반적으로 인정되는 통상적인 것이거나 수익과 직접 관련된 것이다":"손비는 사업과 관련해 생기거나 지출한 비용으로 통상적이라고 인정되거나 수익과 직접 관련된 것이라야 합니다.","법인의 이동통신 전기통신사업은 본점소재지가 사업장이다":"법인의 이동통신 전기통신사업은 본점이 있는 곳을 사업장으로 봅니다.","법정신고기한 후 1개월 이내 수정신고는 과소신고가산세의 90%, 1개월 이내 기한후신고는 무신고가산세의 50%를 감면하고, 정당한 사유가 있으면 부과하지 않는다":"기한 후에 늦게 신고한 경우도 시기가 빠를수록 가산세를 크게 덜어 주며 정당한 사유가 있으면 가산세 자체를 매기지 않습니다.","법정신고기한 후 2년 이내 수정신고나 6개월 이내 기한 후 신고를 하면 형을 감경할 수 있다":"법정신고기한 후 2년 안에 수정신고하거나 6개월 안에 기한후신고를 하면 법원이 형을 줄여 줄 수 있습니다.","법정 신고납부기한의 다음 날, 기한이 연장되면 연장된 기한의 다음 날부터 행사할 수 있다":"신고로 확정되는 세목의 소멸시효는 법정 신고납부기한의 다음 날부터 진행하고 기한이 늘면 연장된 기한 다음 날부터입니다.","변경된 날부터 15일 이내에 변경 후 관할 세무서장에게 신고한다":"납세지가 바뀌면 변경된 날부터 15일 안에 변경 후 관할 세무서장에게 신고해야 합니다.","변경 방법을 적용할 사업연도 종료일 이전 3개월이 되는 날까지 신고한다":"재고자산 평가방법을 바꾸려면 변경한 방법을 적용할 사업연도 종료일 3개월 전까지 변경신고를 해야 합니다.","변상책임이 없는 타인 소유 자산은 상실비율 계산에서 빼고, 보험금을 받아도 상실비율은 줄지 않는다":"상실비율을 계산할 때 변상할 책임이 없는 남의 자산은 빠지고 보험금을 받더라도 상실비율이 낮아지지는 않습니다.","보장성보험료는 12%(장애인전용 15%)로 각 100만원 한도이고 건강보험료는 소득공제 대상이다":"보장성보험료는 세액공제하며 일반 12%와 장애인전용 15% 모두 각 100만원이 한도이고 건강보험료는 소득공제입니다.","보증금 1천만원 초과 임차인은 임대인 동의 없이 미납국세를 열람할 수 있다":"임차보증금이 1천만원을 넘는 임차인은 임대인의 동의 없이도 임대인의 미납국세를 열람할 수 있습니다.","보증금에서 금융수익을 빼지 않는다":"추계로 소득을 결정할 때는 보증금으로 번 금융수익을 따로 빼지 않고 계산합니다.","보험기간이 담보가 필요한 기간에 30일을 더한 기간 이상이어야 한다":"보험이 만료되어 담보 공백이 생기지 않도록 필요한 기간보다 한 달 더 긴 보험기간이 필요합니다.","본인·배우자·부양가족 1명당 연 150만원이고 배우자·부양가족은 소득금액 100만원 이하(근로소득만 있으면 총급여 500만원 이하)여야 한다":"기본공제는 본인과 배우자와 부양가족 1명당 연 150만원이며 소득금액이 100만원 이하이고 근로소득만 있으면 총급여 500만원 이하여야 합니다.","부가가치세는 세관장에게 관세와 함께 신고·납부하고 납부유예도 세관장이 한다":"수입 재화에 대한 부가가치세는 세관장에게 관세와 함께 신고하고 납부하며 납부유예도 세관장이 합니다.","부당행위계산 부인이 아니라 정상가격 과세조정을 적용한다":"국제거래에서 자산을 시가보다 비싸게나 싸게 매매했다면 부당행위계산 부인이 아니라 정상가격 과세조정을 적용합니다.","부동산 등과 주식 등 소득별로 연 250만원이며 미등기자산은 받지 못한다":"기본공제는 소득별로 연 250만원을 한 번씩 공제하며 등기하지 않은 자산에는 적용되지 않습니다.","부동산·신탁수익권은 양도일이 속하는 달의 말일부터 2개월, 주식은 반기 말일부터 2개월, 부담부증여는 3개월 이내이고 국외전출자는 출국일이 속하는 달의 말일부터 3개월 이내에 신고한다":"양도소득세 예정신고는 부동산은 양도일이 속하는 달의 말일부터 2개월 이내이고 주식은 반기 말일부터 2개월이며 부담부증여는 3개월입니다.","부동산임대업에서 생긴 결손금은 소급공제할 수 없으며, 과세표준확정신고기한까지 신청한다":"부동산임대업에서 생긴 결손금은 소급공제할 수 없고 소급공제 신청은 과세표준확정신고기한까지 해야 합니다.","부동산임대업 주업 등 성실신고확인 대상 소규모 법인은 200억원 이하도 20%이다":"부동산임대업이 주업인 성실신고확인 대상 소규모 법인은 구간이 낮아도 상위 구간인 20% 세율을 적용받습니다.","부동산임대업 주업 등 요건을 갖춘 법인은 800만원 대신 400만원, 1,500만원 대신 500만원이다":"부동산임대업이 주업인 법인처럼 요건을 갖추면 한도가 800만원에서 400만원으로 1,500만원에서 500만원으로 낮아집니다.","부채(충당금 제외)가 사업용 자산을 넘는 초과인출금에 대한 지급이자는 필요경비에 넣지 않는다":"부채가 사업용 자산을 넘는 초과인출금에 대한 지급이자는 사업과 관련이 없다고 보아 필요경비에 넣지 않습니다.","분납·징수유예·사해행위 취소소송 진행·6개월 이상 국외 체류 기간에는 시효가 정지된다":"분납이나 징수유예 중이거나 사해행위 취소소송이 진행되거나 국외에 6개월 이상 체류하는 동안 시효가 멈춥니다.","분리과세 이자·배당·연금·기타소득만 있는 거주자와 공적연금소득만 있는 거주자는 신고하지 않을 수 있으나 분리과세 주택임대소득이 있으면 확정신고를 해야 한다":"분리과세 소득만 있거나 공적연금소득만 있는 거주자는 확정신고를 생략할 수 있으나 분리과세 주택임대소득이 있으면 신고해야 합니다.","분리과세 주택임대소득 외 종합소득금액이 2천만원 이하이면 200만원(등록임대주택 400만원)을 추가로 뺀다":"분리과세 주택임대소득 외 종합소득금액이 2천만원 이하이면 일정 금액을 추가로 빼 주며 등록임대주택이 더 큽니다.","분양권은 2년 이상이어도 60%, 미등기자산은 70%, 비사업용 토지는 기본세율에 10%포인트를 더한다":"분양권은 오래 보유해도 60%이고 미등기자산은 70%이며 비사업용 토지는 기본세율에 10%를 더 얹은 세율입니다.","분할등기일 현재 시가로 양수한 것으로 본다":"비적격분할에서는 분할신설법인 등이 분할등기일 현재의 시가로 자산을 양수한 것으로 봅니다.","분할신설법인 등은 분할등기일 이전에 성립한 국세에 연대납세의무를 진다":"분할 후 존속하는 경우 분할신설법인 등은 분할등기일 전에 성립한 국세에 대해 함께 납세의무를 집니다.","비거주자·외국법인 사업자는 그 나라가 우리 거주자에게 같은 면세를 할 때만 영세율을 받으며 간이과세자도 영세율을 적용받는다":"비거주자와 외국법인은 상호주의에 따라 그 나라도 우리 거주자에게 면세할 때만 영세율을 받고 간이과세자도 적용 대상입니다.","비교가능 제3자 가격방법(특수관계 없는 독립 사업자 간 가격), 재판매가격방법(재판매가에서 통상이윤을 뺀 가격), 원가가산방법, 거래순이익률방법, 이익분할방법 가운데 가장 합리적인 방법을 고르며 순서는 없고 무형자산 거래는 비교가능 제3자 가격방법과 이익분할방법을 우선한다":"정상가격 산출방법 중 가장 합리적인 것을 순서 없이 고르며 무형자산 거래는 비교가능 제3자 가격방법과 이익분할방법을 우선합니다.","비실명 이자처럼 45% 분리과세되는 소득은 이 계산에서 뺀다":"비실명 이자처럼 45% 분리과세되는 소득은 금융소득 비교과세 계산에서 빼고 따로 과세합니다.","비영업대금이익, 직장공제회 초과반환금, 채권 보유기간 이자상당액, 환매조건부채권 매매차익, 물가연동국채 원금 증가분, 소비대차로 바뀐 외상매출금 지연이자는 이자소득이다":"비영업대금이익과 직장공제회 초과반환금과 채권 이자상당액과 환매조건부채권 매매차익 등은 이자소득으로 분류합니다.","비용 처리한 경우에도 감가상각비에 합산하고 상각 기초가액에도 더한다":"재해로 훼손된 자산의 복구비는 비용으로 처리했어도 감가상각비에 더하고 상각 기초가액에도 합산합니다.","사기나 그 밖의 부정한 행위로 조세를 포탈하거나 환급·공제를 받으면 2년 이하 징역 또는 포탈세액등의 2배 이하 벌금이다":"사기나 부정한 행위로 세금을 빼돌리거나 환급을 받으면 2년 이하 징역에 처하거나 포탈세액등의 2배 이하 벌금을 과합니다.","사업소득뿐이고 공동사업장의 이자·배당소득은 합산하지 않는다":"주된 공동사업자에게 합산하는 대상은 사업소득뿐이며 공동사업장에서 생긴 이자와 배당소득은 합산하지 않습니다.","사업연도 말 설정대상 채권 장부가액에 1%와 대손실적률 중 큰 비율을 곱한 금액이다":"대손충당금 한도는 설정대상 채권 장부가액에 일정 비율을 곱해 구하며 그 비율은 법정 비율과 대손실적률 중 큰 쪽입니다.","사업연도 종료일이 속하는 달의 말일부터 3개월 이내에 신고하고, 성실신고확인서를 내면 4개월, 외부감사 미종결로 신청하면 1개월 연장된다":"법인세 신고기한은 사업연도 종료일이 속한 달 말일부터 3개월이고 성실신고확인서나 외부감사 사유가 있으면 더 늘어납니다.","사업용 유형·무형자산 건설에 쓴 특정차입금 이자는 준공된 날까지 자본적 지출로 원본에 더한다(유보)":"사업용 자산을 짓는 데 쓴 특정차입금 이자는 준공일까지 자본적 지출로 보아 자산 원본에 더하고 유보로 처리합니다.","사업용 자산의 20% 이상을 재해로 잃으면 법인세액에 자산상실비율을 곱한 금액을 공제하되 상실 자산가액이 한도이다":"사업용 자산을 재해로 일정 비율 이상 잃으면 법인세액에 상실비율을 곱한 금액을 공제하되 상실한 자산가액을 넘지 못합니다.","사전에 서면 약정한 성과배분상여금이라도 손금에 넣지 않는다":"이익을 처분하면서 지급하는 상여금은 미리 서면으로 약정한 성과배분상여금이라도 손금으로 인정되지 않습니다.","산출세액×국외원천소득/과세표준이다":"외국납부세액공제의 한도는 산출세액에 국외원천소득이 과세표준에서 차지하는 비율을 곱한 금액입니다.","산출세액에서 감면·공제세액, 중간예납·수시부과·원천징수세액을 빼고 납부하며 수시부과를 받아도 신고의무는 남는다":"납부할 법인세는 산출세액에서 감면과 공제세액과 이미 낸 중간예납과 수시부과와 원천징수세액을 빼서 정하며 수시부과를 받아도 신고의무는 남습니다.","상각범위액만큼 반드시 손금에 넣어야 해서(의무상각), 덜 계상해도 상각범위액을 손금산입한 것으로 보고 미상각잔액을 줄인다":"법인세를 감면받는 법인은 상각범위액만큼을 의무적으로 손금에 넣는 것으로 보므로 덜 계상해도 상각범위액만큼 미상각잔액이 줄어듭니다.","상속개시 전 1년 이내에 재산 종류별로 2억원 이상, 2년 이내 5억원 이상을 처분하거나 인출했는데 용도가 객관적으로 명백하지 않으면 상속받은 것으로 추정해 과세가액에 넣는다":"상속 전 1년 이내 2억원 이상 또는 2년 이내 5억원 이상 처분한 재산의 용도가 불명확하면 상속받은 것으로 추정해 과세가액에 넣습니다.","상속세는 상속개시일이 속하는 달의 말일부터 6개월, 증여세는 증여받은 날이 속하는 달의 말일부터 3개월 이내에 신고하고 신고하면 산출세액의 3%를 공제한다":"상속세는 상속개시일이 속한 달 말일부터 6개월 증여세는 3개월 안에 신고해야 하며 기한 내 신고하면 산출세액의 3%를 공제합니다.","상속세 신고기한 다음 날부터 9개월이 되는 날까지 배우자 상속재산을 분할(등기 등 포함)해야 적용한다":"배우자 상속공제는 상속세 신고기한 다음 날부터 9개월이 되는 날까지 배우자 상속재산을 분할해야 적용합니다.","상속세·증여세는 신고와 관계없이 정부가 결정하는 때 확정된다":"상속세와 증여세는 신고했더라도 정부가 결정하는 때에 세액이 확정되는 부과과세 방식입니다.","상속인과 수유자는 상속재산 중 각자 받았거나 받을 재산의 비율에 따라 상속세를 내고 각자 받았거나 받을 재산을 한도로 연대납부의무를 진다":"상속인과 수유자는 각자 받은 재산의 비율로 세금을 내고 서로 받은 재산 한도 안에서 연대해 납부할 책임을 집니다.","상속재산가액에서 공과금, 장례비용, 채무를 빼고 상속개시 전 10년 이내 상속인에게 한 증여재산과 5년 이내 상속인 아닌 자에게 한 증여재산을 더한다":"상속세 과세가액은 상속재산가액에서 공과금과 장례비용과 채무를 빼고 10년 이내 상속인 증여와 5년 이내 상속인 아닌 자 증여를 더한 금액입니다.","상속주택과 상속 전부터 보유한 일반주택이 있으면 일반주택을 팔 때만 1주택으로 보고, 상속 후 산 일반주택에는 적용하지 않는다":"상속주택이 있어도 상속 전부터 가진 일반주택을 팔 때만 1주택으로 보고 상속 후 산 일반주택에는 이 특례를 적용하지 않습니다.","상업서류 송달용역과 외국항행사업자가 자기 승객 전용 호텔에 투숙시키는 것은 영세율이다":"상업서류를 송달하는 용역과 외국항행사업자가 자기 승객을 전용 호텔에 묵게 하는 용역은 영세율 대상입니다.","상장법인 대주주의 자본준비금 감액배당은 주식 장부가액까지만 배당소득에서 뺀다":"상장법인 대주주가 자본준비금 감액배당을 받으면 주식 장부가액까지만 배당소득에서 빼고 그 초과분은 배당소득으로 봅니다.","상장 여부와 관계없이 액면가액을 취득가액으로 본다":"소액주주가 취득가액을 입증하지 못하면 주식이 상장되었는지와 관계없이 액면가액을 취득가액으로 봅니다.","상품 등 외의 자산 양도는 대금청산일, 소유권이전등기일, 인도일, 사용수익일 중 빠른 날이 속하는 사업연도에 귀속한다":"상품이 아닌 자산을 팔 때는 대금 청산과 등기와 인도와 사용수익 중 가장 빠른 시점이 속한 사업연도에 귀속합니다.","선입선출법(매매용 부동산은 개별법)으로 평가한다":"기한 안에 평가방법을 신고하지 않으면 선입선출법으로 평가하고 매매용 부동산은 개별법으로 평가합니다.","설립일이 속하는 사업연도 신고기한까지 평가방법을 신고한다":"신설법인은 설립일이 속하는 사업연도의 법인세 신고기한까지 재고자산 평가방법을 신고해야 합니다.","성실신고확인 대상 개인사업자가 법인으로 전환하면 전환 후 3년간 성실신고확인서를 낸다":"성실신고확인 대상 개인사업자가 법인으로 전환했다면 전환한 뒤 3년 동안은 법인도 성실신고확인서를 제출해야 합니다.","성실신고확인대상사업자가 성실신고확인서를 내면 확정신고 기간은 다음 연도 5월 1일부터 6월 30일까지이다":"성실신고확인서를 내는 사업자는 일반 사업자보다 한 달 늦은 다음 연도 6월 30일까지 확정신고할 수 있습니다.","세금계산서 미발급·거짓 기재 발급, 통정한 미수취·거짓 수취, 매출처별 합계표 거짓 제출은 1년 이하 징역 또는 공급가액×세율의 2배 이하 벌금이다":"세금계산서를 안 주거나 거짓으로 적어 주는 등의 행위는 1년 이하 징역이나 공급가액에 세율을 곱한 금액의 2배 이하 벌금입니다.","세무공무원이 점유한 때 효력이 생긴다":"동산이나 유가증권 압류는 세무공무원이 직접 점유한 때 효력이 생깁니다.","세무사가 성실신고확인대상사업자이면 자기 사업소득금액에 대한 성실신고확인서를 본인이 작성·제출할 수 없다":"세무사가 성실신고확인대상사업자라도 자기 사업소득금액에 대한 확인서를 직접 쓰고 낼 수는 없습니다.","세무상 미상각잔액(장부가액+전기 상각부인누계액+즉시상각의제액)에 상각률을 곱해 구한다":"정률법의 상각범위액은 장부가액에 전기 상각부인누계액과 즉시상각의제액을 더한 세무상 미상각잔액에 상각률을 곱해 구합니다.","세무조사 통지 후 경정을 미리 알고 하는 세율 오류 정정은 할 수 없다":"세무조사 통지를 받고 경정을 미리 알면서 하는 세율 오류 정정은 수정세금계산서로 할 수 없습니다.","세액공제받은 납입액과 운용수익은 연금수령하면 연금소득, 연금외수령하면 기타소득(15% 원천징수)이다":"세액공제받은 납입액과 운용수익은 연금으로 받으면 연금소득이고 연금 외로 받으면 15% 원천징수하는 기타소득입니다.","세액공제분 연금수령액은 70세 미만 5%, 70세 이상 80세 미만 4%, 80세 이상 3%로 원천징수하고, 사망 때까지 받는 종신계약 연금은 3%이다":"세액공제를 받은 연금 수령액의 원천징수세율은 나이가 많을수록 낮아지며 종신계약 연금은 일정하게 3%입니다.","세액이 2천만원 이하면 1천만원을 넘는 금액, 2천만원을 넘으면 세액의 50% 이하를 분납한다":"분납할 수 있는 금액은 세액이 2천만원 이하이면 1천만원을 넘는 금액이고 2천만원을 넘으면 세액의 50% 이하입니다.","소득세가 면제되는 소득과 지급 전에 이미 종합소득에 합산되어 과세된 배당소득은 지급할 때 원천징수하지 않는다":"면세 소득과 지급 전에 이미 종합과세로 합산된 배당소득은 지급하는 때에는 따로 세금을 떼지 않아도 됩니다.","소득세·법인세·부가가치세·교통·에너지·환경세 등은 신고로 확정된다":"납세자가 신고하는 순간 세액이 확정되는 신고납세 방식 세목에는 소득세와 법인세와 부가가치세 등이 있습니다.","소득세와 대표자 본인의 급여":"사업소득 계산에서 소득세와 대표자 본인에게 주는 급여는 필요경비로 인정되지 않습니다.","소멸법인이 내지 않은 원천징수 소득세의 납세의무를 진다":"합병으로 새로 설립된 법인은 합병으로 없어진 법인이 내지 않은 원천징수 소득세의 납세의무를 이어받습니다.","소멸시효가 완성되거나 회생계획인가·면책결정으로 회수불능이 확정된 채권은 그 사유가 생긴 사업연도에 손금산입해야 하고 뒤 사업연도에 계상해도 인정되지 않는다":"시효 완성이나 면책결정으로 회수불능이 확정된 채권은 그 사유가 생긴 사업연도에 손금으로 넣어야 하고 뒤에 계상하면 인정되지 않습니다.","소멸시효가 진행되지 않고 교부청구는 할 수 있다":"징수유예 기간에는 소멸시효가 진행되지 않지만 다른 절차에 대해 교부청구는 할 수 있습니다.","소유권 이전 전에 법정기일이 도래한 국세에도 미치고, 이미 거두어들인 천연과실에는 미치지 않고 급료 등 계속적 채권은 압류 후 발생분에도 미친다":"부동산 압류의 효력은 소유권 이전 전 법정기일 국세에도 미치고 이미 거둔 천연과실에는 미치지 않으며 급료는 압류 후 발생분에도 미칩니다.","손금불산입하여 귀속자에 따라 상여 등으로 처분한다":"업무 외로 사용한 부분은 손금에 넣지 않고 사용한 사람이 누구인지에 따라 상여 등으로 처분합니다.","손금에 넣은 국고보조금을 기한 안에 사업용자산 취득·개량에 쓰지 않거나 쓰기 전에 폐업·해산하면 쓰지 않은 금액을 그 사유가 생긴 사업연도의 익금에 산입한다":"국고보조금을 손금에 넣고도 기한 안에 사업용자산에 쓰지 않거나 먼저 폐업하면 안 쓴 금액을 그 사유가 생긴 연도의 익금에 더합니다.","수익사업을 하면 자산·부채·손익을 다른 회계로 구분경리해야 한다":"비영리법인이 수익사업을 하면 고유목적사업과 섞이지 않도록 자산과 부채와 손익을 따로 구분경리해야 합니다.","수입금액 1%에 미가입 기간 비율을 곱한다":"현금영수증가맹점에 가입하지 않았다면 수입금액의 1%에 미가입 기간 비율을 곱한 금액이 가산세입니다.","수입금액 100억원 이하 0.3%, 100억원 초과 500억원 이하 0.2%, 500억원 초과 0.03%를 적용한다":"수입금액 한도율은 구간이 오를수록 낮아져 100억원 이하는 0.3% 500억원 이하는 0.2% 그 위는 0.03%입니다.","수입에 해당하는 것은 수입신고 수리일이다":"보세구역에서 국내로 공급한 재화 중 수입에 해당하는 것은 수입신고가 수리된 날이 공급시기입니다.","수탁자가 공급하거나 공급받은 것으로 본다":"위탁매매에서 위탁자를 알 수 없으면 거래 상대방에게는 수탁자가 직접 공급하거나 공급받은 것으로 봅니다.","순금융재산이 2천만원 이하면 전액, 넘으면 20%와 2천만원 중 큰 금액을 2억원 한도로 공제하고 최대주주 보유 주식과 신고하지 않은 타인 명의 금융재산은 빠진다":"순금융재산이 2천만원 이하면 전액 넘으면 20%와 2천만원 중 큰 금액을 2억원 한도로 공제하며 최대주주 보유 주식은 제외됩니다.","승계받아 공제한 감면·세액공제액도 법인세에 더해 납부하고 그 사업연도부터 감면을 적용하지 않는다":"사후관리 사유가 생기면 승계받아 공제한 감면과 세액공제액을 법인세에 더해 내고 그 사업연도부터 감면을 적용하지 않습니다.","승계사업 소득으로 계산한 기부금 한도 안에서 손금에 넣는다":"승계한 기부금한도초과액은 승계사업 소득으로 계산한 기부금 한도 안에서 손금에 넣을 수 있습니다.","승계사업에서 생긴 소득금액의 80%(중소기업 등 100%) 범위에서만 공제한다":"적격합병으로 승계한 피합병법인의 결손금은 승계사업에서 생긴 소득금액의 80% 범위에서만 공제하며 중소기업 등은 100%입니다.","승계사업을 폐지하거나 주주가 받은 주식을 처분하는 등의 사유가 생기면 그 사업연도에 자산조정계정 잔액과 공제한 승계결손금 등을 익금에 산입한다":"사후관리 기간에 사업을 접거나 주식을 팔면 자산조정계정 잔액과 공제받은 승계결손금 등을 한꺼번에 익금에 넣습니다.","승계재산 가액을 한도로 연대한다":"분할법인이 사라지는 경우 분할신설법인은 물려받은 재산의 가액까지를 한도로 연대납세의무를 집니다.","시가보다 싸게 임대하면 과세하나 대학이 산학협력단에 무상 임대하는 것은 공급이 아니다":"특수관계인에게 사업용 부동산을 시가보다 싸게 빌려주면 과세하나 대학이 산학협력단에 무상으로 임대하는 것은 공급이 아닙니다.","시설물을 철거하면 장부가액에서 1천원을 뺀 금액을 폐기일이 속하는 사업연도의 손금에 넣을 수 있다":"임차한 사업장의 원상회복으로 시설물을 철거하면 장부가액에서 천원을 남기고 폐기한 사업연도의 손금으로 처리할 수 있습니다.","식사를 제공받지 않는 근로자의 식사대 월 20만원, 6세 이하 자녀 보육수당 자녀 1명당 월 20만원, 자가운전보조금 월 20만원 이내는 비과세이다":"식사를 따로 받지 않는 근로자의 식사대와 6세 이하 자녀 보육수당과 자가운전보조금은 각각 월 20만원 이내이면 비과세입니다.","신고납부 세목은 신고·납부기한이 지난 때이고 부과 세목은 정부 결정 후 납부기한이 지난 때이나 포탈 목적으로 신고하지 않아 결정할 수 없으면 신고기한이 지난 때이다":"포탈죄는 신고납부 세목과 부과 세목의 기수 시기가 다르고 포탈 목적의 미신고로 결정이 불가능하면 신고기한이 지난 때입니다.","신고 때 손금산입하면 손비로 계상한 것으로 본다":"일시상각충당금이나 압축기장충당금은 장부에 계상하지 않고 세무조정계산서에만 넣어 손금산입해도 계상한 것으로 봅니다.","신고서에 적은 대로 1인에게 공제하고 서로 적었거나 알 수 없으면 배우자 공제를 우선한다":"여러 사람의 공제대상에 겹치면 신고서에 적힌 한 사람에게 공제하고 서로 적었거나 알 수 없으면 배우자 공제를 먼저 적용합니다.","신고일 또는 수정신고일에 지급한 것으로 본다":"법인이 법인세를 신고하면서 스스로 소득처분한 금액은 신고일이나 수정신고일에 지급한 것으로 봅니다.","신고일이 속하는 사업연도까지는 종전 기준을 적용하고 그다음 사업연도부터 신고한 방법을 쓴다":"변경신고 기한이 지난 뒤에 신고했다면 신고일이 속하는 사업연도까지는 종전 방법이고 다음 사업연도부터 새 방법을 씁니다.","신고조정으로 손금산입하고, 지분법이익은 익금불산입한다":"소멸시효가 완성된 매출채권은 신고조정으로 손금에 넣고 지분법이익은 익금에 넣지 않습니다.","신고한 방법 외의 방법으로 평가하거나 변경신고 없이 바꾸면 선입선출법 평가액과 당초 신고방법 평가액 중 큰 금액으로 평가한다":"신고한 방법과 다르게 평가하거나 변경신고 없이 바꾸면 선입선출법 평가액과 당초 신고방법 평가액 중 큰 금액을 적용합니다.","실제 공급받은 자가 아닌 다른 사람에게 발급하면 미발급죄가 되고 거래 없는 발급죄는 세금계산서마다 1죄이며 합계표를 내지 않은 것은 가산세 대상일 뿐 범죄가 아니다":"실제 공급받은 자가 아닌 사람에게 발급하면 미발급죄이고 거래 없는 발급죄는 계산서마다 1죄이며 합계표 미제출은 가산세만 따릅니다.","실제 공급자가 아닌 다른 가맹점 명의 매출전표는 신용카드 사용으로 보지 않는다":"실제 공급자가 아닌 다른 가맹점 이름으로 받은 매출전표는 적격증빙인 신용카드 사용으로 인정하지 않습니다.","실제 근무하는 배우자·가족의 급여는 필요경비이다":"실제로 일하는 배우자와 가족에게 준 급여는 정당한 대가이므로 사업소득의 필요경비로 인정됩니다.","실제로 받은 날이 수입시기이다":"금융보험업이 받는 이자와 할인료는 받을 권리가 생긴 날이 아니라 실제로 받은 날이 수입시기입니다.","실제부담세액이 실제발생소득에 법인세 최고세율의 70%를 곱한 금액 이하인 지역의 외국법인으로서 내국인과 특수관계가 있으면 특정외국법인이고 사업연도 말 현재 발행주식의 10% 이상을 직접·간접 보유한 내국인이 대상이다":"법인세 부담이 최고세율의 70% 이하인 지역의 특수관계 외국법인이 특정외국법인이며 그 주식을 10% 이상 가진 내국인이 대상입니다.","실제 수령연차 10년 이하는 연금외수령 세율의 70%, 10년 초과 20년 이하는 60%, 20년 초과는 50%를 적용한다":"이연퇴직소득을 연금으로 받을 때 실제 수령연차가 길수록 적용 세율 비율이 낮아져 70%에서 60% 그리고 50%가 됩니다.","실제 지급한 날 원천징수한다":"무기명주식의 배당은 지급시기를 의제하지 않고 실제로 지급한 날에 원천징수합니다.","실지귀속을 구분할 수 없는 공통매입세액은 공급가액 비율로 안분하고 예정신고 때 안분한 것은 확정신고 때 6개월 전체 비율로 정산한다":"어느 사업에 쓰였는지 가를 수 없는 공통매입세액은 공급가액 비율로 안분하고 예정신고분은 확정신고 때 전체 비율로 정산합니다.","쌍방 토지가액 차액이 큰 쪽 가액의 4분의 1 이하인 국가사업 농지 교환은 비과세이다":"국가사업을 위한 농지 교환은 쌍방 토지가액 차액이 큰 쪽 가액의 4분의 1 이하이면 양도소득세를 과세하지 않습니다.","쓰면 필요경비는 개산공제(토지·건물은 기준시가의 3%, 미등기 0.3%)만 인정한다":"환산취득가액이나 매매사례가액을 쓰면 필요경비는 개산공제만 인정하며 토지와 건물은 기준시가의 3%이고 미등기는 0.3%입니다.","알선·중개자도 같은 형이며 세무사·공인회계사·변호사가 알선하면 2분의 1을 가중한다":"알선하거나 중개한 사람도 같은 형을 받고 세무사와 공인회계사와 변호사가 알선하면 형의 2분의 1을 가중합니다.","양도대가 1억원 이하분 90%, 초과분 80%(10년 이상 보유하면 90%)이며 이 역시 실제 경비가 크면 그 금액을 쓴다":"서화와 골동품은 양도대가가 클수록 의제 비율이 90%에서 80%로 낮고 10년 넘으면 90%이며 실제 경비가 많으면 그 금액을 씁니다.","양도성 예금증서도 담보로 쓰는 유가증권이다":"담보로 제공할 수 있는 유가증권에는 양도성 예금증서도 포함됩니다.","양도일 이전에 확정된 그 사업의 국세에 대해 양수재산 가액 한도로 제2차 납세의무를 진다":"사업을 넘겨받은 사람은 양도일 전에 확정된 그 사업의 국세에 대해 양수한 재산의 가액 한도까지 제2차 납세의무를 집니다.","어음으로 지급하면 어음이 결제된 날에 지출한 것으로 본다":"기부금은 현금주의로 따지므로 어음으로 지급했다면 어음이 결제된 날에 지출한 것으로 봅니다.","업무를 총괄하는 장소만 사업장이고 다른 장소를 추가로 등록할 수 없으며 사업장도 등록도 없으면 결정·경정 당시 주소나 거소를 사업장으로 한다":"무인자동판매기 사업은 업무를 총괄하는 장소만 사업장이며 추가 등록이 안 되고 등록이 없으면 결정 당시 주소나 거소가 사업장입니다.","업무무관 대여금과 특수관계인 업무무관 가지급금 등":"대손충당금 설정대상 채권에서 빼는 것에는 업무와 관계없는 대여금과 특수관계인의 업무무관 가지급금 등이 있습니다.","업무무관 자산, 기업업무추진비 관련(거래처 증정품), 면세사업 투자, 토지 관련(건축물이 있는 토지를 사서 철거한 건물의 취득·철거비 포함) 매입세액은 불공제이다":"업무와 무관한 자산과 기업업무추진비 관련과 면세사업 투자와 토지 관련 매입세액은 공제하지 않습니다.","업무사용분 감가상각비(임차차량은 감가상각비 상당액)는 차량별 연 800만원을 넘는 금액을 손금불산입(보유 차량은 유보, 임차 차량은 기타사외유출)하고 이후 800만원에 미달하는 연도에 추인한다":"업무사용분 감가상각비가 차량별로 연 800만원을 넘으면 손금에 넣지 않고 이월해 이후 800만원에 못 미치는 해에 추인합니다.","연결사업연도와 일치해야 하고 1년을 넘지 못하며 납세지는 연결모법인의 납세지이다":"연결법인의 사업연도는 연결사업연도와 같아야 하고 1년을 넘을 수 없으며 납세지는 연결모법인의 납세지입니다.","연결지배하지 않는 법인에 적용하면 승인이 취소된다":"연결지배 관계가 없는 법인에 연결납세방식을 적용했다면 승인이 취소됩니다.","연금계좌 가입자가 사망하고 배우자가 연금외수령 없이 계좌를 승계하면 그 계좌의 소득은 상속인의 소득으로 본다":"연금계좌의 가입자가 숨졌을 때 배우자가 연금을 인출하지 않고 이어받으면 그 계좌의 소득은 상속인 몫으로 과세합니다.","연대납세의무자, 제2차 납세의무자, 보증인이 들어가고 원천징수의무자는 빠진다":"납세의무자에는 연대납세의무자와 제2차 납세의무자와 보증인이 포함되지만 원천징수의무자는 해당하지 않습니다.","영세율 대상인 면세재화는 면세를 포기할 수 있으나 신고한 날부터 3년간 면제받지 못하고 그 수출용 농산물에는 의제매입세액공제를 하지 않는다":"영세율 대상 면세재화는 면세를 포기할 수 있으나 3년간 다시 면세를 받지 못하고 수출용 농산물은 의제매입세액공제도 없습니다.","예금이자처럼 사업과 무관한 이자수익은 이자소득으로 따로 구분하며 사업소득에 넣지 않는다":"사업과 무관하게 생긴 예금이자 같은 수익은 이자소득으로 따로 나누어 과세하고 사업소득에는 넣지 않습니다.","예탁결제원에 송달된 때 효력이 생긴다":"예탁된 유가증권의 압류는 한국예탁결제원에 압류 통지서가 송달된 때 효력이 생깁니다.","완성도기준·중간지급조건부와 전력처럼 단위를 나눌 수 없는 재화의 계속 공급은 대가의 각 부분을 받기로 한 때이고 완성도기준·중간지급조건부에서 인도일 이후 받기로 한 부분은 인도일이다":"완성도기준과 중간지급조건부 같은 계속 공급은 대가의 각 부분을 받기로 한 때가 공급시기이고 인도일 이후 받기로 한 부분은 인도일입니다.","완성된 제품의 인도가액이 과세표준이다":"위탁가공무역 방식으로 수출하는 경우 과세표준은 완성된 제품을 인도할 때의 가액입니다.","외국법인 배당, 출자공동사업자 배당, 자기주식소각이익 2년 내 자본전입, 집합투자기구 이익":"외국법인 배당과 출자공동사업자 배당과 소각 후 2년 이내 자본전입한 자기주식소각이익과 집합투자기구 이익은 Gross-up 대상이 아닙니다.","외국인 관광객에게 알선용역을 제공하고 원화로 받으면 발급의무가 없다":"종합여행업자가 외국인 관광객에게 알선용역을 제공하고 원화로 받으면 세금계산서 발급의무가 없습니다.","외국인 직업운동가가 프로스포츠구단과 계약해 받는 소득은 계약기간과 관계없이 20%, 일용근로자 근로소득은 6%, 봉사료는 5%이다":"외국인 직업운동가의 소득은 계약기간과 관계없이 20% 일용근로자 근로소득은 6% 봉사료는 5%의 원천징수세율이 적용됩니다.","운행기록상 업무사용비율을 곱한 금액만 손금이다":"업무용승용차 관련비용 중 운행기록에 나타난 업무사용비율을 곱한 금액만 손금으로 인정합니다.","원천징수세액은 반기별 납부를 할 수 없다":"결정이나 경정으로 처분된 소득에 대한 원천징수세액은 반기별 납부 특례를 적용하지 못합니다.","원천징수세액은 징수일이 속하는 달의 다음 달 10일까지 낸다":"원천징수한 세액은 징수한 달의 다음 달 10일까지 납부합니다.","원천징수세액을 기타사외유출, 나머지를 대표자 상여로 처분한다":"채권자를 알 수 없는 사채이자는 원천징수세액 부분을 기타사외유출로 하고 나머지는 대표자 상여로 처분합니다.","원천징수한 국세도 대상이고, 성립만 하고 확정되지 않은 세액은 대상이 아니다":"납부기한 전 징수는 원천징수한 국세에도 적용되지만 성립만 하고 아직 확정되지 않은 세액에는 적용되지 않습니다.","원칙은 둘 중 선택이지만 현행법상 공시대상기업집단 소속 법인은 실적 기준으로만 계산한다":"중간예납은 원칙적으로 두 방법 중 고를 수 있으나 현행법상 공시대상기업집단 소속 법인은 실적 기준으로만 계산합니다.","월정액급여 260만원 이하이고 직전 총급여 3,700만원 이하인 생산직 근로자의 연장·야간·휴일근로수당은 연 240만원까지 비과세한다":"월정액급여와 직전 총급여가 일정 금액 이하인 생산직 근로자의 연장과 야간과 휴일 수당은 연 240만원까지 비과세입니다.","유형자산을 취득하며 함께 산 국공채의 매입가액과 현재가치의 차액을 기업회계기준에 따라 유형자산 취득가액으로 계상하면 그 금액은 취득가액에 포함한다":"유형자산을 사면서 함께 산 국공채의 매입가액과 현재가치의 차액을 회계기준대로 자산 취득가액에 넣었다면 취득가액에 포함합니다.","의결권 있는 주식 10%(해외자원개발 5%) 이상을 가진 외국자회사의 배당은 95%를 익금불산입하나 간접투자회사등은 제외한다":"의결권 있는 주식을 10% 이상 가진 외국자회사의 배당은 95%를 익금에 넣지 않으며 간접투자회사 등은 제외됩니다.","의무자가 종이로 발급하면 공급가액의 1%, 확정신고기한까지 늦게 전송하면 0.3% 가산세이다":"전자세금계산서 의무자가 종이로 내주면 공급가액의 1% 늦게 전송하면 0.3%만큼 가산세가 붙어 불이익이 있습니다.","의제배당이 아니나, 출자전환 때 시가를 넘어 발행된 금액은 의제배당이다":"주식발행초과금을 자본에 넣어 받은 무상주는 의제배당이 아니지만 출자전환 때 시가를 넘은 발행분은 의제배당입니다.","이월결손금 보전에 충당한 금액만 익금불산입한다":"자산수증이익과 채무면제이익은 이월결손금을 메우는 데 쓴 금액만 익금에 넣지 않습니다.","이익잉여금, 자기주식처분이익, 소각일부터 2년 안의 자기주식소각이익, 재평가세 1% 토지분 재평가적립금을 자본전입해 받은 무상주는 의제배당이다":"이익잉여금이나 자기주식처분이익 등을 자본에 넣어 받은 무상주는 실제 배당이 아니어도 배당으로 보는 의제배당입니다.","이익처분 상여로 보아 손금불산입한다":"합명회사와 합자회사의 노무출자사원이 받는 보수는 이익처분에 따른 상여로 보아 손금에 넣지 않습니다.","이자, Gross-up 대상이 아닌 배당, Gross-up 대상 배당 순으로 채운다":"금융소득 기준금액을 채울 때는 이자를 먼저 넣고 Gross-up 대상이 아닌 배당 그리고 마지막에 Gross-up 대상 배당을 넣습니다.","이자·배당소득 합계가 2천만원을 넘으면 전액 종합과세하고, 2천만원 이하이면 14%(비영업대금이익·출자공동사업자 배당 25%) 원천징수로 끝난다":"이자와 배당소득 합계가 2천만원을 넘으면 전액 종합과세하고 2천만원 이하이면 14% 원천징수로 끝나며 비영업대금이익은 25%입니다.","이자소득이나 10년 이상 유지하고 납입보험료 1억원 이하 등 요건을 갖추면 과세하지 않는다":"저축성보험 차익은 이자소득이지만 오래 유지하고 납입보험료가 일정 한도 이하인 등 요건을 갖추면 과세하지 않습니다.","이중장부, 거짓 증빙 작성·수취, 장부 파기, 재산 은닉, 고의적 장부 미작성처럼 부과·징수를 불가능하게 하거나 현저히 곤란하게 하는 적극적 행위이고 착오로 장부를 안 쓰거나 단순히 신고하지 않은 것은 해당하지 않는다":"부정한 행위는 이중장부와 거짓 증빙과 재산 은닉처럼 부과와 징수를 현저히 곤란하게 하는 적극적 행위이며 단순 미신고는 해당하지 않습니다.","익금이지만 같은 사업연도(또는 기한) 안에 사업용자산 취득에 쓰면 해당 금액을 손금에 넣어 과세를 이연한다":"국고보조금과 공사부담금과 보험차익은 익금이지만 기한 안에 사업용자산 취득에 쓰면 해당 금액을 손금에 넣어 과세를 미룹니다.","인지세, 원천징수하는 소득세·법인세, 납세조합 징수 소득세, 중간예납 법인세(정부가 조사·결정하는 경우 제외)":"세금이 성립하는 때에 별도 절차 없이 곧바로 세액이 확정되는 세목들이며 정부가 결정하는 중간예납은 제외됩니다.","일반 5년, 무신고 7년, 부정행위 10년(역외거래 부정행위 15년)":"부과제척기간은 일반 5년이고 신고를 안 하면 7년이며 부정행위면 10년이고 역외거래 부정행위는 15년입니다.","일반 수입금액 다음 구간부터 적용한 금액의 10%만 인정한다":"특수관계인과의 거래 수입금액은 일반 수입금액 다음 구간부터 적용해 계산한 금액의 10%만 한도로 인정합니다.","일반 이자·배당은 14%, 비영업대금의 이익과 출자공동사업자의 배당은 25%, 원천징수대상 사업소득은 3%이다":"원천징수세율은 일반 이자와 배당이 14%이고 비영업대금 이익과 출자공동사업자 배당이 25%이며 원천징수대상 사업소득은 3%입니다.","일시불 선불로 받고 여러 과세기간 계속 쓰게 하는 경우도 같다":"상표권 사용대가를 일시불로 선불로 받고 여러 과세기간 동안 계속 쓰게 하는 경우에도 같은 방식으로 공급시기를 정합니다.","일용근로소득 지급명세서는 지급일이 속하는 달의 다음 달 말일까지 낸다":"일용근로소득 지급명세서는 지급한 달의 다음 달 말일까지 제출하는 것이 기한입니다.","임대료와 간주임대료 합계를 건물은 기준시가 비율로, 부수토지는 면적 비율로 나누어 상가분만 과세한다":"상가와 주택이 함께 있는 건물은 임대료와 간주임대료 합계를 건물은 기준시가 비율로 부수토지는 면적 비율로 나눠 상가분만 과세합니다.","임대료 지급기간이 1년을 넘거나 결산 때 경과기간분 임대료를 수익으로 계상하면 경과기간분을 그 사업연도의 익금으로 한다":"임대료를 오래 선지급받거나 결산에서 이미 지난 기간 몫을 수익으로 올렸다면 그 지난 기간분을 해당 연도 익금으로 잡습니다.","임대보증금·전세금을 받으면 보증금에 정기예금이자율과 과세대상기간 일수/365(윤년 366)를 곱한 간주임대료를 과세표준에 더한다":"임대보증금과 전세금에는 정기예금이자율에 과세대상기간 일수를 연 일수로 나눈 비율을 곱한 간주임대료를 과세표준에 더합니다.","임원, 일용근로자, 정년퇴직 예정자, 계약기간 1년 미만인 자":"근로자 승계 비율을 계산할 때 임원과 일용근로자와 정년퇴직 예정자와 계약기간 1년 미만인 사람은 제외합니다.","임원이 아닌 종업원이 받는 사택 이익은 비과세이다":"임원이 아닌 종업원이 사택을 제공받아 얻는 이익은 근로소득에서 비과세됩니다.","임차인이 부담한 사실이 확인되는 전세금·임차보증금에 대한 부가가치세는 임차인의 손금이다":"전세금과 임차보증금에 대한 간주임대료 부가가치세를 임차인이 부담한 사실이 확인되면 임차인의 손금입니다.","잉여금 범위에서 자기자본에서 빼고, 청산기간 중 환급받은 법인세는 자기자본에 더한다":"청산소득을 계산할 때 이월결손금은 잉여금 범위에서 자기자본에서 빼고 청산기간에 환급받은 법인세는 자기자본에 더합니다.","잉여금처분 배당의 수입시기는 잉여금처분 결의일이고, 인정배당은 결산확정일이다":"잉여금처분에 따른 배당은 잉여금처분 결의일이 수입시기이고 법인세법상 인정배당은 결산확정일이 수입시기입니다.","자가운전보조금, 사택제공이익, 광산 입갱·발파수당 같은 실비변상성 급여":"월정액급여를 계산할 때 자가운전보조금과 사택제공이익과 광산 입갱수당 같은 실비변상 성격의 급여는 빼고 셉니다.","자녀가 아닌 직계비속이 상속·증여받으면 산출세액의 30%(미성년자이고 20억원 초과분이면 40%)를 더하나 중간 세대가 먼저 사망한 대습상속이면 할증하지 않는다":"자녀가 아닌 직계비속이 받으면 산출세액의 30%가 할증되고 미성년자이며 20억원 초과분이면 40%이나 대습상속은 할증하지 않습니다.","자동차운전학원·수의사도 감가상각자산을 공급하며 사업자가 요구하면 세금계산서를 발급한다":"자동차운전학원과 수의사도 감가상각자산을 팔 때는 상대 사업자가 요구하면 세금계산서를 줘야 합니다.","자본 납입 등을 빼고 순자산을 늘리는 거래의 수익이다":"익금은 자본 납입 같은 자본 거래를 빼고 법인의 순자산을 늘리는 거래에서 생기는 수익입니다.","자산을 합병등기일 현재 시가로 양수한 것으로 보고, 지급한 양도가액과 순자산 시가의 차액은 합병매수차익·합병매수차손으로 처리한다":"비적격합병에서 합병법인은 합병등기일 시가로 자산을 샀다고 보고 지급한 가액과 순자산 시가의 차액을 합병매수차익이나 차손으로 처리합니다.","자산을 합병법인에 양도한 것으로 보아 양도가액에서 순자산 장부가액을 뺀 양도손익을 최종 사업연도 익금·손금에 넣는다":"비적격합병에서 피합병법인은 자산을 합병법인에 판 것으로 보아 양도가액에서 순자산 장부가액을 뺀 손익을 최종 사업연도에 넣습니다.","자산의 가치를 늘리는 자본적 지출을 수선비 등 비용으로 처리하면 감가상각비로 계상한 것으로 보아 시부인한다":"자산 가치를 늘리는 자본적 지출을 수선비로 처리하면 감가상각비로 계상한 것으로 간주하여 상각범위액과 견줘 시부인합니다.","자회사 법인세 중 배당분(간접외국납부세액)을 더해 공제하고 국외원천소득에도 가산한다":"외국자회사 배당은 자회사가 낸 법인세 중 배당에 해당하는 간접외국납부세액을 함께 공제하고 국외원천소득에도 더합니다.","작성 연월일 같은 필요적 기재사항이 빠진 세금계산서는 공제하지 않으나 공급자 주소·품목·단가·수량이 빠진 것은 공제한다":"작성 연월일처럼 법이 필수로 정한 사항이 없으면 불공제이고 공급자 주소와 품목과 단가와 수량이 없는 것은 공제됩니다.","잔여재산가액에서 해산등기일 현재 자본금과 잉여금 합계(자기자본)를 뺀 금액이다":"청산소득은 해산하면서 남은 잔여재산가액에서 해산등기일 현재의 자본금과 잉여금 합계인 자기자본을 뺀 금액입니다.","잔여재산가액확정일이 속하는 달의 말일부터 3개월 이내에 한다":"청산소득의 확정신고는 잔여재산가액확정일이 속하는 달의 말일부터 3개월 안에 해야 합니다.","장부 계상과 관계없이 신고조정으로 산입한다":"익금 항목은 회사가 장부에 올렸는지와 관계없이 세무조정 단계에서 신고조정으로 산입합니다.","재난·도난, 질병, 사업의 중대한 위기, 장부 작성을 대행하는 세무사의 장부 도난 등":"납부기한을 늘려 주는 사유에는 재난과 도난과 질병과 사업의 중대한 위기와 장부를 맡은 세무사의 장부 도난 등이 있습니다.","재난·도난 손실이 아니면 담보를 요구할 수 있다":"재난이나 도난으로 입은 손실이 사유가 아닌 경우에는 과세관청이 납세담보를 요구할 수 있습니다.","재산 상황 변동으로 유예를 취소했으면 다시 유예할 수 있다":"재산 상황이 바뀌어 징수유예를 취소했더라도 사정이 달라지면 다시 유예해 줄 수 있습니다.","재산은 시가로 평가하며 매매·감정·수용·경매가 있는 평가기간은 상속은 상속개시일 전후 6개월, 증여는 증여일 전 6개월부터 후 3개월까지이다":"재산은 시가로 평가하며 매매와 감정과 수용과 경매 가액을 쓰는 기간이 상속은 전후 6개월 증여는 전 6개월에서 후 3개월입니다.","재직 일수로 나누어 각자에게 상여 처분한다":"사업연도 중 대표자가 바뀌고 귀속이 불분명하면 각 대표자의 재직 일수로 나누어 각자에게 상여로 처분합니다.","재화·용역의 공급 없이 세금계산서·계산서를 발급하거나 받은 행위와 합계표 거짓 제출은 3년 이하 징역 또는 3배 이하 벌금으로 징역과 벌금을 병과할 수 있다":"재화나 용역의 공급 없이 세금계산서를 발급하거나 받으면 3년 이하 징역 또는 3배 이하 벌금이며 징역과 벌금을 함께 과할 수 있습니다.","전기 유보로 세무상 취득가액이 장부가액보다 큰 자산을 처분하면 처분 비율만큼 유보를 손금산입(△유보)으로 추인한다":"전기 유보 때문에 세무상 취득가액이 더 큰 자산을 처분하면 처분 비율만큼 유보를 손금산입으로 추인해 세무조정을 정리합니다.","전용 40㎡ 이하이고 기준시가 2억원 이하인 소형주택은 2026년까지 주택 수에서 뺀다":"면적과 기준시가가 작은 소형주택은 2026년까지 간주임대료를 따지는 주택 수 계산에서 빠집니다.","전자세금계산서 의무발급자에게서 종이 세금계산서를 받았어도 확정신고기한까지 받고 거래사실이 확인되면 공제한다":"전자세금계산서 의무자에게 종이로 받았어도 확정신고기한까지 받고 거래가 확인되면 매입세액을 공제합니다.","전환 전 공급분이 환입되면 처음 세금계산서 작성일을 작성일로 적는다":"간이과세자에서 일반과세자로 바뀐 뒤 전환 전 공급분이 환입되면 처음 세금계산서의 작성일을 작성일로 적습니다.","정당한 사유 없이 차액이 시가의 30% 이상일 때 차액에서 3억원을 뺀다":"특수관계가 없는 경우에는 정당한 사유 없이 차액이 시가의 30% 이상일 때 차액에서 3억원을 뺀 금액을 증여재산으로 봅니다.","정산시점부터 근무연수를 새로 기산하는 경우에만 현실적 퇴직으로 본다":"퇴직급여를 중간정산하더라도 그 시점부터 근무연수를 새로 세는 경우에만 실제로 퇴직한 것으로 인정합니다.","정상가격 산출방법 사전승인은 적용하려는 최초 과세연도 개시일의 전날까지 국세청장에게 신청하고 일방적 사전승인을 받아 과실이 없다고 판정되면 과소신고가산세를 부과하지 않는다":"정상가격 산출방법의 사전승인은 적용할 최초 과세연도 개시일 전날까지 국세청장에게 신청하며 과실 없는 일방적 승인이면 과소신고가산세를 면제합니다.","정액법·내용연수 5년으로 강제 상각한다":"업무용승용차의 감가상각비는 정액법에 내용연수 5년으로 정해진 방식대로 반드시 상각해야 합니다.","제3자 명의나 계산으로도 압류재산을 매수할 수 없다":"체납자와 세무공무원은 제삼자의 이름을 빌리거나 제삼자의 계산으로도 압류재산을 매수하지 못합니다.","제3자 명의 재산 취득 등으로 부정 포탈한 재산가액이 50억원을 넘으면 상속·증여가 있음을 안 날부터 1년 이내에 부과할 수 있다":"부정 포탈한 재산가액이 50억원을 넘으면 과세관청이 상속이나 증여를 안 날부터 1년 안에는 부과할 수 있습니다.","제3채무자에게 통지하고 그 통지서가 제3채무자에게 송달된 때 효력이 생기며 체납자에게는 압류 후 통지한다":"채권 압류는 제3채무자에게 통지서가 송달된 때 효력이 생기고 체납자에게는 압류 후에 알립니다.","제품·상품, 반제품·재공품, 원재료, 저장품으로 구분하고 종류별·영업장별로 다른 방법을 쓸 수 있다":"재고자산은 제품과 반제품과 원재료와 저장품으로 나누며 종류별과 영업장별로 평가방법을 다르게 쓸 수 있습니다.","종교관련종사자가 현실적 퇴직으로 받는 소득, 과학기술인공제회의 과학기술발전장려금, 국민연금 일시금 중 2002.1.1. 이후 납입분 기초 부분은 퇴직소득이다":"종교관련종사자의 퇴직으로 받는 돈과 과학기술발전장려금과 국민연금 일시금의 2002.1.1. 이후 납입분 부분이 퇴직소득입니다.","종업원 선물·작업복과 국가에 무상 공급한 재화의 매입세액은 공제한다":"종업원에게 준 선물과 작업복 그리고 국가에 무상으로 공급한 재화에 든 매입세액은 공제 대상입니다.","종전 개시일부터 변경 후 개시일 전날까지가 1개월 미만이면 변경된 사업연도에 포함한다":"사업연도를 바꿀 때 사이 기간이 1개월 미만이면 별도 사업연도로 세지 않고 변경된 사업연도에 포함합니다.","종전주택 취득 후 1년 이상 지나 신규주택을 사고 3년 이내(조정대상지역 안에서 갈아타면 2년)에 종전주택을 팔면 비과세한다":"종전주택을 산 지 1년이 지나 신규주택을 사고 3년 안에 종전주택을 팔면 비과세하며 조정대상지역 안에서 갈아타면 2년 안입니다.","종합소득금액이 있으면 과세표준이 없거나 결손금이 있어도 확정신고를 해야 한다":"종합소득금액이 있으면 과세표준이 없거나 결손금이 생겼더라도 확정신고를 생략하지 못하고 신고해야 합니다.","종합소득에 합산하지 않는 분리과세 이자소득이고, 납입금 초과이익은 연분연승 방식으로 세액을 계산한다":"직장공제회 초과반환금은 종합소득에 합치지 않고 분리과세하며 납입금 초과이익은 연분연승 방식으로 세액을 계산합니다.","종합소득·퇴직소득·양도소득 모두에 적용되고 확정신고 세액뿐 아니라 중간예납세액과 예정신고세액도 대상이다":"분납은 종합소득과 퇴직소득과 양도소득 모두에 쓸 수 있고 확정신고 세액은 물론 중간예납과 예정신고 세액에도 적용됩니다.","주거용 건물 임대업 결손금은 다른 소득과 통산하지만 그 밖의 부동산임대업 결손금은 이월만 되고 소급공제도 안 된다":"주거용 건물 임대업 결손금은 다른 소득에서 뺄 수 있지만 다른 부동산임대업 결손금은 이월만 가능하고 소급공제는 안 됩니다.","주된 사업이면 현지에 고정시설을 두고 스스로 사업을 관리해도 배당간주를 적용하고 유보소득은 법인마다 따로 계산하며 임의적립금 처분액은 유보소득에서 빼지 않는다":"선박과 항공기와 장비 임대가 주된 사업이면 현지 고정시설과 관리가 있어도 배당간주를 적용하고 유보소득은 법인마다 따로 계산합니다.","주민등록상 거주가 확인된 채권자가 변제받은 뒤 소재불명이 되면 채권자 불분명 사채로 보지 않는다":"거주가 확인되던 채권자가 이자를 받은 뒤에 소재불명이 되었다면 채권자 불분명 사채이자로 보지 않습니다.","주식·출자지분 양도 수입과 유형·무형자산 처분 수입":"비영리법인의 수익사업 소득에는 주식과 출자지분을 팔아 번 수입과 유형자산과 무형자산을 처분한 수입이 들어갑니다.","주요자재를 전혀 부담하지 않는 단순가공과 자재를 부담하는 건설업은 용역의 공급이다":"주요 자재를 전혀 대지 않는 단순가공과 자재를 대는 건설업은 새 재화를 만드는 것이 아니므로 용역의 공급으로 봅니다.","주요자재 일부를 부담해 새 재화를 만들어 인도하면 재화의 공급이다":"주요자재 일부를 부담해 새 재화를 만들어 넘기는 경우에는 용역이 아니라 재화의 공급으로 봅니다.","주택·별장과 조합원입주권·분양권 양도는 20%, 비사업용 토지는 10%(미등기 40%)를 각 사업연도 법인세에 추가한다":"주택 같은 부동산 양도와 비사업용 토지 양도는 사업연도 소득세 외에 법인세를 추가로 과세하며 미등기는 더 무겁습니다.","주택임대 총수입금액이 2천만원 이하이면 14% 분리과세를 선택할 수 있다":"주택임대 총수입이 2천만원 이하이면 종합과세 대신 14%로 분리과세하는 방법을 고를 수 있습니다.","주택입주 지체상금은 받은 금액의 80%":"주택입주 지체상금은 받은 금액의 80%를 필요경비로 의제해 기타소득금액을 계산합니다.","중간예납기간 6개월 소득을 연으로 환산해 계산한다":"중간예납의 실적 기준은 중간예납기간 6개월 동안의 소득을 한 해로 환산해서 세액을 계산하는 방법입니다.","중간예납기준액의 30%에 미달하면 11월에 추계액을 신고·납부할 수 있다":"중간예납기간의 소득으로 추계한 세액이 중간예납기준액의 30%에 못 미치면 11월에 추계액을 신고하고 낼 수 있습니다.","중간지급조건부가 아닌 거래에서는 인도 전에는 공급시기가 오지 않는다":"계약금만 받고 세금계산서도 발급하지 않았다면 중간지급조건부가 아닌 거래는 인도하기 전에는 공급시기가 오지 않습니다.","중계무역·외국인도수출과 보세구역 물품의 외국 반출은 국내 사업장에서 계약과 대가 수령이 이루어진 경우에만 영세율이다":"중계무역과 외국인도수출과 보세구역 물품의 외국 반출은 국내 사업장에서 계약하고 대가를 받은 경우에만 영세율을 적용합니다.","중소기업 7%, 일반기업 100억원 이하 10%, 100억원 초과 1천억원 이하 12%, 1천억원 초과 17%이다":"최저한세율은 중소기업 7%이고 일반기업은 100억원 이하 10%와 1천억원 이하 12%와 1천억원 초과 17%입니다.","중소기업만 직전 사업연도 법인세를 환급받을 수 있고, 결손금 사업연도와 직전 사업연도를 모두 기한 안에 신고해야 한다":"결손금 소급공제는 중소기업만 직전 사업연도 법인세를 환급받는 제도이며 결손금 사업연도와 직전 사업연도를 모두 기한 안에 신고해야 합니다.","중소기업을 경영하는 거주자만 사업소득 결손금으로 직전 과세기간 소득세를 환급받을 수 있고 비거주자는 대상이 아니다":"사업소득 결손금을 이용한 소급공제는 중소기업을 경영하는 거주자에게만 허용되고 비거주자는 받을 수 없습니다.","중소기업의 계약기간 1년 미만 건설, 기업회계기준에 따라 인도일 기준으로 계상한 경우, 작업진행률을 계산할 수 없는 경우는 인도일이 속하는 사업연도에 넣는다":"중소기업의 1년 미만 건설이나 인도기준으로 계상했거나 진행률을 계산할 수 없으면 인도일이 속하는 사업연도에 넣습니다.","중소기업이 아닌 회사 종업원이 주택구입자금을 무상으로 빌려 얻은 이익은 근로소득이다":"중소기업이 아닌 회사의 종업원이 주택자금을 공짜로 빌려 얻은 이자 상당 이익은 근로의 대가이므로 근로소득입니다.","증권시장에서 보통거래방식으로 한 유가증권 매매는 매매계약을 체결한 날이 귀속시기이다":"증권시장에서 보통거래방식으로 유가증권을 매매하면 대금을 주고받은 날이 아니라 계약을 체결한 날이 귀속시기입니다.","증여한 자산을 수증자가 10년 이내 양도해 세부담이 줄면 증여자가 양도한 것으로 보아 연대납세의무를 지우고 증여세는 환급한다":"특수관계인에게 증여한 자산을 수증자가 10년 안에 팔아 세부담이 줄면 증여자가 판 것으로 보고 연대납세의무를 지우며 증여세는 돌려줍니다.","지급이자에 업무무관자산 등 적수/차입금 적수를 곱해 기타사외유출로 처분한다":"업무무관자산과 가지급금 관련 이자는 지급이자에 업무무관자산 등 적수를 차입금 적수로 나눈 비율을 곱해 손금불산입하고 기타사외유출로 처분합니다.","지급한 사업연도의 기부금이다":"기부금을 미지급금으로 계상했더라도 실제로 돈을 지급한 사업연도의 기부금으로 인정합니다.","지분을 거짓으로 정하면 주된 공동사업자에게 합산하며, 이때 특수관계인은 손익분배비율에 해당하는 자기 소득금액을 한도로 연대납세의무를 진다":"특수관계인과의 공동사업에서 지분을 거짓으로 정하면 주된 공동사업자에게 합산하고 특수관계인은 자기 소득금액을 한도로 연대납세의무를 집니다.","지출한 사업연도의 기부금이다":"가지급금으로 이연해 계상한 기부금도 장부 처리와 상관없이 실제로 지출한 사업연도의 기부금입니다.","직계존비속에게 주택을 무상으로 빌려주고 실제 거주하면 부인 대상이 아니다":"직계존비속에게 주택을 공짜로 빌려줬더라도 그들이 실제로 살고 있다면 조세 회피로 보아 부인하지 않습니다.","직계존속 60세 이상, 직계비속 20세 이하, 형제자매 20세 이하 또는 60세 이상이 요건이고 장애인은 나이 제한이 없다":"부양가족은 직계존속 60세 이상과 직계비속과 형제자매 20세 이하 또는 60세 이상이어야 하며 장애인은 나이 제한이 없습니다.","직계존속에게서 혼인일 전후 2년 이내나 자녀 출생일부터 2년 이내에 받으면 합쳐서 1억원을 따로 공제한다":"혼인이나 출산에 직계존속이 준 재산은 혼인일 전후 2년과 출생일부터 2년 이내이면 합쳐서 1억원을 추가로 공제합니다.","직무발명보상금은 연 700만원, 공무원의 공무 관련 상금은 연 240만원까지 비과세이다":"직무발명보상금과 공무원의 공무 관련 상금은 각각 연 700만원과 연 240만원까지만 비과세합니다.","직전 사업연도 산출세액(가산세 포함, 토지등 양도소득 법인세 등 제외)에서 감면·원천징수·수시부과세액을 뺀 금액에 6/직전 월수를 곱한다":"중간예납의 직전 산출세액 기준은 직전 산출세액에서 감면과 원천징수와 수시부과세액을 뺀 금액에 6을 직전 월수로 나눈 비율을 곱합니다.","직전 산출세액에서 결손금을 뺀 과세표준에 직전 세율을 적용한 세액을 뺀 금액이며 직전 사업연도 법인세액(산출세액-공제·감면세액)이 한도이다":"환급액은 직전 산출세액에서 결손금을 뺀 과세표준에 직전 세율을 적용한 세액을 뺀 금액이고 직전 사업연도 법인세액이 한도입니다.","직전 연도 공급대가 1억4백만원 미만인 개인사업자만 간이과세자이고 부동산임대업·과세유흥장소는 4천800만원 미만이 기준이며 일반과세 사업장을 가진 사람이 새로 연 사업장도 일반과세이다":"직전 연도 공급대가가 1억4백만원 미만인 개인사업자가 간이과세자이며 부동산임대업과 과세유흥장소는 4천800만원 미만이 기준입니다.","직전 연도 공급대가 4천800만원 미만 간이과세자와 수의사 진료용역·도로운영용역 공급자는 영수증을 발급한다":"4천800만원 미만 간이과세자와 수의사와 도로운영 용역 공급자는 세금계산서 대신 간단한 영수증을 발급합니다.","직전 연도 상시고용인원 20명 이하인 원천징수의무자(금융·보험업 제외)는 승인을 받아 반기 마지막 달의 다음 달 10일까지 낼 수 있다":"직전 연도 상시고용인원이 20명 이하인 원천징수의무자는 승인을 받아 반기마다 한 번에 모아 납부할 수 있습니다.","질권·저당권·가등기담보권은 매각으로 소멸한다":"압류재산이 공매로 팔리면 질권과 저당권과 가등기담보권은 매각과 함께 사라집니다.","질권·저당권·양도담보 목적의 제공, 상속세 물납, 출자지분의 양도·상속·증여와 현금 반환":"질권과 저당권과 양도담보 목적의 제공과 상속세 물납과 출자지분의 양도는 재화의 공급으로 보지 않습니다.","징수할 때는 납부고지서를 발급하지 않을 수 있다":"지정납부기한이 지난 뒤에 생기는 납부지연가산세는 징수할 때 따로 납부고지서를 발급하지 않아도 됩니다.","징수할 때도 납부고지서를 발급한다":"고지서 발급은 징수 단계에서도 필요해서 보충적 납세의무자와 보증인과 물적납세의무자에게도 각각 보냅니다.","차액이 시가의 30%와 3억원 중 적은 금액 이상이면 차액에서 그 금액을 뺀 것을 증여재산으로 한다":"특수관계인 사이의 저가양수와 고가양도는 차액이 시가의 30%와 3억원 중 적은 금액 이상이면 차액에서 그 금액을 뺀 것을 증여재산으로 봅니다.","착오로 이중 발급하면 처음 내용대로 음의 표시를 해 발급한다":"세금계산서를 착오로 이중 발급했다면 처음 내용과 같게 음의 표시를 해서 발급해 바로잡습니다.","참가압류는 등기재산의 경우 참가압류 등기가 완료된 때로 소급해 효력이 생긴다":"선행압류가 해제되면 참가압류는 등기재산의 경우 참가압류 등기가 끝난 때로 거슬러 올라가 압류의 효력을 갖습니다.","채권자 불분명 사채이자, 지급받는 자가 불분명한 채권·증권 이자, 건설자금이자, 업무무관자산·가지급금 관련 이자의 순서로 적용한다":"지급이자 손금불산입은 채권자 불분명 사채이자부터 시작해 불분명한 채권증권 이자와 건설자금이자와 업무무관 관련 이자 순으로 적용합니다.","채권자 불분명 사채이자를 먼저 빼고 남은 차입금 중 이자율이 높은 것부터 초과인출금 적수에 맞추어 불산입액을 계산한다":"먼저 채권자 불분명 사채이자를 빼고 남은 차입금 중 이자율이 높은 것부터 초과인출금에 대응시켜 불산입 이자를 구합니다.","채무면제이익으로 보전하는 데 쓸 수 없다":"적격합병으로 승계한 결손금은 채무면제이익 같은 익금을 메우는 용도로 쓰지 못합니다.","처분을 안 날부터 90일 이내에 하고, 처분으로 권리나 이익을 침해당하지 않은 자의 청구는 각하한다":"불복 청구는 처분을 안 날부터 90일 안에 해야 하고 권리나 이익을 침해받지 않은 사람의 청구는 본안을 보지 않고 각하됩니다.","처분일 현재 3년 이상 계속 고유목적사업에 직접 쓴 자산의 처분 수입":"처분일 현재까지 3년 이상 계속 고유목적사업에 직접 쓴 자산의 처분 수입은 수익사업 소득에서 빠집니다.","천재지변·화재·수용·폐광으로 파손·멸실된 경우에 시가로 감액한다":"유형자산은 천재지변이나 화재나 수용이나 폐광으로 파손이나 멸실된 경우에만 시가로 평가손실을 인정합니다.","체납 발생일부터 1년이 지난 국세가 2억원 이상일 때 할 수 있고, 불복이 계속 중이면 공개하지 않는다":"체납 발생일부터 1년이 지난 국세가 2억원 이상이면 명단을 공개할 수 있고 불복이 진행 중이면 공개하지 않습니다.","체납액은 강제징수비, 가산세를 제외한 국세, 가산세의 순으로 징수한다":"체납액은 강제징수비를 먼저 거두고 그다음 가산세를 뺀 국세를 거두며 마지막에 가산세를 거둡니다.","체납액을 한도로 압류하나 우선 질권 등으로 징수가 불확실하면 전액을 압류할 수 있다":"채권 압류는 체납액 한도 안에서 하는 것이 원칙이나 선순위 질권 등으로 징수가 불확실하면 채권 전액을 압류할 수 있습니다.","체약상대국이 국외특수관계인과의 거래가격을 조정하고 상호합의절차가 종결되면 거주자는 수정신고나 경정청구를 할 수 있고 과세당국은 그 합의에 따라 조정할 수 있다":"상대국이 거래가격을 조정하고 상호합의절차가 끝나면 거주자는 수정신고나 경정청구를 할 수 있고 과세당국도 합의대로 조정할 수 있습니다.","총급여 3%를 넘는 금액의 15%(일반 대상 700만원 한도, 본인·65세 이상·6세 이하·장애인은 한도 없음)이고 미숙아 20%, 난임시술 30%이며 안경은 1인당 50만원까지이다":"의료비는 총급여 3%를 넘는 지출분에 공제율을 적용하며 대상자별로 한도와 공제율이 다르고 안경은 1인당 50만원까지입니다.","총급여액의 5%와 추계액 기준 누적한도(2016년 이후 0%에 퇴직금전환금 가산) 중 작은 금액까지 손금이다":"퇴직급여충당금은 총급여액의 5%와 추계액 기준 누적한도 중 작은 금액까지 손금으로 인정합니다.","총수입금액에서 필요경비를 뺀 금액이다":"사업소득금액은 사업으로 번 총수입금액에서 그 수입을 얻는 데 든 필요경비를 뺀 금액입니다.","총평균법으로 평가한다(2026.2. 시행령 개정 전 선입선출법)":"가상자산은 재고자산처럼 평가하며 현행 규정에서는 총평균법을 적용합니다.","최초 적용 연결사업연도와 그다음 4년 동안은 포기할 수 없다":"연결납세방식은 처음 적용한 연결사업연도와 그다음 4년 동안은 포기할 수 없습니다.","추계액에서 세법상 퇴직급여충당금 잔액을 뺀 금액과 운용자산 잔액 중 적은 금액에서 이미 손금산입한 누적액을 뺀 범위에서 신고조정으로 손금산입한다":"퇴직연금 부담금은 추계액 기준액과 운용자산 잔액 중 적은 금액에서 이미 손금에 넣은 누적액을 뺀 범위만큼 신고조정합니다.","출자공동사업자의 배당소득, 사업소득, 기타소득, 양도소득에만 적용하고 이자·근로·연금·퇴직소득에는 없다":"소득세의 부당행위계산 부인은 출자공동사업자의 배당과 사업과 기타와 양도소득에만 적용되고 이자와 근로와 연금과 퇴직소득에는 없습니다.","출자비율 50% 이상 100%, 20% 이상 50% 미만 80%, 20% 미만 30%를 익금불산입한다":"내국법인 배당은 출자비율이 50% 이상이면 100%, 20% 이상이면 80%, 20% 미만이면 30%를 익금에 넣지 않습니다.","출자비율에 따라 나누어 부담하는 것이 원칙이다":"공동사업에서 생기는 비용은 각 공동사업자의 출자비율에 따라 나누어 부담하는 것이 원칙입니다.","취득일부터 3년이 지나 소급 감정한 가액은 쓸 수 없다":"취득일부터 3년이 지난 뒤에 거꾸로 감정한 가액은 취득가액으로 쓸 수 없습니다.","토지등 양도소득에 대한 법인세와 가산세":"최저한세를 계산할 때 토지등 양도소득에 대한 법인세와 가산세는 포함하지 않습니다.","토지 등 양도소득을 양도소득세 방식으로 내고 과세표준 신고를 생략할 수 있다":"수익사업이 없는 비영리 내국법인은 토지 양도소득을 양도소득세 방식으로 내면 법인세 과세표준 신고를 생략할 수 있습니다.","토지 양도소득도 과세표준 신고를 한다":"수익사업을 하는 비영리법인은 토지 양도소득도 다른 소득과 함께 법인세 과세표준을 신고해야 합니다.","통합발행 국채의 매각가액과 액면가액 차액, 판결에 따른 손해배상금의 법정이자는 이자소득이 아니다":"통합발행 국채의 매각 차익이나 판결로 받은 손해배상금의 법정이자는 이자소득의 범위에 들어가지 않습니다.","퇴직금전환금, 미지급소득세 대납액, 직원 학자금·우리사주 취득자금 대여 등":"가지급금 계산에서는 퇴직금전환금과 소득세 대납액과 직원 학자금과 우리사주 취득자금 대여 등을 뺍니다.","퇴직금 지급 지체로 받는 지연손해금, 퇴직 후 행사한 주식매수선택권 이익, 상속받은 저작권 양도대가, 계약 위약 배상금과 그 법정이자, 몰수되지 않은 뇌물은 기타소득이다":"퇴직금 지연손해금과 퇴직 후 행사한 주식매수선택권 이익과 위약 배상금과 몰수되지 않은 뇌물 등은 기타소득입니다.","퇴직급여를 미리 받으면 받은 날 퇴직한 것으로 본다":"퇴직연금제도를 폐지하고 퇴직급여를 미리 받았다면 받은 날에 퇴직한 것으로 봅니다.","퇴직소득에서 공제하는 외국납부세액의 한도초과액은 이월공제하지 않는다":"퇴직소득에서 외국납부세액을 공제할 때 한도를 넘는 금액은 다음 해로 이월해 공제하지 않습니다.","퇴직소득에서 근속연수공제를 빼고 12/근속연수를 곱해 환산급여를 구한 뒤 환산급여공제를 빼고 기본세율을 적용해 근속연수/12를 곱한다":"퇴직소득세는 근속연수공제를 뺀 뒤 연 단위로 환산해 환산급여공제와 기본세율을 적용하고 다시 근속연수만큼 환원해 계산합니다.","퇴직일 현재 연금계좌에 있는 퇴직소득은 연금외수령하기 전까지 원천징수하지 않는다":"연금계좌에 들어 있는 퇴직소득은 아직 실제로 받은 것이 아니므로 연금 외로 수령할 때까지 원천징수를 미룹니다.","투자회사 등이 경과기간분 이자·배당을 수익으로 계상하면 그 사업연도 익금이다":"투자회사 등이 이자와 배당 중 경과기간분을 수익으로 계상했다면 그 사업연도의 익금으로 봅니다.","특별법 폐지로 상법상 회사로 조직변경하면 과세하지 않으며 비영리내국법인은 청산소득 납세의무가 없다":"특별법 폐지로 상법상 회사로 조직을 바꾸는 경우는 청산소득을 과세하지 않고 비영리내국법인은 청산소득 납세의무가 없습니다.","특수관계법인에서 취득하며 상여로 처분된 금액은 취득가액에 더하고, 소유권 확보 소송비용은 다른 소득에서 필요경비로 처리한 부분을 빼고 취득가액에 넣는다":"특수관계법인에게서 취득하며 상여로 처분된 금액은 취득가액에 더하고 소송비용은 이미 비용으로 쓴 부분을 뺀 뒤 넣습니다.","특수관계법인 외의 자에게 시가보다 비싸게 팔아 증여재산가액이 있으면 양도가액에서 증여재산가액을 뺀 금액이 양도가액이다":"특수관계법인이 아닌 자에게 시가보다 비싸게 팔아 증여재산이 생기면 그 증여재산가액을 빼고 남은 금액이 양도가액입니다.","특수관계인과의 거래로 조세 부담을 부당하게 줄이면 시가로 다시 계산한다":"특수관계인과 거래하면서 조세 부담을 부당하게 줄였다면 과세관청이 그 거래를 시가로 다시 계산합니다.","특수관계인에게서 자산을 시가보다 비싸게 사면 시가 초과액을 대가 지급 사업연도별로 손금불산입(상여 등)하고 같은 금액을 손금산입(△유보)해 취득가액을 시가로 낮춘다":"비싸게 산 차액은 대가를 지급한 연도마다 손금에 넣지 않고 상여 등으로 처분하며 같은 금액을 손금산입해 취득가액을 시가로 낮춥니다.","특수관계인 외의 자에게 정당한 사유 없이 자산을 정상가액보다 낮게 양도해 실질적으로 증여한 금액도 기부금이다":"특수관계인이 아닌 사람에게 정당한 사유 없이 정상가액보다 싸게 자산을 넘겨 실질적으로 증여했다면 그 차액도 기부금으로 봅니다.","특수관계인인 개인에게서 시가보다 싸게 사면 차액이 익금이고, 국세 환급가산금은 익금이 아니다":"특수관계인인 개인에게서 시가보다 낮게 유가증권을 사면 그 차액을 익금으로 보며 환급가산금은 익금에서 제외됩니다.","특정외국법인 유보소득 간주배당과 혼성금융상품 배당":"특정외국법인의 유보소득을 배당한 것으로 보는 금액과 혼성금융상품에서 받은 배당은 익금에 산입합니다.","파산선고에 따른 처분, 직접 경작 농지의 교환·분합, 환지처분":"파산선고에 따른 처분과 직접 경작하던 농지의 교환과 분합과 환지처분은 토지등 양도소득 추가 과세에서 빠집니다.","파손·부패 등으로 정상가격에 팔 수 없으면 처분가능한 시가로 감액할 수 있다":"재고자산이 파손이나 부패로 정상가격에 팔 수 없다면 처분할 수 있는 시가까지 장부가액을 낮출 수 있습니다.","판결로 확정되면 1년 이내에 실제 사업자에게 처분할 수 있다":"명의를 빌려준 사람이 사업자가 아니라는 판결이 확정되면 1년 안에 실제 사업자에게 과세할 수 있습니다.","평가액÷(11-연금수령연차)×120%이고, 한도를 넘는 인출은 연금외수령이다":"연금수령한도는 평가액을 11에서 연금수령연차를 뺀 수로 나눈 금액의 120%이며 한도를 넘는 인출은 연금외수령입니다.","포탈세액등이 3억원 이상이면서 신고·납부할 세액의 30% 이상이거나 5억원 이상이면 3년 이하 징역 또는 3배 이하 벌금이고 징역과 벌금을 병과할 수 있으며 상습범은 형의 2분의 1을 가중한다":"포탈액이 3억원 이상이면서 30% 이상이거나 5억원 이상이면 형량이 3년과 3배로 무거워지고 상습범은 2분의 1을 더 가중합니다.","피상속인과 직계비속 상속인이 10년 이상 한 주택에서 동거하고 1세대1주택이었으면 주택가액(담보채무 차감)의 100%를 6억원 한도로 공제한다":"피상속인과 10년 이상 한집에서 동거한 직계비속이 상속받는 1세대1주택은 담보채무를 뺀 가액의 100%를 6억원까지 공제합니다.","피상속인의 소득에 대한 소득세와 상속인 자신의 소득에 대한 소득세는 구분해서 계산한다":"상속이 있으면 피상속인의 소득에 대한 소득세와 상속인 자신의 소득에 대한 소득세를 각각 따로 계산합니다.","피상속인이 거주자이면 국내외 모든 상속재산, 비거주자이면 국내에 있는 상속재산에 상속세를 매긴다":"피상속인이 거주자면 국내외 상속재산 전부에 과세하고 비거주자이면 국내에 있는 상속재산만 과세 대상입니다.","피상속인이 보험료를 낸 생명보험금, 신탁재산, 피상속인에게 지급될 퇴직금":"상속세 계산에서는 피상속인이 보험료를 낸 생명보험금과 신탁재산과 피상속인에게 지급될 퇴직금도 상속재산으로 보아 포함합니다.","피출자법인을 새로 설립하며 주식만 받으면 출자한 순자산의 시가가 주식 취득가액이다":"현물출자로 새 법인을 세우고 주식만 받으면 출자한 순자산의 시가가 받은 주식의 취득가액이 됩니다.","피합병법인의 양도손익은 없는 것으로 하고, 합병법인은 자산을 장부가액으로 양수한 것으로 보아 시가로 계상하되 시가와 장부가액의 차액은 자산조정계정으로 둔다":"적격합병이면 피합병법인에게 양도손익이 없고 합병법인은 시가와 장부가액의 차이를 자산조정계정에 따로 두어 과세를 미룹니다.","피합병법인 주식의 취득가액으로 평가한다":"합병대가를 모두 주식으로 받은 적격합병에서는 받은 주식을 피합병법인 주식의 취득가액으로 평가합니다.","한도 안에서 손금에 넣고, 손금산입한 사업연도 종료일 이후 5년이 되는 날까지 쓰지 않으면 익금에 산입한다":"준비금은 한도 안에서 손금에 넣지만 정해진 시점까지 목적 사업에 쓰지 않으면 이를 다시 익금으로 되돌립니다.","한 차례 접대에 3만원(경조금 20만원)을 넘게 쓰면서 신용카드·현금영수증·세금계산서 등 적격증빙을 받지 않은 금액은 한도 계산 전에 전액 손금불산입하고 기타사외유출로 처분한다":"한 번의 접대가 3만원을 넘는데 적격증빙이 없으면 한도 계산 전에 전부 손금불산입하고 기타사외유출로 처분하며 경조금은 20만원 기준입니다.","합병등기일이 속하는 사업연도의 다음 사업연도 개시일부터 2년(근로자 수 요건은 3년) 안이다":"적격합병의 사후관리 기간은 합병등기일이 속하는 사업연도의 다음 사업연도 개시일부터 2년이고 근로자 수 요건은 3년입니다.","합병등기일 현재 1년 이상 사업을 계속한 내국법인 간 합병이어야 하고, 합병대가 중 합병법인 주식이 80% 이상이어야 한다":"적격합병이 되려면 합병등기일 현재 1년 이상 사업한 내국법인끼리여야 하고 합병대가의 80% 이상을 합병법인 주식으로 줘야 합니다.","합병법인 등이 손금산입한 것으로 본다":"합병이나 분할로 충당금을 승계하는 경우에는 합병법인 등이 그 금액을 손금에 넣은 것으로 봅니다.","합병법인 본래 사업 소득에서만 공제한다":"합병법인 자신이 가지고 있던 결손금은 합병법인의 본래 사업에서 생긴 소득에서만 공제할 수 있습니다.","합병법인은 그 사업연도 종료일까지 승계사업을 계속하고, 합병등기일 1개월 전 근로자의 80% 이상을 승계해 사업연도 말까지 유지해야 한다":"적격합병의 요건으로 승계한 사업의 계속과 근로자 승계 비율 80%가 있고 둘 다 사업연도 말까지 이어져야 합니다.","항공기 여객운송, 도서 인쇄·제본 용역, 피부과 부설 피부관리실 용역, 음악산업법상 전자출판물, 집합투자업자가 자금을 어업권 등 실물에 운용하는 용역은 과세한다":"항공기 여객운송과 도서 인쇄와 제본 용역과 피부과 부설 피부관리실 용역 등은 면세가 아니라 과세합니다.","해당 과세기간에 생긴 결손금을 먼저 공제하고 남은 소득에서 이월결손금을 뺀다":"결손금은 먼저 그 과세기간에 생긴 것부터 공제하고 남은 소득에서 이월결손금을 이어서 뺍니다.","해산등기일부터 1년이 되는 날까지 잔여재산가액이 확정되지 않으면 하되 국유재산법상 청산절차를 밟는 법인은 하지 않는다":"해산 후 1년이 지나도 잔여재산가액이 정해지지 않으면 중간신고를 하며 국유재산법상 청산 법인은 이를 하지 않습니다.","해산등기일 현재 잔여재산을 그대로 분배하면 분배를 완료한 날이 확정일이다":"해산등기일 현재의 잔여재산을 그대로 나누어 주는 경우에는 분배를 마친 날이 잔여재산가액확정일입니다.","해외직접투자를 한 거주자·내국법인은 과세기간(사업연도) 종료일이 속하는 달의 말일부터 6개월 이내에 해외직접투자명세등을 내고 주식 양도나 청산으로 투자가 끝난 해에도 제출한다":"해외직접투자를 한 거주자와 내국법인은 과세기간 종료일이 속하는 달의 말일부터 6개월 이내에 명세를 내고 투자가 끝난 해에도 제출합니다.","행사할 수 있는 때부터 5년이다":"국세징수권과 환급금 청구권은 권리를 행사할 수 있게 된 때부터 5년이 지나면 소멸시효가 완성됩니다.","허가사업 관련 세금을 3회 이상·500만원 이상 체납하면 요구할 수 있다":"허가사업과 관련된 세금을 3회 이상 500만원 이상 체납하면 관계 기관에 사업정지를 요구할 수 있습니다.","확정급여형 퇴직연금 보험차익과 사업용 자산 손실로 받은 보험차익은 사업소득 총수입금액에 넣는다":"퇴직연금에서 난 보험차익과 사업용 자산 손실로 받은 보험금은 사업소득을 계산할 때 수입으로 잡습니다.","확정신고를 해야 할 거주자가 출국하면 출국일 전날까지 그 과세기간의 과세표준을 신고한다":"확정신고 의무가 있는 거주자가 출국하는 경우에는 출국일 전날까지 그 과세기간 과세표준을 미리 신고해야 합니다.","환가한 금액을 공급가액으로 한다":"공급시기가 되기 전에 외화를 원화로 환가했다면 환가한 금액을 공급가액으로 봅니다.","환입된 날을 작성일로 적고 비고란에 처음 작성일을 덧붙여 붉은색 글씨나 음의 표시로 발급한다":"재화가 환입되면 환입된 날을 작성일로 적고 비고란에 처음 작성일을 덧붙여 붉은색 글씨나 음의 표시로 수정세금계산서를 발급합니다.","환지처분으로 지목·지번이 바뀌는 것은 양도가 아니며, 지역권은 과세대상 자산이 아니다":"환지처분으로 지목이나 지번이 바뀌는 것은 양도가 아니며 지역권은 양도소득세 대상 자산에 들지 않습니다.","회사가 계상한 감가상각비(즉시상각의제액 포함)가 상각범위액을 넘으면 상각부인액으로 손금불산입(유보)하고, 이후 시인부족액이 생기는 해에 그 범위에서 손금으로 추인한다":"회사가 계상한 감가상각비가 상각범위액을 넘으면 그 초과액을 부인하여 유보하고 이후 시인부족액이 생기는 해에 손금으로 추인합니다.","회생계획인가 법인 등만 이후 결손금 보전에 쓰도록 이연할 수 있다":"출자전환으로 생긴 채무면제이익은 회생계획인가를 받은 법인 등만 이후 결손금 보전에 쓰도록 과세를 미룰 수 있습니다.","횡령한 처분대금, 무효인 매매로 받아 보유하는 대금처럼 위법소득도 과세하고, 나중에 형법상 몰수·추징되면 후발적 경정청구를 할 수 있다":"횡령한 대금이나 무효인 매매 대금 같은 위법소득도 과세하며 나중에 몰수나 추징되면 후발적 경정청구로 바로잡습니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
